class RuntimeFailure final : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

class GuestTransfer final {
public:
    explicit GuestTransfer(std::uint32_t address, std::uint64_t unwind_start_ns = 0u,
                           std::uint32_t exception = 0u, std::uint32_t loaded_context = 0u,
                           std::uint32_t load_call_pc = 0u)
        : address_(address), unwind_start_ns_(unwind_start_ns), exception_(exception),
          loaded_context_(loaded_context), load_call_pc_(load_call_pc) {}

    std::uint32_t address() const {
        return address_;
    }

    std::uint64_t unwind_start_ns() const { return unwind_start_ns_; }
    std::uint32_t exception() const { return exception_; }
    std::uint32_t loaded_context() const { return loaded_context_; }
    std::uint32_t load_call_pc() const { return load_call_pc_; }

private:
    std::uint32_t address_;
    std::uint64_t unwind_start_ns_;
    std::uint32_t exception_;
    std::uint32_t loaded_context_,load_call_pc_;
};

// Source-specific unwind used only by the exact exception-7 RFI path. A
// generic scheduler/OSLoadContext transfer must never be mistaken for the
// suppressed FPU instruction's same-stack retry, even if its address happens
// to match.
class FpuRetryTransfer final {
public:
    explicit FpuRetryTransfer(std::uint32_t address) : address_(address) {}

    std::uint32_t address() const {
        return address_;
    }

private:
    std::uint32_t address_;
};

// Wall-clock time alone cannot distinguish a guest thread that was executing
// without reaching a service point from one descheduled by the host. Sample
// current-thread CPU time only at bounded AI-DMA diagnostic boundaries.
std::uint64_t current_thread_cpu_time_100ns() noexcept {
    FILETIME creation{};
    FILETIME exit{};
    FILETIME kernel{};
    FILETIME user{};
    if (GetThreadTimes(
            GetCurrentThread(), &creation, &exit, &kernel, &user) == FALSE) {
        return 0u;
    }
    ULARGE_INTEGER kernel_ticks{};
    kernel_ticks.LowPart = kernel.dwLowDateTime;
    kernel_ticks.HighPart = kernel.dwHighDateTime;
    ULARGE_INTEGER user_ticks{};
    user_ticks.LowPart = user.dwLowDateTime;
    user_ticks.HighPart = user.dwHighDateTime;
    return kernel_ticks.QuadPart + user_ticks.QuadPart;
}

// Unlike GetThreadTimes, this counter is fine-grained enough to distinguish
// short callback work from a long period in which the simulation thread did
// not execute. It is diagnostic evidence only: cycle counts are intentionally
// not converted into a duration because Windows does not promise a fixed
// frequency for this API across every supported processor.
std::uint64_t current_thread_cycle_count() noexcept {
    ULONG64 cycles{};
    if (QueryThreadCycleTime(GetCurrentThread(), &cycles) == FALSE) {
        return 0u;
    }
    return static_cast<std::uint64_t>(cycles);
}

