// Guest OSContext addresses associated with live host callback/interceptor
// scopes (innermost last). Used by diagnostics and remaining legacy catch
// sites only; scheduler targets are never executed recursively from this list.
std::vector<std::uint32_t> g_live_ctx_stack;

// Retired nested-resume diagnostic. It intentionally remains empty while old
// trace formatting is removed separately from the flat scheduler correction.
std::vector<std::uint32_t> g_active_nested_ctx_stack;

thread_local std::uint64_t g_branch_checkpoint_callback_depth = 0u;
thread_local std::uint32_t g_active_branch_checkpoint_pc = 0u;

class ScopedBranchCheckpointIdentity {
public:
    explicit ScopedBranchCheckpointIdentity(std::uint32_t guest_pc)
        : previous_pc_(g_active_branch_checkpoint_pc), guest_pc_(guest_pc) {
        if (g_branch_checkpoint_callback_depth ==
            std::numeric_limits<std::uint64_t>::max()) {
            throw RuntimeFailure("branch-checkpoint callback depth overflowed");
        }
        ++g_branch_checkpoint_callback_depth;
        g_active_branch_checkpoint_pc = guest_pc_;
    }

    ~ScopedBranchCheckpointIdentity() noexcept {
        if (g_branch_checkpoint_callback_depth == 0u ||
            g_active_branch_checkpoint_pc != guest_pc_) {
            std::terminate();
        }
        --g_branch_checkpoint_callback_depth;
        g_active_branch_checkpoint_pc = previous_pc_;
    }

    ScopedBranchCheckpointIdentity(const ScopedBranchCheckpointIdentity&) =
        delete;
    ScopedBranchCheckpointIdentity& operator=(
        const ScopedBranchCheckpointIdentity&) = delete;

private:
    std::uint32_t previous_pc_{};
    std::uint32_t guest_pc_{};
};

// Trace-only record of the context most recently observed at OSSaveContext or
// OSSetCurrentContext. It does not select, defer, or repair a flat transfer.
std::uint32_t g_last_saved_ctx = 0;

std::uint32_t innermost_live_parent_context(std::uint32_t current_context) {
    for (auto it = g_live_ctx_stack.rbegin();
         it != g_live_ctx_stack.rend();
         ++it) {
        if (*it != 0u && *it != current_context) {
            return *it;
        }
    }
    return 0u;
}

constexpr std::uint32_t kGuestOsContextBytes = 0x1C4u;
// RMGE01 bring-up scaffolding: probe rosters identify these fixed
// OSThread/OSContext addresses during the current boot milestone.
constexpr std::uint32_t kRmge01MainThreadContext = 0x80650878u;
constexpr std::uint32_t kRmge01JasAudioThreadContext = 0x807ACCA0u;
constexpr std::uint32_t kRmge01SchedulerIdleContext = 0x80650C90u;

bool is_guest_scheduler_idle_context(std::uint32_t context) {
    return context == kRmge01SchedulerIdleContext;
}

bool mapped_guest_range(
    const galaxy::host::GuestAddressSpace* address_space,
    std::uint32_t address,
    std::uint32_t bytes) {
    return address_space != nullptr &&
           bytes != 0u &&
           address_space->pointer_or_null(address, bytes) != nullptr;
}

bool valid_guest_os_context(
    const galaxy::host::GuestAddressSpace* address_space,
    std::uint32_t context_address) {
    return context_address != 0u &&
           mapped_guest_range(
               address_space, context_address, kGuestOsContextBytes);
}

bool guest_context_is_active_thread_base(
    const galaxy::host::GuestAddressSpace* address_space,
    std::uint32_t context_address) {
    if (address_space == nullptr ||
        context_address < 0x80000000u ||
        context_address >= 0x82000000u) {
        return false;
    }

    constexpr std::uint32_t kActiveThreadQueueHead = 0x800000DCu;
    constexpr std::uint32_t kActiveThreadNextOffset = 0x2FCu;
    std::uint32_t thread = address_space->read_u32(kActiveThreadQueueHead);
    for (int i = 0; i < 64 &&
            thread >= 0x80000000u && thread < 0x82000000u; ++i) {
        if (thread == context_address) {
            return true;
        }
        thread = address_space->read_u32(thread + kActiveThreadNextOffset);
    }
    return false;
}

