struct PerformanceStartSemanticState {
    bool captured{};
    PerformanceActorSemanticSample start{};
    static constexpr std::size_t kCanonicalCapacity = 2048u;
    std::array<char, kCanonicalCapacity> canonical{};
    std::size_t canonical_size{};
    bool canonical_sealed{};
    std::string sha256;
};

std::string sha256_ascii_upper_hex(std::span<const char> text) {
    if (text.size() > std::numeric_limits<ULONG>::max()) {
        throw RuntimeFailure("native performance semantic state is too large");
    }

    BCRYPT_ALG_HANDLE algorithm = nullptr;
    BCRYPT_HASH_HANDLE hash = nullptr;
    ULONG object_size = 0;
    ULONG hash_size = 0;
    ULONG result_size = 0;
    if (BCryptOpenAlgorithmProvider(
            &algorithm, BCRYPT_SHA256_ALGORITHM, nullptr, 0) < 0 ||
        BCryptGetProperty(
            algorithm,
            BCRYPT_OBJECT_LENGTH,
            reinterpret_cast<PUCHAR>(&object_size),
            sizeof(object_size),
            &result_size,
            0) < 0 ||
        BCryptGetProperty(
            algorithm,
            BCRYPT_HASH_LENGTH,
            reinterpret_cast<PUCHAR>(&hash_size),
            sizeof(hash_size),
            &result_size,
            0) < 0 ||
        hash_size != 32u) {
        if (algorithm != nullptr) {
            BCryptCloseAlgorithmProvider(algorithm, 0);
        }
        throw RuntimeFailure(
            "failed to initialize native performance semantic-state SHA-256");
    }

    std::vector<UCHAR> object(object_size);
    std::array<UCHAR, 32> digest{};
    const NTSTATUS create_status = BCryptCreateHash(
        algorithm, &hash, object.data(), object_size, nullptr, 0, 0);
    const NTSTATUS data_status =
        create_status < 0
            ? create_status
            : BCryptHashData(
                  hash,
                  reinterpret_cast<PUCHAR>(
                      const_cast<char*>(text.data())),
                  static_cast<ULONG>(text.size()),
                  0);
    const NTSTATUS finish_status =
        data_status < 0
            ? data_status
            : BCryptFinishHash(
                  hash, digest.data(), static_cast<ULONG>(digest.size()), 0);
    if (hash != nullptr) {
        BCryptDestroyHash(hash);
    }
    BCryptCloseAlgorithmProvider(algorithm, 0);
    if (finish_status < 0) {
        throw RuntimeFailure(
            "native performance semantic-state SHA-256 failed");
    }

    std::ostringstream output;
    output << std::hex << std::uppercase << std::setfill('0');
    for (const UCHAR byte : digest) {
        output << std::setw(2) << static_cast<unsigned int>(byte);
    }
    return output.str();
}

void append_performance_semantic_literal(
    PerformanceStartSemanticState& state,
    std::string_view value) {
    if (state.canonical_sealed ||
        value.size() > state.canonical.size() - state.canonical_size) {
        throw RuntimeFailure(
            "native performance semantic-state canonical buffer overflowed");
    }
    std::copy(
        value.begin(),
        value.end(),
        state.canonical.begin() +
            static_cast<std::ptrdiff_t>(state.canonical_size));
    state.canonical_size += value.size();
}

void append_performance_semantic_hex_field(
    PerformanceStartSemanticState& state,
    std::string_view name,
    std::uint32_t value) {
    append_performance_semantic_literal(state, name);
    append_performance_semantic_literal(state, "=");
    constexpr char kHex[] = "0123456789abcdef";
    std::array<char, 8> encoded{};
    for (std::size_t index = 0u; index < encoded.size(); ++index) {
        const unsigned shift =
            static_cast<unsigned>((encoded.size() - 1u - index) * 4u);
        encoded[index] = kHex[(value >> shift) & 0xFu];
    }
    append_performance_semantic_literal(
        state, std::string_view(encoded.data(), encoded.size()));
    append_performance_semantic_literal(state, "\n");
}

void append_performance_semantic_register_field(
    PerformanceStartSemanticState& state,
    std::uint32_t chosen_register) {
    append_performance_semantic_literal(state, "anchorChosenRegister=");
    if (chosen_register == 3u) {
        append_performance_semantic_literal(state, "3\n");
    } else if (chosen_register == 31u) {
        append_performance_semantic_literal(state, "31\n");
    } else if (chosen_register == 30u) {
        append_performance_semantic_literal(state, "30\n");
    } else {
        throw RuntimeFailure(
            "native performance semantic-state chosen register is invalid");
    }
}

void append_performance_semantic_sample(
    PerformanceStartSemanticState& state,
    std::string_view prefix,
    const PerformanceActorSemanticSample& sample) {
    std::array<char, 64> field{};
    const auto append = [&](std::string_view suffix, std::uint32_t value) {
        if (prefix.size() + suffix.size() > field.size()) {
            throw RuntimeFailure(
                "native performance semantic-state field name overflowed");
        }
        const auto end = std::copy(prefix.begin(), prefix.end(), field.begin());
        const auto suffix_end = std::copy(suffix.begin(), suffix.end(), end);
        append_performance_semantic_hex_field(
            state,
            std::string_view(
                field.data(),
                static_cast<std::size_t>(suffix_end - field.begin())),
            value);
    };
    append("MarioSelf", sample.mario_self);
    append("PositionXBits", sample.position_bits[0]);
    append("PositionYBits", sample.position_bits[1]);
    append("PositionZBits", sample.position_bits[2]);
    append("VelocityXBits", sample.velocity_bits[0]);
    append("VelocityYBits", sample.velocity_bits[1]);
    append("VelocityZBits", sample.velocity_bits[2]);
    append("PreviousPositionXBits", sample.previous_position_bits[0]);
    append("PreviousPositionYBits", sample.previous_position_bits[1]);
    append("PreviousPositionZBits", sample.previous_position_bits[2]);
}

std::uint64_t file_time_ticks(const FILETIME& value) noexcept {
    ULARGE_INTEGER ticks{};
    ticks.LowPart = value.dwLowDateTime;
    ticks.HighPart = value.dwHighDateTime;
    return ticks.QuadPart;
}

ProcessTimesSnapshot query_current_process_times() {
    FILETIME creation{};
    FILETIME exit{};
    FILETIME kernel{};
    FILETIME user{};
    if (GetProcessTimes(
            GetCurrentProcess(), &creation, &exit, &kernel, &user) == FALSE) {
        throw RuntimeFailure(
            "GetProcessTimes failed for the native performance window (error " +
            std::to_string(GetLastError()) + ")");
    }
    return ProcessTimesSnapshot{
        file_time_ticks(user),
        file_time_ticks(kernel),
    };
}


template <typename Function>
Function load_export(HMODULE module, const char* name) {
    auto* address = GetProcAddress(module, name);
    if (address == nullptr) {
        throw RuntimeFailure(std::string("native module is missing export ") + name);
    }
    return reinterpret_cast<Function>(address);
}

std::string hexadecimal(std::uint32_t value) {
    std::ostringstream output;
    output << "0x" << std::hex << std::uppercase << std::setfill('0') << std::setw(8)
           << value;
    return output.str();
}

// ── Cooperative fiber scheduler ─────────────────────────────────────────
std::string format_context_stack(const std::vector<std::uint32_t>& stack) {
    std::ostringstream output;
    output << '[';
    for (std::size_t i = 0; i < stack.size(); ++i) {
        if (i != 0u) {
            output << ',';
        }
        output << hexadecimal(stack[i]);
    }
    output << ']';
    return output.str();
}

// Provides concurrent Wii OS execution on a single native thread.
// Virtual threads yield via GuestTransfer; the IOS thread runs as a
// native event pump that processes hardware completions.

enum class ThreadState { Running, Ready, Sleeping };

struct VirtualThread {
    galaxy::PpcContext ctx{};
    std::uint32_t stack_base{};
    ThreadState state{ThreadState::Ready};
    std::uint32_t wait_queue_ptr{};
};

