    [[nodiscard]] static std::size_t lookup_cache_index(
        std::uint32_t address) {
        const std::uint32_t word_address = address >> 2u;
        const std::uint32_t mixed =
            word_address ^ (word_address >> 7u) ^ (word_address >> 13u);
        return static_cast<std::size_t>(mixed) & (kLookupCacheSize - 1u);
    }

    [[nodiscard]] galaxy::NativeGameFunction lookup_function(
        std::uint32_t address) const {
        if (lookup == nullptr) {
            return nullptr;
        }
        LookupCacheEntry& entry = lookup_cache[lookup_cache_index(address)];
        if (trace_lookup_cache) {
            ++lookup_cache_queries;
        }
        if (entry.valid && entry.address == address) {
            if (trace_lookup_cache) {
                ++lookup_cache_hits;
            }
            return entry.function;
        }

        if (trace_lookup_cache) {
            ++lookup_cache_misses;
            if (entry.valid) {
                ++lookup_cache_collisions;
            }
        }
        galaxy::NativeGameFunction function = lookup(address);
        if (trace_lookup_cache && function == nullptr) {
            ++lookup_cache_null_results;
        }
        entry.address = address;
        entry.function = function;
        entry.valid = true;
        return function;
    }

    void dump_lookup_cache_summary(std::ostream& output) const {
        if (!trace_lookup_cache) {
            return;
        }
        std::size_t occupied = 0;
        for (const LookupCacheEntry& entry : lookup_cache) {
            if (entry.valid) {
                ++occupied;
            }
        }
        const double hit_rate =
            lookup_cache_queries != 0u
                ? static_cast<double>(lookup_cache_hits) * 100.0 /
                      static_cast<double>(lookup_cache_queries)
                : 0.0;
        output << "[lookup-cache] queries=" << lookup_cache_queries
               << " hits=" << lookup_cache_hits
               << " misses=" << lookup_cache_misses
               << " hitRate=" << std::fixed << std::setprecision(2)
               << hit_rate << std::defaultfloat
               << "% collisions=" << lookup_cache_collisions
               << " nullResults=" << lookup_cache_null_results
               << " occupied=" << occupied << '/' << kLookupCacheSize
               << '\n';
    }

    void reset_call_profiles() {
        call_profile.clear();
        call_time_profile.clear();
        call_self_time_profile.clear();
        const std::uint64_t now = __rdtsc();
        for (ActiveCallTimeFrame& frame : call_time_stack) {
            frame.start_cycles = now;
            frame.child_cycles = 0u;
        }
        next_call_profile = call_count + 10'000'000u;
        next_call_time_profile = call_count + 10'000'000u;
    }

    void dump_call_profile(std::ostream& output, const char* label) const {
        std::vector<std::pair<std::uint32_t, std::uint64_t>> calls(
            call_profile.begin(), call_profile.end());
        std::sort(
            calls.begin(),
            calls.end(),
            [](const auto& left, const auto& right) {
                return left.second > right.second;
            });
        output << label;
        const std::size_t limit = std::min<std::size_t>(calls.size(), 100);
        for (std::size_t index = 0; index < limit; ++index) {
            output << ' ' << hexadecimal(calls[index].first)
                   << '=' << calls[index].second;
        }
        output << '\n';
    }

    void dump_call_time_samples(
        std::ostream& output,
        const char* label,
        const std::unordered_map<std::uint32_t, CallTimeSample>& profile)
        const {
        std::vector<std::pair<std::uint32_t, CallTimeSample>> samples(
            profile.begin(), profile.end());
        std::sort(
            samples.begin(),
            samples.end(),
            [](const auto& left, const auto& right) {
                return left.second.cycles > right.second.cycles;
            });
        output << label;
        const std::size_t limit = std::min<std::size_t>(samples.size(), 100);
        for (std::size_t index = 0; index < limit; ++index) {
            const CallTimeSample& sample = samples[index].second;
            const std::uint64_t average =
                sample.samples != 0 ? sample.cycles / sample.samples : 0;
            output << ' ' << hexadecimal(samples[index].first)
                   << '=' << sample.cycles << '/' << sample.samples
                   << '/' << average;
        }
        output << '\n';
    }

    void dump_call_time_profile(std::ostream& output, const char* label) const {
        dump_call_time_samples(output, label, call_time_profile);
    }

    void dump_call_self_time_profile(
        std::ostream& output,
        const char* label) const {
        dump_call_time_samples(output, label, call_self_time_profile);
    }

    void record_call(std::uint32_t address) {
        ++call_count;
        pc_history[pc_history_pos % pc_history.size()] = address;
        ++pc_history_pos;
        trace_guest_call(address);
        if (!profile_calls && !profile_call_time && !profile_call_self_time &&
            !trace_calls &&
            max_calls == 0) {
            return;
        }
        if (profile_calls) {
            ++call_profile[address];
            if (call_count >= next_call_profile) {
                std::ostringstream label;
                label << "[call-profile] calls=" << call_count;
                dump_call_profile(std::cerr, label.str().c_str());
                call_profile.clear();
                next_call_profile += 10'000'000u;
            }
        }
        if ((profile_call_time || profile_call_self_time) &&
            call_count >= next_call_time_profile) {
            std::ostringstream label;
            label << std::dec << " calls=" << call_count;
            if (profile_call_time) {
                dump_call_time_profile(
                    std::cerr,
                    ("[call-time-profile]" + label.str()).c_str());
            }
            if (profile_call_self_time) {
                dump_call_self_time_profile(
                    std::cerr,
                    ("[call-self-time-profile]" + label.str()).c_str());
            }
            call_time_profile.clear();
            call_self_time_profile.clear();
            next_call_time_profile += 10'000'000u;
        }
        if (trace_calls) {
            std::cerr << "[call " << call_count << "] " << hexadecimal(address) << '\n';
        }
        if (max_calls != 0 && call_count > max_calls) {
            throw RuntimeFailure("native boot call budget reached");
        }
    }

    void load_guest_trace_filter() {
        trace_guest_filter_loaded = true;
        trace_guest_log_limit =
            read_env_u64("GALAXY_TRACE_GUEST_ADDRS_LIMIT", 512u);

        char value[2048]{};
        std::size_t length = 0;
        if (getenv_s(&length, value, sizeof(value),
                     "GALAXY_TRACE_GUEST_ADDRS") != 0 ||
            length <= 1) {
            return;
        }

        const std::string script(value);
        std::size_t offset = 0;
        while (offset <= script.size()) {
            const std::size_t sep =
                script.find_first_of(",; \t\r\n", offset);
            const std::string token =
                sep == std::string::npos
                    ? script.substr(offset)
                    : script.substr(offset, sep - offset);
            if (!token.empty()) {
                char* end = nullptr;
                const unsigned long parsed =
                    std::strtoul(token.c_str(), &end, 0);
                if (end != token.c_str() && *end == '\0') {
                    trace_guest_addresses.push_back(
                        static_cast<std::uint32_t>(parsed));
                } else {
                    std::cerr << "[guest-trace] ignoring address token \""
                              << token << "\"\n";
                }
            }
            if (sep == std::string::npos) {
                break;
            }
            offset = sep + 1;
        }

        std::sort(
            trace_guest_addresses.begin(), trace_guest_addresses.end());
        trace_guest_addresses.erase(
            std::unique(
                trace_guest_addresses.begin(), trace_guest_addresses.end()),
            trace_guest_addresses.end());

        if (!trace_guest_addresses.empty()) {
            std::cerr << "[guest-trace] tracing";
            for (const std::uint32_t address : trace_guest_addresses) {
                std::cerr << ' ' << hexadecimal(address);
            }
            std::cerr << " limit=" << trace_guest_log_limit << '\n';
        }
    }

    void trace_guest_call(std::uint32_t address) {
        if (!trace_guest_filter_loaded) {
            load_guest_trace_filter();
        }
        if (trace_guest_addresses.empty() ||
            !std::binary_search(
                trace_guest_addresses.begin(),
                trace_guest_addresses.end(),
                address)) {
            return;
        }
        std::uint64_t& hits = trace_guest_hits[address];
        ++hits;
        if (hits > trace_guest_log_limit) {
            return;
        }
        std::cerr << "[guest-trace] vi=" << vi_retrace_count
                  << " call=" << hexadecimal(address)
                  << " hit=" << hits
                  << " total-calls=" << call_count << '\n';
    }

    void record_call_time(std::uint32_t address, std::uint64_t cycles) {
        CallTimeSample& sample = call_time_profile[address];
        sample.cycles += cycles;
        ++sample.samples;
    }

    void begin_call_self_time(std::uint32_t address) {
        call_time_stack.push_back(
            ActiveCallTimeFrame{address, __rdtsc(), 0u});
    }

    void end_call_self_time(std::uint32_t address) {
        if (call_time_stack.empty() ||
            call_time_stack.back().address != address) {
            throw RuntimeFailure(
                "call self-time stack mismatch at " + hexadecimal(address));
        }

        ActiveCallTimeFrame frame = call_time_stack.back();
        call_time_stack.pop_back();
        const std::uint64_t elapsed = __rdtsc() - frame.start_cycles;
        const std::uint64_t self_cycles =
            elapsed >= frame.child_cycles ? elapsed - frame.child_cycles : 0u;
        CallTimeSample& sample = call_self_time_profile[address];
        sample.cycles += self_cycles;
        ++sample.samples;
        if (!call_time_stack.empty()) {
            call_time_stack.back().child_cycles += elapsed;
        }
    }

    void cancel_call_self_time(std::uint32_t address) noexcept {
        if (!call_time_stack.empty() &&
            call_time_stack.back().address == address) {
            call_time_stack.pop_back();
            return;
        }
        call_time_stack.clear();
    }

    std::string trace() const {
        std::ostringstream output;
        output << "Recent translated calls:";
        const std::size_t count =
            std::min<std::size_t>(pc_history_pos, pc_history.size());
        const std::size_t start =
            pc_history_pos >= pc_history.size()
                ? pc_history_pos % pc_history.size()
                : 0;
        for (std::size_t index = 0; index < count; ++index) {
            output << ' '
                   << hexadecimal(
                          pc_history[
                              (start + index) % pc_history.size()]);
        }
        return output.str();
    }

    void print_recent_reverse(
        std::ostream& output, std::size_t limit) const {
        const std::size_t count = std::min<std::size_t>(
            std::min<std::size_t>(pc_history_pos, pc_history.size()),
            limit);
        for (std::size_t index = 0; index < count; ++index) {
            const std::size_t slot =
                (pc_history_pos - 1u - index) % pc_history.size();
            output << ' ' << std::hex << pc_history[slot] << std::dec;
        }
    }

    std::string null_call_trace(const galaxy::PpcContext& ctx) const {
        std::ostringstream o;
        o << "Last 16 calls (oldest first):";
        for (std::size_t i = 0; i < 16; ++i) {
            const std::size_t idx = (pc_history_pos + i) % 16;
            o << ' ' << hexadecimal(pc_history[idx]);
        }
        o << "\n  lr=" << hexadecimal(ctx.lr)
          << " r3=" << hexadecimal(ctx.gpr[3])
          << " r4=" << hexadecimal(ctx.gpr[4])
          << " r5=" << hexadecimal(ctx.gpr[5])
          << " cr=" << hexadecimal(ctx.cr);
        // The Home Button loader resolves its seven exported callbacks through
        // the RSO header and then writes them to the small-data slots below.
        // This is failure-only evidence: it never changes the loader's
        // decisions, and lets a null callback distinguish a bad RSO export
        // table from an unrelated indirect call.
        if (ctx.lr == 0x80362458u && address_space != nullptr) {
            constexpr std::uint32_t kHomeButtonCallbackSlots = 0x806A2560u;
            constexpr std::uint32_t kHomeButtonCallbackCount = 7u;
            constexpr std::uint32_t kRsoExportTableOffset = 0x40u;
            constexpr std::uint32_t kRsoExportCountOffset = 0x44u;
            constexpr std::uint32_t kRsoExportBaseOffset = 0x48u;
            constexpr std::uint32_t kRsoExportStride = 0x10u;

            const auto read_u32_or_zero = [this](std::uint32_t address) {
                return address_space->pointer_or_null(address, 4u) != nullptr
                    ? address_space->read_u32(address)
                    : 0u;
            };
            o << "\n  home-button callbacks:";
            for (std::uint32_t index = 0u;
                 index < kHomeButtonCallbackCount;
                 ++index) {
                const std::uint32_t slot =
                    kHomeButtonCallbackSlots + index * sizeof(std::uint32_t);
                o << ' ' << hexadecimal(slot) << '='
                  << hexadecimal(read_u32_or_zero(slot));
            }

            const std::uint32_t rso_base = home_button_rso_base;
            const std::uint32_t export_table =
                read_u32_or_zero(rso_base + kRsoExportTableOffset);
            const std::uint32_t export_count =
                read_u32_or_zero(rso_base + kRsoExportCountOffset);
            const std::uint32_t export_base =
                read_u32_or_zero(rso_base + kRsoExportBaseOffset);
            o << "\n  home-button rso-base=" << hexadecimal(rso_base)
              << " exports=" << hexadecimal(export_table)
              << " count=" << hexadecimal(export_count)
              << " export-base=" << hexadecimal(export_base);
            if (export_table != 0u &&
                address_space->pointer_or_null(
                    export_table,
                    kHomeButtonCallbackCount * kRsoExportStride) != nullptr) {
                o << "\n  home-button export-records:";
                for (std::uint32_t index = 0u;
                     index < kHomeButtonCallbackCount;
                     ++index) {
                    const std::uint32_t record =
                        export_table + index * kRsoExportStride;
                    o << " [" << index
                      << ":name="
                      << hexadecimal(read_u32_or_zero(record))
                      << ",offset="
                      << hexadecimal(read_u32_or_zero(record + 4u))
                      << ",section="
                      << hexadecimal(read_u32_or_zero(record + 8u))
                      << ",aux="
                      << hexadecimal(read_u32_or_zero(record + 12u)) << ']';
                }
            }
        }
        return o.str();
    }

    std::string loop_trace() const {
        std::vector<std::pair<std::uint32_t, std::uint64_t>> sites(
            loop_sites.begin(), loop_sites.end());
        std::sort(
            sites.begin(),
            sites.end(),
            [](const auto& left, const auto& right) {
                return left.second > right.second;
            });
        std::ostringstream output;
        output << "Hottest backward branches:";
        const std::size_t limit = std::min<std::size_t>(sites.size(), 8);
        for (std::size_t index = 0; index < limit; ++index) {
            output << ' ' << hexadecimal(sites[index].first) << '='
                   << sites[index].second;
        }
        return output.str();
    }

