std::uint64_t read_env_u64(const char* name, std::uint64_t fallback) {
    char value[32]{};
    std::size_t length = 0;
    if (getenv_s(&length, value, sizeof(value), name) != 0 || length <= 1) {
        return fallback;
    }
    return std::strtoull(value, nullptr, 10);
}

bool env_value_present(const char* name) {
    std::size_t length = 0;
    return getenv_s(&length, nullptr, 0u, name) == 0 && length > 1u;
}

std::uint32_t read_env_u32_auto(const char* name, std::uint32_t fallback) {
    char value[32]{};
    std::size_t length = 0;
    if (getenv_s(&length, value, sizeof(value), name) != 0 || length <= 1) {
        return fallback;
    }
    return static_cast<std::uint32_t>(std::strtoul(value, nullptr, 0));
}

bool read_env_flag(const char* name, bool fallback) {
    char value[16]{};
    std::size_t length = 0;
    if (getenv_s(&length, value, sizeof(value), name) != 0 || length <= 1) {
        return fallback;
    }
    char normalized[16]{};
    const std::size_t count =
        std::min<std::size_t>(length - 1u, sizeof(normalized) - 1u);
    for (std::size_t i = 0; i < count; ++i) {
        normalized[i] = static_cast<char>(
            std::tolower(static_cast<unsigned char>(value[i])));
    }
    if (std::strcmp(normalized, "0") == 0 ||
        std::strcmp(normalized, "false") == 0 ||
        std::strcmp(normalized, "no") == 0 ||
        std::strcmp(normalized, "off") == 0) {
        return false;
    }
    if (std::strcmp(normalized, "1") == 0 ||
        std::strcmp(normalized, "true") == 0 ||
        std::strcmp(normalized, "yes") == 0 ||
        std::strcmp(normalized, "on") == 0) {
        return true;
    }
    return fallback;
}

std::FILE* flight_recorder_file() {
    static std::FILE* file = []() -> std::FILE* {
        char path[4096]{};
        std::size_t length = 0;
        const bool has_path =
            getenv_s(
                &length,
                path,
                sizeof(path),
                "GALAXY_FLIGHT_RECORDER_PATH") == 0 &&
            length > 1u;
        if (!has_path && !read_env_flag("GALAXY_FLIGHT_RECORDER", false)) {
            return nullptr;
        }

        std::FILE* out = nullptr;
        const char* resolved_path =
            has_path ? path : "galaxy_flight_recorder.log";
        if (fopen_s(&out, resolved_path, "w") != 0 || out == nullptr) {
            std::cerr << "[flight-recorder] unable to open "
                      << resolved_path << '\n';
            return nullptr;
        }
        static std::array<char, 1024 * 1024> buffer{};
        (void)std::setvbuf(out, buffer.data(), _IOFBF, buffer.size());
        std::fprintf(out, "[flight] version=1\n");
        std::fflush(out);
        return out;
    }();
    return file;
}

void flush_flight_recorder_periodically(std::FILE* file) {
    static std::uint64_t s_lines = 0;
    ++s_lines;
    if ((s_lines % 120u) == 0u) {
        std::fflush(file);
    }
}

void flight_record_config(
    const galaxy::gx::RenderConfig& config,
    const galaxy::gx::GxTimingConfig& timing) {
    std::FILE* file = flight_recorder_file();
    if (file == nullptr) {
        return;
    }
    std::fprintf(
        file,
        "[flight] event=config host_ms=%llu efb_scale=%u "
        "window=%ux%u vsync=%u wait_latency=%u swap_latency=%u "
        "flip_discard=%u allow_tearing=%u async_render=%u "
        "queue_depth=%llu vi_fifo_wait=%u pe_gpu_fence=%u "
        "live_memory_wait=%u memory_snapshot=%u "
        "fast_thp=%u mipmaps=%u aniso=%u lod_bias=%u input_mode=%s\n",
        static_cast<unsigned long long>(host_qpc_milliseconds()),
        config.efb_scale,
        config.window_width,
        config.window_height,
        config.vsync_interval,
        config.wait_for_frame_latency ? 1u : 0u,
        config.swap_chain_frame_latency,
        config.flip_discard ? 1u : 0u,
        config.allow_tearing ? 1u : 0u,
        read_env_flag("GALAXY_ASYNC_RENDER_THREAD", true) ? 1u : 0u,
        static_cast<unsigned long long>(timing.render_queue_depth),
        timing.vi_render_fifo_wait ? 1u : 0u,
        timing.pe_events_gpu_fence ? 1u : 0u,
        timing.render_live_memory_wait ? 1u : 0u,
        timing.render_memory_snapshot ? 1u : 0u,
        read_env_flag("GALAXY_FAST_THP_CHECKPOINTS", true) ? 1u : 0u,
        config.enhanced_mipmaps ? 1u : 0u,
        config.anisotropic_filtering,
        config.texture_lod_bias,
        galaxy::runtime_input_mode_name(
            galaxy::get_runtime_settings().input_mode));
    std::fflush(file);
}

void flight_record_vi(
    const RuntimeState& state,
    std::size_t fifo_size,
    bool rendered_retrace_frame,
    bool present_this_vi,
    std::uint32_t displayed_xfb_addr,
    std::uint64_t xfb_copies_before_render,
    std::uint64_t xfb_copies_after_present,
    const galaxy::gx::XfbPresentStats& stats) {
    std::FILE* file = flight_recorder_file();
    if (file == nullptr) {
        return;
    }
    static std::uint64_t s_last_host_ms = 0;
    const std::uint64_t host_ms = host_qpc_milliseconds();
    const std::uint64_t delta_ms =
        s_last_host_ms == 0u || host_ms < s_last_host_ms
            ? 0u
            : host_ms - s_last_host_ms;
    s_last_host_ms = host_ms;
    const std::uint64_t xfb_delta =
        xfb_copies_after_present >= xfb_copies_before_render
            ? xfb_copies_after_present - xfb_copies_before_render
            : 0u;

    std::uint32_t xfb_manager = 0u;
    std::uint32_t xfb_buffer_num = 0u;
    std::int32_t xfb_drawing = -1;
    std::int32_t xfb_drawn = -1;
    std::int32_t xfb_displaying = -1;
    std::uint32_t xfb_slot0 = 0u;
    std::uint32_t xfb_slot1 = 0u;
    std::uint32_t xfb_slot2 = 0u;
    std::uint32_t framework = 0u;
    std::int32_t framework_retraces = -1;
    std::uint32_t framework_tick_duration = 0u;
    std::uint32_t framework_render_interval = 0u;
    std::uint32_t framework_render_counter = 0u;
    std::uint32_t framework_do_render = 0u;
    std::uint32_t jut_video_message_used = 0u;
    if (state.address_space != nullptr) {
        const auto& address_space = *state.address_space;
        const auto mapped = [&](std::uint32_t address, std::uint32_t bytes) {
            return address >= 0x80000000u && address < 0x94000000u &&
                   address_space.pointer_or_null(address, bytes) != nullptr;
        };
        const auto read_s16_be = [&](std::uint32_t address) {
            const std::uint32_t word = address_space.read_u32(address & ~3u);
            const unsigned shift = (address & 2u) == 0u ? 16u : 0u;
            return static_cast<std::int32_t>(
                static_cast<std::int16_t>((word >> shift) & 0xFFFFu));
        };
        const auto read_u8_be = [&](std::uint32_t address) {
            const std::uint32_t word = address_space.read_u32(address & ~3u);
            return static_cast<std::uint32_t>(
                (word >> (24u - 8u * (address & 3u))) & 0xFFu);
        };

        constexpr std::uint32_t kJutVideoManagerPtr = 0x806A2850u;
        constexpr std::uint32_t kJutVideoMessageQueueOffset = 0x38u;
        constexpr std::uint32_t kMqUsedCount = 0x1Cu;
        constexpr std::uint32_t kJutXfbManagerPtr = 0x806A2868u;
        constexpr std::uint32_t kMainLoopFrameworkManagerPtr = 0x806A2500u;

        xfb_manager = address_space.read_u32(kJutXfbManagerPtr);
        if (mapped(xfb_manager, 0x20u)) {
            xfb_buffer_num = address_space.read_u32(xfb_manager + 0x10u);
            xfb_drawing = read_s16_be(xfb_manager + 0x14u);
            xfb_drawn = read_s16_be(xfb_manager + 0x16u);
            xfb_displaying = read_s16_be(xfb_manager + 0x18u);
            xfb_slot0 = address_space.read_u32(xfb_manager + 0x00u);
            xfb_slot1 = address_space.read_u32(xfb_manager + 0x04u);
            xfb_slot2 = address_space.read_u32(xfb_manager + 0x08u);
        }

        framework = address_space.read_u32(kMainLoopFrameworkManagerPtr);
        if (mapped(framework, 0x38u)) {
            framework_retraces = read_s16_be(framework + 0x10u);
            framework_tick_duration = address_space.read_u32(framework + 0x14u);
            framework_render_interval =
                address_space.read_u32(framework + 0x2Cu);
            framework_render_counter =
                address_space.read_u32(framework + 0x30u);
            framework_do_render = read_u8_be(framework + 0x34u);
        }

        const std::uint32_t jut_video_manager =
            address_space.read_u32(kJutVideoManagerPtr);
        const std::uint32_t jut_video_mq =
            jut_video_manager + kJutVideoMessageQueueOffset;
        if (mapped(jut_video_mq, kMqUsedCount + sizeof(std::uint32_t))) {
            jut_video_message_used =
                address_space.read_u32(jut_video_mq + kMqUsedCount);
        }
    }

    std::fprintf(
        file,
        "[flight] event=vi host_ms=%llu host_delta_ms=%llu guest_exec_us=%llu "
        "vi=%llu "
        "fifo_bytes=%zu rendered=%u present=%u displayed_xfb=0x%08X "
        "xfb_manager=0x%08X xfb_buffers=%u xfb_drawing=%d "
        "xfb_drawn=%d xfb_displaying=%d xfb_slot0=0x%08X "
        "xfb_slot1=0x%08X xfb_slot2=0x%08X "
        "framework=0x%08X framework_retraces=%d "
        "framework_tick_duration=%u framework_render_interval=%u "
        "framework_render_counter=%u framework_do_render=%u "
        "jut_video_message_used=%u "
        "xfb_copies_before=%llu xfb_copies_after=%llu xfb_delta=%llu "
        "requests=%llu presented=%llu first_serial_presentations=%llu "
        "misses=%llu "
        "stale_fallbacks=%llu missing_fallbacks=%llu stale_preserved=%llu "
        "missing_preserved=%llu repeated_or_stale_serial_requests=%llu "
        "skipped_duplicates=%llu "
        "duplicate_run_max=%llu "
        "out_of_order_serial_requests=%llu serial_delta0=%llu "
        "serial_delta1=%llu serial_delta_multi=%llu "
        "last_presented_xfb=0x%08X last_presented_serial=%llu "
        "last_presented_stamp=%llu "
        "stale_vi_preserves=%llu near_due_retries=%llu "
        "near_due_waits=%llu checkpoints=%llu\n",
        static_cast<unsigned long long>(host_ms),
        static_cast<unsigned long long>(delta_ms),
        static_cast<unsigned long long>(state.last_guest_exec_us),
        static_cast<unsigned long long>(state.vi_retrace_count),
        fifo_size,
        rendered_retrace_frame ? 1u : 0u,
        present_this_vi ? 1u : 0u,
        displayed_xfb_addr,
        xfb_manager,
        xfb_buffer_num,
        xfb_drawing,
        xfb_drawn,
        xfb_displaying,
        xfb_slot0,
        xfb_slot1,
        xfb_slot2,
        framework,
        framework_retraces,
        framework_tick_duration,
        framework_render_interval,
        framework_render_counter,
        framework_do_render,
        jut_video_message_used,
        static_cast<unsigned long long>(xfb_copies_before_render),
        static_cast<unsigned long long>(xfb_copies_after_present),
        static_cast<unsigned long long>(xfb_delta),
        static_cast<unsigned long long>(stats.requests),
        static_cast<unsigned long long>(stats.presented),
        static_cast<unsigned long long>(stats.first_serial_presentations),
        static_cast<unsigned long long>(stats.misses),
        static_cast<unsigned long long>(stats.stale_fallbacks),
        static_cast<unsigned long long>(stats.missing_fallbacks),
        static_cast<unsigned long long>(stats.stale_preserved),
        static_cast<unsigned long long>(stats.missing_preserved),
        static_cast<unsigned long long>(
            stats.repeated_or_stale_serial_requests),
        static_cast<unsigned long long>(stats.skipped_duplicate_presents),
        static_cast<unsigned long long>(stats.duplicate_run_max),
        static_cast<unsigned long long>(stats.out_of_order_serial_requests),
        static_cast<unsigned long long>(stats.serial_delta_zero),
        static_cast<unsigned long long>(stats.serial_delta_one),
        static_cast<unsigned long long>(stats.serial_delta_multi),
        stats.last_presented_xfb_addr,
        static_cast<unsigned long long>(stats.last_presented_copy_serial),
        static_cast<unsigned long long>(stats.last_presented_frame_stamp),
        static_cast<unsigned long long>(state.stale_displaying_xfb_preserves),
        static_cast<unsigned long long>(state.realtime_vi_near_due_retries),
        static_cast<unsigned long long>(state.realtime_vi_near_due_waits),
        static_cast<unsigned long long>(state.checkpoint_count));
    flush_flight_recorder_periodically(file);
}

