bool trace_guest_u32(
    const RuntimeState& state,
    std::uint32_t address,
    std::uint32_t& out) {
    if (state.address_space == nullptr || address < 0x80000000u ||
        address > 0x817FFFFCu) {
        return false;
    }
    try {
        out = state.address_space->read_u32(address);
        return true;
    } catch (...) {
        return false;
    }
}

bool trace_guest_u16(
    const RuntimeState& state,
    std::uint32_t address,
    std::uint16_t& out) {
    std::uint32_t word = 0;
    if (!trace_guest_u32(state, address & ~3u, word)) {
        return false;
    }
    const std::uint32_t shift = (2u - (address & 2u)) * 8u;
    out = static_cast<std::uint16_t>((word >> shift) & 0xFFFFu);
    return true;
}

bool trace_guest_u8(
    const RuntimeState& state,
    std::uint32_t address,
    std::uint8_t& out) {
    std::uint32_t word = 0;
    if (!trace_guest_u32(state, address & ~3u, word)) {
        return false;
    }
    const std::uint32_t shift = (3u - (address & 3u)) * 8u;
    out = static_cast<std::uint8_t>((word >> shift) & 0xFFu);
    return true;
}

void trace_dsp_task_info(
    const RuntimeState& state,
    const char* label,
    std::uint32_t task) {
    if (task == 0u) {
        std::cerr << label << "=0x00000000";
        return;
    }
    std::uint32_t task_state = 0;
    std::uint32_t priority = 0;
    std::uint32_t flags = 0;
    std::uint32_t iram_mmem_addr = 0;
    std::uint32_t iram_length = 0;
    std::uint32_t iram_addr = 0;
    std::uint32_t dram_mem_addr = 0;
    std::uint32_t dram_len = 0;
    std::uint32_t dram_addr = 0;
    std::uint16_t dsp_vector = 0;
    std::uint16_t dsp_res_vector = 0;
    std::uint32_t init_cb = 0;
    std::uint32_t res_cb = 0;
    std::uint32_t done_cb = 0;
    std::uint32_t req_cb = 0;
    std::uint32_t next = 0;
    std::uint32_t prev = 0;
    const bool ok =
        trace_guest_u32(state, task + 0x00u, task_state) &&
        trace_guest_u32(state, task + 0x04u, priority) &&
        trace_guest_u32(state, task + 0x08u, flags) &&
        trace_guest_u32(state, task + 0x0Cu, iram_mmem_addr) &&
        trace_guest_u32(state, task + 0x10u, iram_length) &&
        trace_guest_u32(state, task + 0x14u, iram_addr) &&
        trace_guest_u32(state, task + 0x18u, dram_mem_addr) &&
        trace_guest_u32(state, task + 0x1Cu, dram_len) &&
        trace_guest_u32(state, task + 0x20u, dram_addr) &&
        trace_guest_u16(state, task + 0x24u, dsp_vector) &&
        trace_guest_u16(state, task + 0x26u, dsp_res_vector) &&
        trace_guest_u32(state, task + 0x28u, init_cb) &&
        trace_guest_u32(state, task + 0x2Cu, res_cb) &&
        trace_guest_u32(state, task + 0x30u, done_cb) &&
        trace_guest_u32(state, task + 0x34u, req_cb) &&
        trace_guest_u32(state, task + 0x38u, next) &&
        trace_guest_u32(state, task + 0x3Cu, prev);
    std::cerr << label << '=' << hexadecimal(task);
    if (!ok) {
        std::cerr << " invalid=1";
        return;
    }
    std::cerr << " state=" << task_state
              << " prio=" << priority
              << " flags=" << hexadecimal(flags)
              << " iram=(" << hexadecimal(iram_mmem_addr) << ','
              << hexadecimal(iram_length) << ','
              << hexadecimal(iram_addr) << ')'
              << " dram=(" << hexadecimal(dram_mem_addr) << ','
              << hexadecimal(dram_len) << ','
              << hexadecimal(dram_addr) << ')'
              << " vectors=(" << hexadecimal(dsp_vector) << ','
              << hexadecimal(dsp_res_vector) << ')'
              << " cbs=(" << hexadecimal(init_cb) << ','
              << hexadecimal(res_cb) << ','
              << hexadecimal(done_cb) << ','
              << hexadecimal(req_cb) << ')'
              << " links=(" << hexadecimal(next) << ','
              << hexadecimal(prev) << ')';
}

void trace_dsp_scheduler_globals(
    const RuntimeState& state,
    const char* label) {
    std::uint8_t busy = 0;
    std::uint8_t deferred_yield = 0;
    std::uint32_t prior_task = 0;
    std::uint32_t head = 0;
    std::uint32_t tail = 0;
    std::uint32_t current = 0;
    const bool ok =
        trace_guest_u8(state, 0x806A2BF8u, busy) &&
        trace_guest_u8(state, 0x806A2BF9u, deferred_yield) &&
        trace_guest_u32(state, 0x806A2BFCu, prior_task) &&
        trace_guest_u32(state, 0x806A30ACu, head) &&
        trace_guest_u32(state, 0x806A30B0u, tail) &&
        trace_guest_u32(state, 0x806A30B4u, current);
    std::cerr << label << "-sched=";
    if (!ok) {
        std::cerr << "invalid";
        return;
    }
    std::cerr << "(busy=" << static_cast<unsigned>(busy)
              << " deferred=" << static_cast<unsigned>(deferred_yield)
              << " prior=" << hexadecimal(prior_task)
              << " head=" << hexadecimal(head)
              << " tail=" << hexadecimal(tail)
              << " current=" << hexadecimal(current) << ')';
}

void trace_dsp_guest_call(
    const RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    if (!trace_dsp_host()) {
        return;
    }
    const auto trace_scheduler_checkpoint = [&](const char* label) {
        static std::uint64_t s_checkpoint_calls = 0;
        const std::uint64_t call = ++s_checkpoint_calls;
        if (call <= 160u || (call % 1000u) == 0u) {
            std::cerr << "[dsp-guest] scheduler-check call=" << call
                      << " fn=" << label
                      << " addr=" << hexadecimal(guest_address)
                      << " vi=" << state.vi_retrace_count
                      << " lr=" << hexadecimal(context.lr)
                      << " depth=" << state.dsp_interrupt_depth
                      << " r3=" << hexadecimal(context.gpr[3])
                      << " r4=" << hexadecimal(context.gpr[4])
                      << " r5=" << hexadecimal(context.gpr[5]) << ' ';
            trace_dsp_scheduler_globals(state, "state");
            std::cerr << '\n';
        }
    };
    switch (guest_address) {
    case 0x80494390u:
        trace_scheduler_checkpoint("JAS-updateDSP");
        return;
    case 0x804946E8u:
        trace_scheduler_checkpoint("JAS-syncFrame");
        return;
    case 0x8049569Cu:
        trace_scheduler_checkpoint("DSP-request-tail");
        return;
    case 0x804969E0u:
        trace_scheduler_checkpoint("DSP-deferred-replay");
        return;
    case 0x80496A60u:
        trace_scheduler_checkpoint("DSP-running-check");
        return;
    case 0x80496A80u:
        trace_scheduler_checkpoint("DSP-set-running");
        return;
    default:
        break;
    }
    if (guest_address == 0x804CB2C0u) {
        static std::uint64_t s_send_mail_calls = 0;
        const std::uint64_t call = ++s_send_mail_calls;
        if (call <= 160u || (call % 1000u) == 0u) {
            std::cerr << "[dsp-guest] DSPSendMailToDSP call=" << call
                      << " vi=" << state.vi_retrace_count
                      << " mail=" << hexadecimal(context.gpr[3])
                      << " lr=" << hexadecimal(context.lr)
                      << " depth=" << state.dsp_interrupt_depth << '\n';
        }
        return;
    }
    if (guest_address == 0x80494C70u) {
        // fn_80494C70: posts AUDIOMSG_DMA (msg=0) to the JAC audio queue.
        static std::uint64_t s_audiomsg_dma_posts = 0;
        const std::uint64_t call = ++s_audiomsg_dma_posts;
        if (call <= 64u || (call % 200u) == 0u) {
            std::cerr << "[audio-q] fn_80494C70(AUDIOMSG_DMA producer) call="
                      << call << " vi=" << state.vi_retrace_count
                      << " lr=" << hexadecimal(context.lr)
                      << " depth=" << state.dsp_interrupt_depth << '\n';
        }
        return;
    }
    if (guest_address == 0x804A88E4u) {
        // OSSendMessage(queue=r3, msg=r4, flags=r5). Only surface posts coming
        // from the JAC audio module (callers in 0x80494xxx-0x80497xxx) so the
        // hot general OSSendMessage path is not spammed.
        const std::uint32_t caller = context.lr;
        if (caller >= 0x80494000u && caller < 0x80497000u) {
            static std::uint64_t s_audio_sends = 0;
            const std::uint64_t call = ++s_audio_sends;
            if (call <= 128u || (call % 200u) == 0u) {
                std::cerr << "[audio-q] OSSendMessage call=" << call
                          << " vi=" << state.vi_retrace_count
                          << " queue=" << hexadecimal(context.gpr[3])
                          << " msg=" << hexadecimal(context.gpr[4])
                          << " flags=" << hexadecimal(context.gpr[5])
                          << " lr=" << hexadecimal(caller)
                          << " depth=" << state.dsp_interrupt_depth << '\n';
            }
        }
        return;
    }
    if (guest_address == 0x80496900u || guest_address == 0x80496980u) {
        static std::uint64_t s_scheduler_calls = 0;
        const std::uint64_t call = ++s_scheduler_calls;
        std::cerr << "[dsp-guest] scheduler call=" << call
                  << " fn=" << hexadecimal(guest_address)
                  << " vi=" << state.vi_retrace_count
                  << " lr=" << hexadecimal(context.lr)
                  << " depth=" << state.dsp_interrupt_depth
                  << " r3=" << hexadecimal(context.gpr[3])
                  << " r4=" << hexadecimal(context.gpr[4]) << ' ';
        trace_dsp_scheduler_globals(state, "before");
        std::cerr << '\n';
        return;
    }
    if (guest_address == 0x804CB420u) {
        static std::uint64_t s_exec_task_calls = 0;
        const std::uint64_t call = ++s_exec_task_calls;
        std::cerr << "[dsp-guest] __DSP_exec_task call=" << call
                  << " vi=" << state.vi_retrace_count
                  << " lr=" << hexadecimal(context.lr)
                  << " depth=" << state.dsp_interrupt_depth << ' ';
        trace_dsp_task_info(state, "current", context.gpr[3]);
        std::cerr << ' ';
        trace_dsp_task_info(state, "next", context.gpr[4]);
        std::cerr << ' ';
        trace_dsp_scheduler_globals(state, "global");
        std::cerr << '\n';
    }
}

const char* dsp_exec_wait_label(std::uint32_t guest_pc) {
    switch (guest_pc) {
    case 0x804CB454u:
        return "current-dram-mem";
    case 0x804CB468u:
        return "current-dram-len";
    case 0x804CB47Cu:
        return "current-dram-addr";
    case 0x804CB494u:
        return "null-current-0";
    case 0x804CB4A8u:
        return "null-current-1";
    case 0x804CB4BCu:
        return "null-current-2";
    case 0x804CB4D0u:
        return "next-iram-mmem";
    case 0x804CB4E4u:
        return "next-iram-len";
    case 0x804CB4F8u:
        return "next-iram-addr";
    case 0x804CB518u:
        return "next-dsp-vector";
    case 0x804CB52Cu:
        return "next-new-zero-0";
    case 0x804CB540u:
        return "next-new-zero-1";
    case 0x804CB554u:
        return "next-new-zero-2";
    case 0x804CB56Cu:
        return "next-dsp-res-vector";
    case 0x804CB580u:
        return "next-dram-mem";
    case 0x804CB594u:
        return "next-dram-len";
    case 0x804CB5A8u:
        return "next-dram-addr";
    default:
        return nullptr;
    }
}

void trace_dsp_exec_task_wait_snapshot(
    const RuntimeState& state,
    std::uint32_t guest_pc,
    const galaxy::PpcContext& context) {
    if (!trace_dsp_host() || !is_dsp_task_mail_wait_pc(guest_pc)) {
        return;
    }
    static std::unordered_map<std::uint32_t, std::uint64_t> s_wait_snapshots;
    const std::uint64_t count = ++s_wait_snapshots[guest_pc];
    if (count > 8u && (count % 10000000u) != 0u) {
        return;
    }
    const galaxy::host::DspDebugSnapshot snapshot =
        state.address_space != nullptr
            ? state.address_space->dsp_debug_snapshot()
            : galaxy::host::DspDebugSnapshot{};
    std::cerr << "[dsp-task-wait] pc=" << hexadecimal(guest_pc)
              << " label=" << (dsp_exec_wait_label(guest_pc) != nullptr
                       ? dsp_exec_wait_label(guest_pc)
                       : "unknown")
              << " count=" << count
              << " vi=" << state.vi_retrace_count
              << " lr=" << hexadecimal(context.lr)
              << " r3=" << hexadecimal(context.gpr[3])
              << " r30=" << hexadecimal(context.gpr[30])
              << " r31=" << hexadecimal(context.gpr[31])
              << " pending="
              << (snapshot.dsp_interrupt_pending ? 1 : 0)
              << " depth=" << state.dsp_interrupt_depth
              << " from-ready=" << (snapshot.from_mail_ready ? 1 : 0)
              << " from=" << hexadecimal(snapshot.from_mail_raw)
              << " native-present="
              << (snapshot.native_from_mail_present ? 1 : 0)
              << " native-staged="
              << (snapshot.native_from_mail_staged ? 1 : 0)
              << " native-irq-latched="
              << (snapshot.native_from_mail_irq_latched ? 1 : 0)
              << " native-queue="
              << snapshot.native_from_mail_queue_depth
              << " native-from-high=0x" << std::hex
              << snapshot.native_from_mail_high
              << " native-from-low=0x" << snapshot.native_from_mail_low
              << std::dec << ' ';
    trace_dsp_task_info(state, "current", context.gpr[30]);
    std::cerr << ' ';
    trace_dsp_task_info(state, "next", context.gpr[31]);
    std::cerr << ' ';
    trace_dsp_scheduler_globals(state, "global");
    std::cerr << '\n';
}

