#ifndef CREATE_WAITABLE_TIMER_HIGH_RESOLUTION
#define CREATE_WAITABLE_TIMER_HIGH_RESOLUTION 0x00000002
#endif

HANDLE realtime_vi_wait_timer() {
    static HANDLE timer = [] {
        HANDLE high_res = CreateWaitableTimerExW(
            nullptr,
            nullptr,
            CREATE_WAITABLE_TIMER_HIGH_RESOLUTION,
            TIMER_MODIFY_STATE | SYNCHRONIZE);
        if (high_res != nullptr) {
            return high_res;
        }
        return CreateWaitableTimerExW(
            nullptr,
            nullptr,
            0,
            TIMER_MODIFY_STATE | SYNCHRONIZE);
    }();
    return timer;
}

bool wait_realtime_vi_duration_high_res(
    std::chrono::steady_clock::duration duration) {
    if (!high_res_vi_wait_enabled() || duration <= duration.zero()) {
        return false;
    }
    HANDLE timer = realtime_vi_wait_timer();
    if (timer == nullptr) {
        return false;
    }

    using HundredNanoseconds =
        std::chrono::duration<long long, std::ratio<1, 10'000'000>>;
    const auto ticks =
        std::chrono::duration_cast<HundredNanoseconds>(duration).count();
    if (ticks <= 0) {
        return false;
    }

    LARGE_INTEGER due_time{};
    due_time.QuadPart = -ticks;
    if (!SetWaitableTimer(timer, &due_time, 0, nullptr, nullptr, FALSE)) {
        return false;
    }
    return WaitForSingleObject(timer, INFINITE) == WAIT_OBJECT_0;
}

