bool thp_decode_checkpoint_pc(std::uint32_t guest_pc) {
    // RVL THP video/audio decode, including the JPEG/Huffman/DCT hot loops.
    return guest_pc >= 0x804514ECu && guest_pc <= 0x80456240u;
}

bool fast_thp_checkpoint_poll_due(std::uint64_t checkpoint_count) {
    const std::uint64_t interval = fast_thp_checkpoint_interval();
    if (interval <= 1u) {
        return true;
    }
    if ((interval & (interval - 1u)) == 0u) {
        return (checkpoint_count & (interval - 1u)) == 0u;
    }
    return (checkpoint_count % interval) == 0u;
}

bool fast_yaz0_checkpoint_poll_due(RuntimeState& state) {
    const std::uint64_t checkpoint_count = state.checkpoint_count;
    const std::uint64_t interval = fast_yaz0_checkpoint_interval();
    if (interval <= 1u) {
        return true;
    }

    if (state.next_yaz0_fast_checkpoint_poll == 0u ||
        checkpoint_count < state.next_yaz0_fast_checkpoint_poll) {
        if (state.next_yaz0_fast_checkpoint_poll == 0u) {
            state.next_yaz0_fast_checkpoint_poll =
                checkpoint_count + interval;
        }
        return false;
    }

    state.next_yaz0_fast_checkpoint_poll = checkpoint_count + interval;
    return true;
}

