bool is_file_select_trace_address(std::uint32_t address) {
    if (!trace_file_select_enabled()) {
        return false;
    }
    if (!trace_file_select_save_sequence_enabled() &&
        address >= 0x803B4900u && address <= 0x803B66ACu) {
        return false;
    }
    if (!trace_file_select_full_enabled()) {
        switch (address) {
            case 0x801785ECu: // FileSelectItem::onPointing.
            case 0x8017866Cu: // FileSelectItem::offPointing.
            case 0x80178A14u: // FileSelectItem::control.
            case 0x80178E64u: // FileSelectItem::updatePointing.
            case 0x80178F5Cu: // FileSelectItem::updateRotate.
            case 0x8017AB10u: // FileSelector::notifyItem.
            case 0x8017AB94u: // FileSelector::control.
            case 0x8017BA08u: // FileSelector::onPoint.
            case 0x8017BA84u: // FileSelector::onSelect.
            case 0x8017BB40u: // FileSelector::clearPointing.
            case 0x8017C7B4u: // FileSelector::exeTitle.
            case 0x8017C874u: // FileSelector::exeTitleEnd.
            case 0x8017C984u: // FileSelector::exeRFLWait.
            case 0x8017CA08u: // FileSelector::exeRFLWaitEnd.
            case 0x8017CA60u: // FileSelector::exeFileSelectStart.
            case 0x8017CAC4u: // FileSelector::exeFileSelect.
            case 0x8017CB1Cu: // FileSelector::exeFileConfirmStart.
            case 0x8017CD18u: // FileSelector::exeFileConfirm.
            case 0x8017CF1Cu: // FileSelector::exeDemo.
            case 0x8017D024u: // FileSelector::exeCreateConfirmStart.
            case 0x8017D08Cu: // FileSelector::exeCreateConfirm.
            case 0x8017D148u: // FileSelector::exeCreate.
            case 0x8017D900u: // FileSelector::exeMiiSelectStart, RMGE01 generated module.
            case 0x8017D9DCu: // FileSelector::exeMiiSelect, RMGE01 generated module.
            case 0x8017DBACu: // FileSelector::exeMiiConfirm, RMGE01 generated module.
            case 0x8017DD04u: // FileSelector::exeMiiCreateWait, RMGE01 generated module.
            case 0x8017DD80u: // FileSelector::exeMiiCreateDemo, RMGE01 generated module.
            case 0x8017DF14u: // FileSelector::exeMiiInfo.
            case 0x8017E0C4u: // FileSelector::exeDelete.
            case 0x8017E294u: // FileSelector::exeManual.
            case 0x803B4D84u: // GameSequenceFunction::startGameDataLoadSequence.
            case 0x803B49B0u: // SaveDataHandleSequence predicate.
            case 0x803B49BCu: // SaveDataHandleSequence advance.
            case 0x803B49C8u: // SaveDataHandleSequence::exeWait.
            case 0x803B49ECu: // SaveDataHandleSequence::exeProcessing.
            case 0x803B4A20u: // SaveDataHandleSequence::exeSaveProcessingGameData.
            case 0x803B4A54u: // SaveDataHandleSequence::exeSaveProcessingBanner.
            case 0x803B4DC8u: // GameSequenceFunction::startCreateUserFileSequence, RMGE01 generated module.
            case 0x803B4F84u: // GameSequenceFunction::isActiveSaveDataHandleSequence, RMGE01 generated module.
            case 0x803B4FA8u: // GameSequenceFunction::isSuccessSaveDataHandleSequence, RMGE01 generated module.
            case 0x803B5498u: // SaveDataHandler fallback notifier.
            case 0x803B55ECu: // SaveDataHandler::wait.
            case 0x803B5654u: // SaveDataHandler::startRequest.
            case 0x803B56BCu: // SaveDataHandler::pumpRequest.
            case 0x803B5958u: // SaveDataHandler::requestRemoveGameData.
            case 0x803B596Cu: // SaveDataHandler D8F4 body.
            case 0x803B59B0u: // SaveDataHandler remove-processing body.
            case 0x803B5A48u: // SaveDataHandler D8F8 body.
            case 0x803B5ADCu: // SaveDataHandler reset flags.
            case 0x803B5E30u: // SaveDataHandler status-list refresh.
            case 0x803B5FC0u: // SaveDataHandler nerve wrapper.
            case 0x803B5FC8u: // SaveDataHandler nerve wrapper.
            case 0x803B5FD0u: // SaveDataHandler nerve wrapper.
            case 0x803B5FD8u: // SaveDataHandler nerve wrapper.
            case 0x803B6018u: // SaveDataHandler nerve wrapper.
            case 0x803B6020u: // SaveDataHandler nerve wrapper.
            case 0x803B6404u: // GameSequenceFunction::startCreateUserFileSequence owner.
            case 0x803B640Cu: // GameSequenceFunction::startCreateUserFileSequence.
            case 0x803B64C0u: // GameSequenceFunction::startSetMiiOrIconIdUserFileSequence.
            case 0x803B64D0u: // startSetMiiOrIconIdUserFileSequence + 0x10.
            case 0x803B64F8u: // GameSequenceFunction save/user-file helpers owner.
            case 0x803B6514u: // GameSequenceFunction::storeMiiOrIconIdUserFileSequence.
            case 0x803B65A4u: // GameSequenceFunction::startSaveAllUserFileSequence.
            case 0x803B65C8u: // GameSequenceFunction::isActiveSaveDataHandleSequence.
            case 0x803B65ECu: // GameSequenceFunction::isSuccessSaveDataHandleSequence.
            case 0x803B8ED8u: // SaveDataHandleSequence::startCreateUserFile owner.
            case 0x803B8EDCu: // SaveDataHandleSequence::startCreateUserFile.
            case 0x803B90F0u: // SaveDataHandleSequence::storeMiiOrIconId.
            case 0x803B9594u: // SaveDataHandleSequence::exeNoOperation.
            case 0x803B95A8u: // SaveDataHandleSequence::exeCheckEnableToCreate.
            case 0x803B9728u: // SaveDataHandleSequence::exeSave.
            case 0x803B9EACu: // SaveDataHandleSequence save/write path.
            case 0x803BA604u: // SaveDataHandleSequenceSave nerve.
            case 0x803BA614u: // SaveDataHandleSequenceCheckEnableToCreate nerve.
            case 0x803BA61Cu: // SaveDataHandleSequenceNoOperation nerve.
            case 0x803AE6ACu: // ConfigDataMii::setMiiOrIconId.
            case 0x8036DA0Cu: // MiiSelect::getSelectedID.
            case 0x8036E558u: // MiiSelect::getIconID.
            case 0x8036ED14u: // MiiSelectIcon::MiiSelectIcon.
            case 0x8036EE1Cu: // MiiSelect::appear.
            case 0x8036F028u: // MiiSelect::exeAppear.
            case 0x8036F0ACu: // MiiSelect::exeWait.
            case 0x8036FB70u: // MiiSelect::onSelect.
            case 0x8036FBC4u: // MiiSelect::onSelectDummy.
            case 0x803FB5BCu: // StarPointerUtil::getPointingPos helper.
            case 0x803FB680u: // StarPointerUtil::isPointing helper.
            case 0x8034C874u: // ButtonPaneController::trySelect owner.
            case 0x8034C87Cu: // ButtonPaneController::trySelect.
            case 0x8034C8E4u: // ButtonPaneController::isPointing owner.
            case 0x8034C914u: // ButtonPaneController::isPointing.
            case 0x803D42E8u: // MR::testDPDMenuPadDecideTrigger owner.
            case 0x803D42ECu: // MR::testDPDMenuPadDecideTrigger.
            case 0x803FBAACu: // StarPointerUtil::checkPointingTarget owner.
            case 0x803FBB08u: // StarPointerUtil::checkPointingTarget.
            case 0x803FC76Cu: // MR::isStarPointerPointingFileSelect owner.
            case 0x803FC794u: // MR::isStarPointerPointingFileSelect.
                return true;
            default:
                return false;
        }
    }

    const std::uint16_t page = static_cast<std::uint16_t>(address >> 16);
    if (page == 0x8017u) {
        return true;
    }
    if (page == 0x803Au) {
        return address >= 0x803AE600u && address <= 0x803AE740u;
    }
    if (page == 0x8034u) {
        return address == 0x8034C874u || address == 0x8034C87Cu ||
               address == 0x8034C8E4u || address == 0x8034C914u;
    }
    if (page == 0x803Du) {
        return address == 0x803D42E8u || address == 0x803D42ECu;
    }
    if (page == 0x803Fu) {
        return address == 0x803FB5BCu || address == 0x803FB680u ||
               address == 0x803FBAACu || address == 0x803FBB08u ||
               address == 0x803FC76Cu || address == 0x803FC794u;
    }
    if (page != 0x803Bu) {
        return false;
    }
    return (address >= 0x803B4900u && address <= 0x803B6070u) ||
           (address >= 0x803B6380u && address <= 0x803B66ACu);
}


