    case 0xF133F014u: return "GameScene::draw3D after 803D8A44";
    case 0xF133F028u: return "GameScene::draw3D after 803CA76C";
    // This final synthetic range resolves the observed costly 80344954
    // dispatch batch by its eight fixed category arguments.  The entries
    // are generated trace markers only and never enter guest dispatch.
    case 0xF3344260u: return "GameScene::draw3D 80344954 category 1D";
    case 0xF3344268u: return "GameScene::draw3D 80344954 category 19";
    case 0xF3344270u: return "GameScene::draw3D 80344954 category 1A";
    case 0xF3344278u: return "GameScene::draw3D 80344954 category 1B";
    case 0xF3344280u: return "GameScene::draw3D 80344954 category 1C";
    case 0xF3344288u: return "GameScene::draw3D 80344954 category 22";
    case 0xF3344290u: return "GameScene::draw3D 80344954 category 17";
    case 0xF3344298u: return "GameScene::draw3D 80344954 category 16";
    // The category-1D marker before its mandatory return checkpoint separates
    // static native function time from any scheduler/interrupt work that the
    // checkpoint is required to dispatch.
    case 0xF534425Cu: return "GameScene::draw3D 80344954 category 1D pre-checkpoint";
    // These trace-only continuations split the direct calls between the
    // broad 8034419C and 8034424C markers. They prevent attributing that
    // whole interval to 8034424C when profiling native frame pacing.
    case 0xF633EFB0u: return "GameScene::draw3D after 80344990(18)";
    case 0xF633EFB8u: return "GameScene::draw3D after 80344894(26)";
    case 0xF633EFC0u: return "GameScene::draw3D after 80344894(47)";
    case 0xF633EFC8u: return "GameScene::draw3D after 80344894(4C)";
    case 0xF633EFD0u: return "GameScene::draw3D after 80344894(2F)";
    case 0xF633EFD8u: return "GameScene::draw3D after 80344894(2D)";
    // Category 47 is the measured expensive dispatcher. These three records
    // separate its one pre-loop virtual call from its per-item virtual loop.
    case 0xF73617FCu: return "Draw category 47 pre-loop virtual call begin";
    case 0xF7361800u: return "Draw category 47 pre-loop virtual call end";
    case 0xF736183Cu: return "Draw category 47 item loop end";
    case 0xFB0C9260u: return "Particle 800C9248 after 803C73CC";
    case 0xFB0C926Cu: return "Particle 800C9248 after 800C95C4";
    case 0xFC0C95F0u: return "Particle 800C95C4 after PSMTXCopy";
    case 0xFC0C95F8u: return "Particle 800C95C4 after PSMTXIdentity";
    case 0xFC0C960Cu: return "Particle 800C95C4 after 80448790 array 0";
    case 0xFC0C9614u: return "Particle 800C95C4 after GXSetArray 0";
    case 0xFC0C9628u: return "Particle 800C95C4 after 80448790 array 1";
    case 0xFC0C9630u: return "Particle 800C95C4 after GXSetArray 1";
    case 0xFC4487D8u: return "Particle 80448790 after preparation";
    case 0xFC44891Cu: return "Particle 80448790 after GX setup";
    case 0xFC448974u: return "Particle 80448790 after callback loop";
    // These markers bracket the optional per-category draw setup and the
    // selected draw-list dispatch. They are emitted once per list, never per
    // item, so they remain safe under the strict realtime cadence audit.
    case 0xF4336998u: return "DrawBuffer::draw category setup begin";
    case 0xF433699Cu: return "DrawBuffer::draw list dispatch begin";
    case 0xF43369E0u: return "DrawBuffer::draw list dispatch end";
    case 0x8039FF14u: return "MainLoop::beginRender";
    case 0x803A007Cu: return "MainLoop::endRender";
