    case 0xF83A014Cu: return "endFrame mode3 before 803A08A0";
    case 0xF83A0150u: return "endFrame mode3 after 803A08A0 before 804B9B20";
    // Shared join also has paths that never begin 804B9B20. Analysis must
    // match a mode3 begin in this guest frame/thread before deriving a span.
    case 0xF83A0154u: return "endFrame shared join 803A0154";
    case 0xF83A093Cu: return "endFrame 803A08A0 before 804BA014";
    case 0xF83A0940u: return "endFrame 803A08A0 after 804BA014";
    case 0xF933E860u: return "scene update before 803F7E40 at 8033E860";
    case 0xFA33E864u: return "scene update after 803F7E40 at 8033E864";
    case 0xF933E86Cu: return "scene update before 80371174 at 8033E86C";
    case 0xFA33E870u: return "scene update after 80371174 at 8033E870";
    case 0xF933E880u: return "scene update before 803A29B8 at 8033E880";
    case 0xFA33E884u: return "scene update after 803A29B8 at 8033E884";
    case 0xF933E898u: return "scene update before 80343DC4 at 8033E898";
    case 0xFA33E89Cu: return "scene update after 80343DC4 at 8033E89C";
    case 0xF933E8A0u: return "scene update before 80343D2C at 8033E8A0";
    case 0xFA33E8A4u: return "scene update after 80343D2C at 8033E8A4";
    case 0xF933E8ACu: return "scene update before 803A29B8 at 8033E8AC";
