bool is_particle_direction_profile_caller(std::uint32_t caller_pc) {
    switch (caller_pc) {
    case 0x80443420u: // draw-list dispatch to direction/setup callbacks
    case 0x803A3BB4u: // direction callback
    case 0x803A3BC0u: // first zero test
    case 0x803A3BD0u: // first normalize
    case 0x803A3BE0u: // first cross product
    case 0x803A3BECu: // second zero test
    case 0x803A3BFCu: // second normalize
    case 0x803A3C0Cu: // second cross product
    case 0x803A3C14u: // work-vector normalize
    case 0x803A3CA8u: // projection callback
    case 0x803A3CB8u: // PSMTXConcat
    case 0x803A3CC4u: // GXLoadPosMtxImm
    case 0x803A3CE4u: // draw callback
    case 0x803A3CFCu: // GXBegin
        return true;
    default:
        return false;
    }
}

// The general direct-edge line is intentionally capped to its 128 most
// expensive edges. That ranking is useful for discovery but can omit cheap
// stages needed to close the arithmetic for one selected hot routine. Emit a
// second, shutdown-only view of every observed direction-pipeline edge. The
// realtime recording path and NativeServices ABI remain unchanged.
void dump_particle_direction_edge_profile() {
    struct Snapshot {
        std::uint64_t key;
        std::uint64_t calls;
        std::uint64_t cycles;
    };
    std::vector<Snapshot> snapshots;
    snapshots.reserve(20u);
    for (const galaxy::DirectEdgeProfileSlot& slot :
         galaxy::direct_edge_profile_slots()) {
        const std::uint64_t key = slot.key.load(std::memory_order_relaxed);
        const std::uint32_t caller = static_cast<std::uint32_t>(key >> 32u);
        if (key == 0u || !is_particle_direction_profile_caller(caller)) {
            continue;
        }
        const std::uint64_t calls = slot.calls.load(std::memory_order_relaxed);
        if (calls == 0u) {
            continue;
        }
        snapshots.push_back(Snapshot{
            key,
            calls,
            slot.cycles.load(std::memory_order_relaxed),
        });
    }
    std::sort(
        snapshots.begin(),
        snapshots.end(),
        [](const Snapshot& left, const Snapshot& right) {
            return left.key < right.key;
        });

    std::fprintf(
        stderr,
        "[particle-direction-edge-profile] edges=%zu",
        snapshots.size());
    for (const Snapshot& snapshot : snapshots) {
        const std::uint32_t caller =
            static_cast<std::uint32_t>(snapshot.key >> 32u);
        const std::uint32_t callee = static_cast<std::uint32_t>(snapshot.key);
        const std::uint64_t average = snapshot.cycles / snapshot.calls;
        std::fprintf(
            stderr,
            " %08X->%08X=%llu/%llu/%llu",
            static_cast<unsigned>(caller),
            static_cast<unsigned>(callee),
            static_cast<unsigned long long>(snapshot.cycles),
            static_cast<unsigned long long>(snapshot.calls),
            static_cast<unsigned long long>(average));
    }
    std::fprintf(stderr, "\n");
}

// NW4R Material::SetupGX is a large translated routine whose many small,
// statically resolved GX setters normally fall below the general profile's
// 128-edge output limit. Keep selection exact to the call instructions inside
// RMGE01 0x800130F0..0x80013F8F and emit one buffered shutdown record so this
// diagnostic cannot recreate the old per-field stderr write-through stalls.
constexpr bool is_nw4r_material_setup_profile_caller(
    std::uint32_t caller_pc) {
    return caller_pc >= 0x80013110u && caller_pc <= 0x80013F7Cu;
}

static_assert(is_nw4r_material_setup_profile_caller(0x80013110u));
static_assert(is_nw4r_material_setup_profile_caller(0x80013F7Cu));
static_assert(!is_nw4r_material_setup_profile_caller(0x800130F0u));
static_assert(!is_nw4r_material_setup_profile_caller(0x80013F80u));

void dump_nw4r_material_setup_edge_profile() {
    struct Snapshot {
        std::uint64_t key;
        std::uint64_t calls;
        std::uint64_t cycles;
    };
    std::vector<Snapshot> snapshots;
    snapshots.reserve(96u);
    for (const galaxy::DirectEdgeProfileSlot& slot :
         galaxy::direct_edge_profile_slots()) {
        const std::uint64_t key = slot.key.load(std::memory_order_relaxed);
        const std::uint32_t caller = static_cast<std::uint32_t>(key >> 32u);
        if (key == 0u || !is_nw4r_material_setup_profile_caller(caller)) {
            continue;
        }
        const std::uint64_t calls = slot.calls.load(std::memory_order_relaxed);
        if (calls == 0u) {
            continue;
        }
        snapshots.push_back(Snapshot{
            key,
            calls,
            slot.cycles.load(std::memory_order_relaxed),
        });
    }
    std::sort(
        snapshots.begin(),
        snapshots.end(),
        [](const Snapshot& left, const Snapshot& right) {
            if (left.cycles != right.cycles) {
                return left.cycles > right.cycles;
            }
            return left.key < right.key;
        });

    if (snapshots.empty()) {
        return;
    }

    std::ostringstream output;
    output << "[nw4r-material-setup-edge-profile] edges=" << snapshots.size();
    for (const Snapshot& snapshot : snapshots) {
        const std::uint32_t caller =
            static_cast<std::uint32_t>(snapshot.key >> 32u);
        const std::uint32_t callee = static_cast<std::uint32_t>(snapshot.key);
        const std::uint64_t average = snapshot.cycles / snapshot.calls;
        output << ' ' << hexadecimal(caller).substr(2) << "->"
               << hexadecimal(callee).substr(2) << '=' << snapshot.cycles
               << '/' << snapshot.calls << '/' << average;
    }
    output << '\n';
    const std::string line = output.str();
    std::fwrite(line.data(), 1u, line.size(), stderr);
}

constexpr bool is_nw4r_pane_draw_self_profile_caller(
    std::uint32_t caller_pc) {
    return (caller_pc >= 0x8000A1C8u && caller_pc < 0x8000A450u) ||
           (caller_pc >= 0x8000A450u && caller_pc < 0x8000A654u) ||
           (caller_pc >= 0x8000DEACu && caller_pc < 0x8000DF88u) ||
           (caller_pc >= 0x8000E5FCu && caller_pc < 0x8000E7E4u) ||
           (caller_pc >= 0x8000EB28u && caller_pc < 0x8000ECF0u) ||
           (caller_pc >= 0x80350388u && caller_pc < 0x803510ECu);
}

static_assert(is_nw4r_pane_draw_self_profile_caller(0x8000A428u));
static_assert(is_nw4r_pane_draw_self_profile_caller(0x8000A610u));
static_assert(is_nw4r_pane_draw_self_profile_caller(0x8000DEF4u));
static_assert(is_nw4r_pane_draw_self_profile_caller(0x8000E7CCu));
static_assert(is_nw4r_pane_draw_self_profile_caller(0x8000EBCCu));
static_assert(is_nw4r_pane_draw_self_profile_caller(0x8035107Cu));
static_assert(!is_nw4r_pane_draw_self_profile_caller(0x8000A1C4u));
static_assert(!is_nw4r_pane_draw_self_profile_caller(0x8000A654u));
static_assert(!is_nw4r_pane_draw_self_profile_caller(0x8000DF88u));
static_assert(!is_nw4r_pane_draw_self_profile_caller(0x8000E7E4u));
static_assert(!is_nw4r_pane_draw_self_profile_caller(0x8000ECF0u));
static_assert(!is_nw4r_pane_draw_self_profile_caller(0x803510ECu));

