bool is_main_frame_core_call(std::uint32_t address) {
    switch (address) {
    case 0x80399AF0u: // GameSystem::frameLoop
    case 0x8039FF14u: // MainLoop::beginRender
    case 0x803A007Cu: // MainLoop::endRender
    case 0x8039FD20u: // MainLoop::copyXfb_triple
    case 0x803A00FCu: // MainLoop::endFrame
    case 0x8039FEE0u: // MainLoop::waitForRetrace
        return true;
    default:
        return false;
    }
}

