// The three outer scene phases each select a scene through the tiny helper
// at 0x8039DBE4 and invoke three virtual methods. Record all nine fixed DOL
// continuation PCs so time between repeated getter entries can be attributed
// to the actual scene callbacks. The high-fanout NameObj dispatcher remains
// opt-in separately; this is not a general indirect-call trace.
bool is_main_frame_dynamic_call_return(std::uint32_t return_pc) {
    switch (return_pc) {
    case 0x8039D308u:
    case 0x8039D31Cu:
    case 0x8039D330u:
    case 0x8039D398u:
    case 0x8039D3ACu:
    case 0x8039D3C0u:
    case 0x8039D404u:
    case 0x8039D418u:
    case 0x8039D42Cu:
        return true;
    // The category-47 draw dispatcher at 802617B4 executes an indirect
    // callback for every item. It deliberately does not participate in the
    // normal outer-frame trace: its rate is scene-dependent and can exhaust
    // the fixed diagnostic ring within one frame. Enable it only for a
    // targeted draw-dispatch investigation.
    case 0x80261820u:
        return trace_main_frame_draw_dispatch_enabled() ||
               trace_main_frame_member_targets_enabled();
    // The inline PTMF decoder has already performed the architectural
    // loads/this adjustment before calling the runtime with these LRs.
    // 800C9AC8 is the nested particle-group PTMF continuation reached by the
    // category-47 80261494 wrapper.  Keeping it under the same bounded member
    // trace exposes the concrete draw member without changing guest dispatch.
    case 0x800C9AC8u:
    case 0x80261B5Cu:
    case 0x80261B8Cu:
        return trace_main_frame_member_targets_enabled();
    default:
        return false;
    }
}

int frame_activity_counter_index(std::uint32_t address) {
    const auto in_function =
        [address](std::uint32_t start, std::uint32_t size) {
            return address >= start && address < start + size;
        };
    if (in_function(0x80399AF0u, 0x68u)) {
        return kFrameActivityFrameLoop;
    }
    if (in_function(0x8039FF14u, 0x168u)) {
        return kFrameActivityBeginRender;
    }
    if (in_function(0x803A007Cu, 0x80u)) {
        return kFrameActivityEndRender;
    }
    if (in_function(0x8039FD20u, 0x70u)) {
        return kFrameActivityCopyXfb;
    }
    if (in_function(0x803A00FCu, 0x94u)) {
        return kFrameActivityEndFrame;
    }
    if (in_function(0x8039FEE0u, 0x34u)) {
        return kFrameActivityWaitForRetrace;
    }
    switch (address) {
    case 0x804B38F0u: return kFrameActivityViGetRetraceCount;
    case 0x804A89ACu: return kFrameActivityOsReceiveMessage;
    case 0x804ABFBCu: return kFrameActivityOsSleepThread;
    case 0x802B0364u:
    case 0x802B0394u:
        return kFrameActivityMarioMovement;
    case 0x802B0D38u:
    case 0x802B0E60u:
    case 0x802B1004u:
    case 0x802B10ECu:
        return kFrameActivityMarioControl;
    case 0x802B2B34u:
    case 0x802B300Cu:
    case 0x802B3800u:
    case 0x802CAD70u:
    case 0x802CB580u:
        return kFrameActivityMarioAnim;
    case 0x803EABE0u:
    case 0x803DF804u:
    case 0x80175EA4u:
    case 0x80183140u:
    case 0x803E1F00u:
        return kFrameActivityCollision;
    case 0x8037175Cu:
    case 0x80371780u:
    case 0x80371FE8u:
        return kFrameActivityMovie;
    case 0x8038D2E4u:
    case 0x8038D34Cu:
    case 0x8038D868u:
        return kFrameActivityThp;
    default:
        return -1;
    }
}

void record_frame_activity(RuntimeState& state, std::uint32_t address) {
    const int index = frame_activity_counter_index(address);
    if (index >= 0) {
        ++state.frame_activity_counts[static_cast<std::size_t>(index)];
    }
}

std::uint64_t frame_activity_delta(
    const RuntimeState& state,
    FrameActivityCounter counter) {
    const std::size_t index = static_cast<std::size_t>(counter);
    const std::uint64_t end = state.frame_activity_counts[index];
    const std::uint64_t start =
        state.benchmark_start_frame_activity_counts[index];
    return end >= start ? end - start : 0u;
}

std::uint8_t read_guest_u8(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address) {
    return std::to_integer<std::uint8_t>(
        *address_space.pointer(address, 1u));
}

std::int16_t read_guest_s16(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address) {
    const std::uint32_t word = address_space.read_u32(address & ~3u);
    const unsigned shift = (address & 2u) == 0u ? 16u : 0u;
    return static_cast<std::int16_t>((word >> shift) & 0xFFFFu);
}

// Bounded to RMGE01's three-XFB paths: JUT's exact pending skip-exchange,
// or SMG's prior GXDrawDone-completed drawn slot distinct from current drawing.
// Memory is protected by the live-read release or a sealed detached snapshot.
// No GPU fence, callback, or guest store is bypassed.
bool independent_vi_pe_capture_allowed(
    RuntimeState& state, std::uint64_t prior_copies,
    bool rendered_retrace, bool present_in_render) {
    if (!independent_vi_pe_completion_enabled()) return false;
    const auto& timing = galaxy::gx::get_gx_timing_config();
    if (!galaxy::gx::independent_vi_pe_policy_valid(
            timing.pe_events_gpu_fence,
            read_env_flag("GALAXY_ASYNC_RENDER_THREAD", true),
            timing.render_live_memory_wait, sim_thread_pe_scan_enabled(),
            read_env_flag("GALAXY_DIRECT_WGPIPE_PE_EVENTS", false),
            // Capture selects the policy before the durable submit phase.
            // That phase cannot advance to token ownership until render_frame
            // seals and detaches its snapshot, classifies that exact view and
            // retains it through recording. Failed capture never admits VI.
            timing.render_memory_snapshot)) {
        throw RuntimeFailure(
            "independent VI delivery requires real GPU fences and protected "
            "memory ownership, with no synthetic PE publication");
    }
    if (!rendered_retrace || present_in_render || prior_copies == 0u ||
        state.address_space == nullptr) return false;
    const auto& space = *state.address_space;
    constexpr std::uint32_t kJutXfbManagerPtr = 0x806A2868u;
    // JUT pending byte: verified 804193F0/804194CC/80419500.
    constexpr std::uint32_t kDrawDoneFlag = 0x806A285Cu;
    // SDK completion byte: cleared at 804BA088/804B9FF0 and set to 1
    // only by the translated PE finish handler at 804BA380.
    constexpr std::uint32_t kGxFinishedFlag = 0x806A2EF8u;
    if (space.pointer_or_null(kJutXfbManagerPtr, 4u) == nullptr ||
        space.pointer_or_null(kDrawDoneFlag, 1u) == nullptr) return false;
    const auto xfb = space.read_u32(kJutXfbManagerPtr);
    if (space.pointer_or_null(xfb, 0x1Cu) == nullptr ||
        space.read_u32(xfb + 0x10u) != 3u) return false;
    const auto displaying = read_guest_s16(space, xfb + 0x18u);
    if (displaying < 0 || displaying >= 3) return false;
    const auto selected = space.read_u32(
        xfb + static_cast<std::uint32_t>(displaying) * 4u);
    // This selected slot was admitted by the prior completed VI path. New
    // managers/first XFB/indeterminate slots retain the original transaction.
    if (space.pointer_or_null(selected, 4u) == nullptr ||
        state.last_valid_displaying_xfb_manager != xfb ||
        state.last_valid_displaying_xfb_addr != selected) return false;
    if (read_guest_u8(space, kDrawDoneFlag) != 0u) {
        ++state.vi_independent_jut_skip_admissions;
        return true;
    }
    if (space.pointer_or_null(kGxFinishedFlag, 1u) == nullptr) return false;
    const auto drawn = read_guest_s16(space, xfb + 0x16u);
    const auto drawing = read_guest_s16(space, xfb + 0x14u);
    if (drawn < 0 || drawn >= 3 || drawing < 0 || drawing >= 3) return false;
    const auto drawn_addr = space.read_u32(
        xfb + static_cast<std::uint32_t>(drawn) * 4u);
    const auto drawing_addr = space.read_u32(
        xfb + static_cast<std::uint32_t>(drawing) * 4u);
    if (!galaxy::gx::independent_vi_completed_drawn_valid(
            read_guest_u8(space, kGxFinishedFlag), drawn, drawing,
            space.pointer_or_null(drawn_addr, 4u),
            space.pointer_or_null(drawing_addr, 4u))) return false;
    // Normal triple-buffer protocol: endFrame's GXDrawDone returns at
    // 803A0940; beginRender's 8039FCA8 publishes drawing->drawn at 8039FCD4
    // and chooses a different drawing slot. preRetrace 80419404 may select
    // that already-completed drawn slot without waiting for current drawing.
    ++state.vi_independent_completed_drawn_admissions;
    return true;
}

std::string read_guest_string(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address,
    std::size_t max_length = 96) {
    if (address < 0x80000000u || address >= 0x94000000u ||
        address_space.pointer_or_null(address, 1) == nullptr) {
        return {};
    }
    std::string output;
    output.reserve(std::min<std::size_t>(max_length, 32));
    for (std::size_t i = 0; i < max_length; ++i) {
        const std::uint32_t cur = address + static_cast<std::uint32_t>(i);
        if (address_space.pointer_or_null(cur, 1) == nullptr) {
            break;
        }
        const char c = static_cast<char>(read_guest_u8(address_space, cur));
        if (c == '\0') {
            break;
        }
        if (static_cast<unsigned char>(c) < 0x20u ||
            static_cast<unsigned char>(c) >= 0x7Fu) {
            output.push_back('?');
        } else {
            output.push_back(c);
        }
    }
    return output;
}

void dump_native_bt_guest_state(
    std::ostream& output,
    const galaxy::host::GuestAddressSpace& address_space) {
    constexpr std::uint32_t kSysconfSize = 0x4000u;
    constexpr std::uint32_t kScConfBuffer = 0x80657F20u;
    constexpr std::uint32_t kScBgJobStatus = 0x806A30D0u;
    constexpr std::uint32_t kScItemRestSize = 0x806A30D4u;
    constexpr std::uint32_t kScItemNumTotal = 0x806A30D8u;
    constexpr std::uint32_t kScItemIdMaxPlus1 = 0x806A30DCu;
    constexpr std::uint32_t kScItemIdOffsetTblOffset = 0x806A30E0u;
    constexpr std::uint32_t kWudControlBlock = 0x80663920u;
    constexpr std::uint32_t kWudStdDevices = kWudControlBlock + 0xE4u;
    constexpr std::uint32_t kWudStdDeviceSize = 0x60u;
    constexpr std::uint32_t kScArray = 0x80664070u;
    constexpr std::uint32_t kScDeviceSize = 0x46u;
    constexpr std::uint32_t kHidHostControlBlock = 0x80694E38u;
    constexpr std::uint32_t kHidHostDeviceSize = 0x34u;
    constexpr std::uint32_t kWpadControlBlockTable = 0x80660170u;
    constexpr std::uint32_t kGkiTaskFlags = 0x8068E0C8u;
    constexpr std::uint32_t kGkiQueueHeads = 0x8068E1A8u;
    constexpr std::uint32_t kGkiQueueTails = 0x8068E228u;
    constexpr std::uint32_t kGkiPoolTable = 0x8068E2A8u;
    constexpr std::uint32_t kGkiPoolOrder = 0x8068E39Au;
    constexpr std::uint32_t kGkiPoolMask = 0x8068E398u;
    constexpr std::uint32_t kGkiPoolCount = 0x8068E3A3u;
    constexpr std::uint32_t kBteControlBlock = 0x80691CD8u;
    constexpr std::uint32_t kBteApplicationControlBlock = 0x80691F48u;
    constexpr std::uint32_t kBteSdaControlPtr = 0x8069E410u;

    const auto be16 = [&](std::uint32_t address) -> std::uint16_t {
        return static_cast<std::uint16_t>(
            (static_cast<std::uint16_t>(
                 read_guest_u8(address_space, address)) << 8u) |
            read_guest_u8(address_space, address + 1u));
    };
    const auto be32 = [&](std::uint32_t address) -> std::uint32_t {
        return (static_cast<std::uint32_t>(
                    read_guest_u8(address_space, address)) << 24u) |
            (static_cast<std::uint32_t>(
                 read_guest_u8(address_space, address + 1u)) << 16u) |
            (static_cast<std::uint32_t>(
                 read_guest_u8(address_space, address + 2u)) << 8u) |
            read_guest_u8(address_space, address + 3u);
    };
    const auto bdaddr = [&](std::uint32_t address) {
        std::ostringstream text;
        for (std::uint32_t i = 0; i < 6u; ++i) {
            if (i != 0) {
                text << ':';
            }
            text << std::hex << std::uppercase << std::setfill('0')
                 << std::setw(2)
                 << static_cast<unsigned>(read_guest_u8(
                        address_space, address + i));
        }
        return text.str();
    };
    const auto key_prefix = [&](std::uint32_t address) {
        std::ostringstream text;
        for (std::uint32_t i = 0; i < 4u; ++i) {
            if (i != 0) {
                text << ':';
            }
            text << std::hex << std::uppercase << std::setfill('0')
                 << std::setw(2)
                 << static_cast<unsigned>(read_guest_u8(
                        address_space, address + i));
        }
        return text.str();
    };
    const auto conf_ascii = [&](std::uint32_t address, std::size_t length) {
        std::string text;
        text.reserve(length);
        for (std::size_t i = 0; i < length; ++i) {
            const char ch = static_cast<char>(
                read_guest_u8(
                    address_space,
                    address + static_cast<std::uint32_t>(i)));
            text.push_back(
                static_cast<unsigned char>(ch) >= 0x20u &&
                    static_cast<unsigned char>(ch) < 0x7Fu
                    ? ch
                    : '?');
        }
        return text;
    };
    const auto has = [&](std::uint32_t address, std::uint32_t size) {
        return address >= 0x80000000u && address < 0x94000000u &&
            address_space.pointer_or_null(address, size) != nullptr;
    };
    const auto byte_hex = [&](std::uint8_t value) {
        std::ostringstream text;
        text << "0x" << std::hex << std::uppercase << std::setfill('0')
             << std::setw(2) << static_cast<unsigned>(value);
        return text.str();
    };
    const auto bytes_hex =
        [&](std::uint32_t address, std::uint32_t length) {
            std::ostringstream text;
            text << std::hex << std::uppercase << std::setfill('0');
            for (std::uint32_t i = 0; i < length; ++i) {
                if (i != 0u) {
                    text << ' ';
                }
                if (!has(address + i, 1u)) {
                    text << "??";
                } else {
                    text << std::setw(2)
                         << static_cast<unsigned>(
                                read_guest_u8(address_space, address + i));
                }
            }
            return text.str();
        };
    const auto dump_sc_ref = [&](std::uint32_t id, const char* label) {
        const std::uint32_t ref_offset = be32(kScItemIdOffsetTblOffset);
        output << "[bt-reject] SC " << label;
        if (ref_offset == 0u || ref_offset >= kSysconfSize) {
            output << " ref_table=0x" << std::hex << ref_offset
                   << std::dec << " unavailable\n";
            return;
        }
        const std::uint32_t ref_entry =
            kScConfBuffer + ref_offset - id * sizeof(std::uint16_t);
        const std::uint16_t offset_entry = be16(ref_entry);
        const std::uint16_t item_offset =
            offset_entry != 0u ? be16(kScConfBuffer + offset_entry) : 0u;
        output << " ref_entry=0x" << std::hex << std::uppercase
               << std::setfill('0') << std::setw(4) << offset_entry
               << " item=0x" << std::setw(4) << item_offset
               << std::dec << std::setfill(' ');
        if (item_offset == 0u || item_offset >= kSysconfSize) {
            output << '\n';
            return;
        }

        const std::uint32_t item = kScConfBuffer + item_offset;
        const std::uint8_t header = read_guest_u8(address_space, item);
        const std::uint8_t type = header & 0xE0u;
        const std::uint32_t name_length =
            static_cast<std::uint32_t>((header & 0x1Fu) + 1u);
        std::uint32_t cursor = item + 1u + name_length;
        std::uint32_t data_size = 0u;
        if (type == 0x20u) {
            data_size = static_cast<std::uint32_t>(be16(cursor)) + 1u;
            cursor += 2u;
        } else if (type == 0x40u) {
            data_size =
                static_cast<std::uint32_t>(
                    read_guest_u8(address_space, cursor)) +
                1u;
            cursor += 1u;
        } else if (type == 0x60u || type == 0xE0u) {
            data_size = 1u;
        } else if (type == 0x80u) {
            data_size = 2u;
        } else if (type == 0xA0u) {
            data_size = 4u;
        } else if (type == 0xC0u) {
            data_size = 8u;
        }
        output << " type=0x" << std::hex << std::uppercase
               << std::setw(2) << std::setfill('0')
               << static_cast<unsigned>(type)
               << " name=\"" << conf_ascii(item + 1u, name_length)
               << "\" size=0x" << data_size
               << " first=0x" << std::setw(2)
               << static_cast<unsigned>(read_guest_u8(address_space, cursor))
               << std::dec << std::setfill(' ') << '\n';
    };

    output << "[bt-reject] SC bg="
           << static_cast<unsigned>(
                  read_guest_u8(address_space, kScBgJobStatus))
           << " rest=0x" << std::hex << be32(kScItemRestSize)
           << " items=" << std::dec << be32(kScItemNumTotal)
           << " max=" << be32(kScItemIdMaxPlus1)
           << " ref_off=0x" << std::hex << be32(kScItemIdOffsetTblOffset)
           << " magic=\"" << conf_ascii(kScConfBuffer, 4)
           << "\" count=" << std::dec << be16(kScConfBuffer + 4u)
           << '\n';
    dump_sc_ref(0x1Cu, "BT.DINF");
    dump_sc_ref(0x1Du, "BT.CDIF");

    output << "[bt-reject] _scArray num="
           << static_cast<unsigned>(read_guest_u8(address_space, kScArray))
           << '\n';
    for (std::uint32_t i = 0; i < 5u; ++i) {
        const std::uint32_t row = kScArray + 1u + i * kScDeviceSize;
        output << "[bt-reject] _scArray.regist[" << i << "] addr="
               << bdaddr(row)
               << " name=\"" << read_guest_string(address_space, row + 0x06u, 24)
               << "\" key0=" << key_prefix(row + 0x26u) << '\n';
    }

    output << "[bt-reject] _wcb devNums="
           << static_cast<unsigned>(
                  read_guest_u8(address_space, kWudControlBlock + 0x12u))
           << " smpNums="
           << static_cast<unsigned>(
                  read_guest_u8(address_space, kWudControlBlock + 0x13u))
           << " linkKeyState="
           << static_cast<unsigned>(
                  read_guest_u8(address_space, kWudControlBlock + 0x0Eu))
           << " stackState="
           << static_cast<unsigned>(
                  read_guest_u8(address_space, kWudControlBlock + 0x0Fu))
           << '\n';
    for (std::uint32_t i = 0; i < 10u; ++i) {
        const std::uint32_t row = kWudStdDevices + i * kWudStdDeviceSize;
        const unsigned status =
            static_cast<unsigned>(read_guest_u8(address_space, row + 0x59u));
        const unsigned marker =
            static_cast<unsigned>(read_guest_u8(address_space, row + 0x5Cu));
        if (status == 0u && marker == 0u) {
            continue;
        }
        output << "[bt-reject] _wcb.stdDevs[" << i << "] status="
               << status
               << " sync="
               << static_cast<unsigned>(
                      read_guest_u8(address_space, row + 0x5Bu))
               << " mark=" << marker
               << " addr=" << bdaddr(row + 0x40u)
               << " name=\"" << read_guest_string(address_space, row, 24)
               << "\" key0=" << key_prefix(row + 0x46u) << '\n';
    }

    for (std::uint32_t i = 0; i < 10u; ++i) {
        const std::uint32_t row = kHidHostControlBlock + i * kHidHostDeviceSize;
        const unsigned in_use =
            static_cast<unsigned>(read_guest_u8(address_space, row));
        if (in_use == 0u) {
            continue;
        }
        output << "[bt-reject] hh_cb.devices[" << i << "] in_use="
               << in_use
               << " addr=" << bdaddr(row + 1u)
               << " attr=0x" << std::hex << std::uppercase << std::setfill('0')
               << std::setw(4)
               << static_cast<unsigned>(
                      static_cast<std::uint16_t>(
                          read_guest_s16(address_space, row + 0x08u)))
               << std::dec
               << " state="
               << static_cast<unsigned>(
                      read_guest_u8(address_space, row + 0x0Au))
               << " conn_state="
               << static_cast<unsigned>(
                      read_guest_u8(address_space, row + 0x10u))
               << " ctrl=0x" << std::hex << std::uppercase << std::setfill('0')
               << std::setw(4)
               << static_cast<unsigned>(
                      static_cast<std::uint16_t>(
                          read_guest_s16(address_space, row + 0x14u)))
               << " intr=0x" << std::setw(4)
               << static_cast<unsigned>(
                      static_cast<std::uint16_t>(
                          read_guest_s16(address_space, row + 0x16u)))
               << std::dec
               << '\n';
    }

    const std::uint32_t bte_sda_control = be32(kBteSdaControlPtr);
    const unsigned bte_task =
        static_cast<unsigned>(read_guest_u8(address_space, kBteControlBlock + 0x7Du));
    output << "[bt-bte] task=" << bte_task
           << " sda-control=" << hexadecimal(bte_sda_control);
    if (has(bte_sda_control, 4u)) {
        output << " queue="
               << static_cast<unsigned>(
                      read_guest_u8(address_space, bte_sda_control + 0x02u));
    }
    output << " send-callback="
           << hexadecimal(be32(kBteApplicationControlBlock + 0x224u))
           << '\n';

    const unsigned gki_pool_count =
        static_cast<unsigned>(read_guest_u8(address_space, kGkiPoolCount));
    output << "[bt-gki] pool-count=" << gki_pool_count
           << " pool-mask=" << hexadecimal(be16(kGkiPoolMask))
           << " order=" << bytes_hex(kGkiPoolOrder, 9u) << '\n';
    for (std::uint32_t pool = 0; pool < 9u; ++pool) {
        const std::uint32_t row = kGkiPoolTable + pool * 0x10u;
        const std::uint16_t block_size = be16(row + 0x08u);
        const std::uint16_t total = be16(row + 0x0Au);
        const std::uint16_t used = be16(row + 0x0Cu);
        const std::uint16_t max_used = be16(row + 0x0Eu);
        const std::uint32_t head = be32(row);
        const std::uint32_t tail = be32(row + 0x04u);
        if (block_size == 0u && total == 0u && used == 0u &&
            max_used == 0u && head == 0u && tail == 0u) {
            continue;
        }
        output << "[bt-gki] pool[" << pool << "] size=0x"
               << std::hex << std::uppercase << block_size
               << std::dec << " total=" << total
               << " used=" << used
               << " free=" << (total >= used ? total - used : 0)
               << " max-used=" << max_used
               << " free-head=" << hexadecimal(head)
               << " free-tail=" << hexadecimal(tail) << '\n';
    }
    for (std::uint32_t task = 0; task < 8u; ++task) {
        const unsigned active =
            static_cast<unsigned>(read_guest_u8(address_space, kGkiTaskFlags + task));
        if (active == 0u) {
            continue;
        }
        output << "[bt-gki] task[" << task << "] active=" << active;
        bool any_queue = false;
        for (std::uint32_t queue = 0; queue < 4u; ++queue) {
            const std::uint32_t offset = task * 0x10u + queue * 4u;
            const std::uint32_t head = be32(kGkiQueueHeads + offset);
            const std::uint32_t tail = be32(kGkiQueueTails + offset);
            if (head == 0u && tail == 0u) {
                continue;
            }
            any_queue = true;
            output << " q" << queue << "=("
                   << hexadecimal(head) << ',' << hexadecimal(tail) << ')';
            if (has(head, 8u)) {
                output << " q" << queue << "-msg="
                       << bytes_hex(head, 8u);
            }
        }
        if (!any_queue) {
            output << " queues-empty";
        }
        output << '\n';
    }

    const std::uint32_t wpad0 =
        has(kWpadControlBlockTable, sizeof(std::uint32_t))
            ? be32(kWpadControlBlockTable)
            : 0u;
    output << "[bt-wpad] wpad0=" << hexadecimal(wpad0);
    if (!has(wpad0, 0x990u)) {
        output << " unavailable\n";
        return;
    }
    const std::uint32_t ring_base = be32(wpad0 + 0x164u);
    const std::uint32_t ring_capacity =
        be32(wpad0 + 0x168u);
    output << " type=" << hexadecimal(be32(wpad0 + 0x8BCu))
           << " init=" << hexadecimal(be32(wpad0 + 0x8E0u))
           << " ready=" << hexadecimal(be32(wpad0 + 0x8DCu))
           << " cb=" << hexadecimal(be32(wpad0 + 0x89Cu))
           << " cur-report=" << byte_hex(read_guest_u8(address_space, wpad0 + 0x987u))
           << " stat=" << byte_hex(read_guest_u8(address_space, wpad0 + 0x8C1u))
           << " dev=" << byte_hex(read_guest_u8(address_space, wpad0 + 0x8C3u))
           << " active-slot=" << byte_hex(read_guest_u8(address_space, wpad0 + 0x8C8u))
           << " q=(" << byte_hex(read_guest_u8(address_space, wpad0 + 0x160u))
           << ',' << byte_hex(read_guest_u8(address_space, wpad0 + 0x161u))
           << '/' << ring_capacity << ')'
           << " read-buf=" << hexadecimal(be32(wpad0 + 0x974u))
           << " read-addr=" << hexadecimal(be32(wpad0 + 0x978u))
           << " read-err=" << hexadecimal(be32(wpad0 + 0x97Cu))
           << " read-size=0x" << std::hex << std::uppercase
           << static_cast<unsigned>(be16(wpad0 + 0x980u))
           << std::dec
           << " timeout-armed="
           << static_cast<unsigned>(read_guest_u8(address_space, wpad0 + 0x910u))
           << " timeout-flag="
           << static_cast<unsigned>(read_guest_u8(address_space, wpad0 + 0x986u))
           << '\n';

    if (has(ring_base, 0x30u) && ring_capacity != 0u && ring_capacity <= 32u) {
        for (std::uint32_t i = 0; i < ring_capacity; ++i) {
            const std::uint32_t entry = ring_base + i * 0x30u;
            bool non_empty = be32(entry) != 0u || be32(entry + 0x04u) != 0u ||
                be32(entry + 0x08u) != 0u || be32(entry + 0x0Cu) != 0u ||
                be32(entry + 0x2Cu) != 0u;
            const std::uint8_t head_index =
                read_guest_u8(address_space, wpad0 + 0x160u);
            const std::uint8_t tail_index =
                read_guest_u8(address_space, wpad0 + 0x161u);
            const std::uint8_t active_slot =
                read_guest_u8(address_space, wpad0 + 0x8C8u);
            non_empty = non_empty || i == head_index || i == tail_index ||
                i == active_slot;
            if (!non_empty) {
                continue;
            }
            output << "[bt-wpad] qslot[" << i << "] raw="
                   << bytes_hex(entry, 16u)
                   << " cb=" << hexadecimal(be32(entry + 0x2Cu))
                   << '\n';
        }
    }
}

bool mapped_guest_range(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address,
    std::uint32_t size) {
    return address >= 0x80000000u &&
           address < 0x94000000u &&
           address_space.pointer_or_null(address, size) != nullptr;
}

bool trace_fileloader_flow_enabled() {
    static const bool enabled =
        read_env_flag("GALAXY_TRACE_FILELOADER_FLOW", false);
    return enabled;
}

std::uint32_t trace_fileloader_entry_filter() {
    static const std::uint32_t entry =
        read_env_u32_auto("GALAXY_TRACE_FILELOADER_ENTRY", 0u);
    return entry;
}

bool trace_rarc_mount_enabled() {
    static const bool enabled =
        read_env_flag("GALAXY_TRACE_RARC_MOUNT", false);
    return enabled;
}

std::uint64_t trace_rarc_mount_limit() {
    static const std::uint64_t limit =
        read_env_u64("GALAXY_TRACE_RARC_MOUNT_LIMIT", 128u);
    return limit;
}

bool is_fileloader_flow_checkpoint_pc(std::uint32_t guest_pc) {
    switch (guest_pc) {
        case 0x80398458u: // FileLoaderThread::run after loadToMainRAM
        case 0x80398464u: // FileLoaderThread::run after mount archive path
        case 0x803986F8u: // JKRDvdRipper retry after DVDReadPrio -3
        case 0x80398844u: // JKRDvdRipper chunk retry after DVDReadPrio -3
        case 0x8039887Cu: // JKRDvdRipper after Yaz0 wrapper
        case 0x8039897Cu: // JKRDecomp after Yaz0 decode helper
        case 0x80398994u: // JKRDecomp after cache maintenance
        case 0x803989A0u: // JKRDecomp after mutex unlock
        case 0x80398AD4u: // Yaz0 copy-loop checkpoint
        case 0x80398AE4u: // Yaz0 outer-loop checkpoint
        case 0x804AC164u: // OSWakeupThread waiter loop
            return true;
        default:
            return false;
    }
}

const char* fileloader_flow_checkpoint_label(std::uint32_t guest_pc) {
    switch (guest_pc) {
        case 0x80398458u: return "after-load";
        case 0x80398464u: return "after-mount";
        case 0x803986F8u: return "dvd-retry-header";
        case 0x80398844u: return "dvd-retry-chunk";
        case 0x8039887Cu: return "after-yaz0-wrapper";
        case 0x8039897Cu: return "after-yaz0-helper";
        case 0x80398994u: return "after-yaz0-cache";
        case 0x803989A0u: return "after-yaz0-unlock";
        case 0x80398AD4u: return "yaz0-copy-loop";
        case 0x80398AE4u: return "yaz0-outer-loop";
        case 0x804AC164u: return "os-wakeup-loop";
        default: return "unknown";
    }
}

bool is_yaz0_loop_checkpoint_pc(std::uint32_t guest_pc) {
    return guest_pc == 0x80398AD4u || guest_pc == 0x80398AE4u;
}

bool is_yaz0_edge_checkpoint_pc(std::uint32_t guest_pc) {
    switch (guest_pc) {
        case 0x8039887Cu:
        case 0x8039897Cu:
        case 0x80398994u:
        case 0x803989A0u:
            return true;
        default:
            return false;
    }
}

bool is_mem2_address(std::uint32_t address) {
    return address >= 0x90000000u && address < 0x94000000u;
}

bool looks_like_guest_message_queue(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t mq);

void append_message_queue_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t message_queue) {
    if (!mapped_guest_range(address_space, message_queue, 0x20u)) {
        out << " mq=unmapped";
        return;
    }
    out << " mq=" << hexadecimal(message_queue)
        << " mq-msgArray="
        << hexadecimal(address_space.read_u32(message_queue + 0x10u))
        << " mq-msgCount=" << address_space.read_u32(message_queue + 0x14u)
        << " mq-firstIndex=" << address_space.read_u32(message_queue + 0x18u)
        << " mq-usedCount=" << address_space.read_u32(message_queue + 0x1Cu);
}

const char* audio_thread_call_label(std::uint32_t guest_address) {
    switch (guest_address) {
        case 0x804A88E4u: return "OSSendMessage";
        case 0x804A89ACu: return "OSReceiveMessage";
        case 0x804A8A88u: return "OSJamMessage";
        case 0x804ABFBCu: return "OSSleepThread";
        case 0x804878BCu: return "audio-interleave";
        case 0x80494390u: return "JASAudioThread::mix";
        case 0x804945CCu: return "audio-ring-output";
        case 0x804946E8u: return "audio-ring-flush";
        case 0x80494C70u: return "AUDIOMSG_DMA producer";
        case 0x80495DB4u: return "audio-after-mix";
        default: return nullptr;
    }
}

bool is_audio_thread_loop_call_address(std::uint32_t guest_address) {
    return audio_thread_call_label(guest_address) != nullptr;
}

const char* audio_thread_loop_checkpoint_label(std::uint32_t guest_pc) {
    switch (guest_pc) {
        case 0x8049465Cu: return "audio-ring-copy-a";
        case 0x8049468Cu: return "audio-ring-copy-b";
        case 0x80494BE8u: return "audio-msg-unhandled-0";
        case 0x80494BF0u: return "audio-msg-unhandled";
        case 0x80494C18u: return "audio-msg0-after-mix";
        case 0x80494C40u: return "audio-msg1-flush";
        case 0x80494C5Cu: return "audio-msg1-update";
        case 0x80494C6Cu: return "audio-msg-exit";
        case 0x80494CDCu: return "audio-dsp-mail-wait";
        default: return nullptr;
    }
}

bool is_audio_thread_loop_checkpoint_pc(std::uint32_t guest_pc) {
    return audio_thread_loop_checkpoint_label(guest_pc) != nullptr;
}

std::uint32_t audio_thread_object_from_sda(
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context) {
    const std::uint32_t audio_thread_ptr_addr =
        context.gpr[13] + 0xFFFF9874u;
    if (!mapped_guest_range(address_space, audio_thread_ptr_addr, 4u)) {
        return 0;
    }
    return address_space.read_u32(audio_thread_ptr_addr);
}

std::uint32_t resolve_audio_thread_message_queue(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    const auto try_mq = [&](std::uint32_t candidate) -> std::uint32_t {
        return looks_like_guest_message_queue(address_space, candidate)
            ? candidate
            : 0u;
    };
    const auto try_queue_or_mq = [&](std::uint32_t candidate) -> std::uint32_t {
        if (const std::uint32_t mq = try_mq(candidate); mq != 0u) {
            return mq;
        }
        if (candidate >= 8u) {
            return try_mq(candidate - 8u);
        }
        return 0u;
    };

    if (guest_address == 0x804ABFBCu) {
        if (const std::uint32_t mq = try_queue_or_mq(context.gpr[3]);
            mq != 0u) {
            return mq;
        }
    }
    if (guest_address == 0x804A88E4u ||
        guest_address == 0x804A89ACu ||
        guest_address == 0x804A8A88u) {
        if (const std::uint32_t mq = try_mq(context.gpr[3]); mq != 0u) {
            return mq;
        }
    }
    if (const std::uint32_t mq = try_mq(context.gpr[30] + 0x30u);
        mq != 0u) {
        return mq;
    }
    if (const std::uint32_t mq = try_mq(context.gpr[31] + 0x30u);
        mq != 0u) {
        return mq;
    }
    const std::uint32_t audio_thread_object =
        audio_thread_object_from_sda(address_space, context);
    if (audio_thread_object != 0u) {
        if (const std::uint32_t mq = try_mq(audio_thread_object + 0x30u);
            mq != 0u) {
            return mq;
        }
    }
    return 0u;
}

void append_audio_message_queue_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t message_queue) {
    if (message_queue == 0u) {
        out << " mq=unresolved";
        return;
    }
    append_message_queue_summary(out, address_space, message_queue);
    if (!mapped_guest_range(address_space, message_queue, 0x20u)) {
        return;
    }
    const std::uint32_t message_array =
        address_space.read_u32(message_queue + 0x10u);
    const std::uint32_t message_count =
        address_space.read_u32(message_queue + 0x14u);
    const std::uint32_t first_index =
        address_space.read_u32(message_queue + 0x18u);
    const std::uint32_t used_count =
        address_space.read_u32(message_queue + 0x1Cu);
    out << " mq-sendQ=" << hexadecimal(address_space.read_u32(message_queue))
        << " mq-recvQ=" << hexadecimal(address_space.read_u32(message_queue + 8u));
    if (message_count != 0u && message_count < 0x10000u &&
        used_count != 0u &&
        mapped_guest_range(address_space, message_array, message_count * 4u)) {
        const std::uint32_t slot = first_index % message_count;
        out << " mq-nextMsg="
            << hexadecimal(address_space.read_u32(message_array + slot * 4u));
    }
}

void append_audio_thread_state_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const char* label,
    std::uint32_t thread) {
    constexpr std::uint32_t kThreadStateOffset = 0x2C8u;
    constexpr std::uint32_t kThreadSuspendOffset = 0x2CCu;
    constexpr std::uint32_t kThreadPriorityOffset = 0x2D0u;
    constexpr std::uint32_t kThreadQueueOffset = 0x2DCu;
    constexpr std::uint32_t kThreadSrr0Offset = 0x198u;
    constexpr std::uint32_t kThreadLrOffset = 0x84u;
    constexpr std::uint32_t kThreadStackPointerOffset = 0x04u;

    out << ' ' << label << '=' << hexadecimal(thread);
    if (!mapped_guest_range(address_space, thread + kThreadQueueOffset, 4u)) {
        out << " state=unmapped";
        return;
    }
    const std::uint32_t queue_ptr =
        address_space.read_u32(thread + kThreadQueueOffset);
    out << " state="
        << (address_space.read_u32(thread + kThreadStateOffset) >> 16)
        << " suspend="
        << static_cast<std::int32_t>(
               address_space.read_u32(thread + kThreadSuspendOffset))
        << " prio=" << address_space.read_u32(thread + kThreadPriorityOffset)
        << " queue=" << hexadecimal(queue_ptr)
        << " srr0=" << hexadecimal(address_space.read_u32(thread + kThreadSrr0Offset))
        << " lr=" << hexadecimal(address_space.read_u32(thread + kThreadLrOffset))
        << " sp="
        << hexadecimal(address_space.read_u32(thread + kThreadStackPointerOffset));
    if (queue_ptr >= 8u &&
        looks_like_guest_message_queue(address_space, queue_ptr - 8u)) {
        append_audio_message_queue_summary(out, address_space, queue_ptr - 8u);
    }
}

void append_audio_sda_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context) {
    const auto append_sda_word = [&](const char* name, std::uint32_t offset) {
        const std::uint32_t address = context.gpr[13] + offset;
        out << ' ' << name << '@' << hexadecimal(address) << '=';
        if (mapped_guest_range(address_space, address, 4u)) {
            out << hexadecimal(address_space.read_u32(address));
        } else {
            out << "unmapped";
        }
    };

    append_sda_word("sda-audio-write", 0xFFFFDF00u);
    append_sda_word("sda-audio-read", 0xFFFFDEFCu);
    append_sda_word("sda-audio-bufs", 0xFFFFDEF8u);
    append_sda_word("sda-audio-count", 0xFFFF9388u);
    append_sda_word("sda-audio-thread", 0xFFFF9874u);
}

bool audio_thread_trace_relevant(
    const galaxy::host::GuestAddressSpace& address_space,
    galaxy::GuestMemoryV1* memory,
    const galaxy::NativeServicesV1* services,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context,
    std::uint32_t message_queue) {
    const std::uint32_t current_thread = address_space.read_u32(0x800000E4u);
    const std::uint32_t current_context = address_space.read_u32(0x800000D4u);
    const std::uint32_t r1_owner =
        (memory != nullptr && services != nullptr)
            ? guest_r1_owner_thread(memory, services, context.gpr[1])
            : 0u;
    if (current_thread == kRmge01JasAudioThreadContext ||
        current_context == kRmge01JasAudioThreadContext ||
        r1_owner == kRmge01JasAudioThreadContext) {
        return true;
    }

    const std::uint32_t audio_thread_object =
        audio_thread_object_from_sda(address_space, context);
    const std::uint32_t audio_mq =
        audio_thread_object != 0u ? audio_thread_object + 0x30u : 0u;
    if (message_queue != 0u && audio_mq != 0u && message_queue == audio_mq) {
        return true;
    }
    return guest_address == 0x80494C70u;
}

void append_audio_thread_common_summary(
    std::ostream& out,
    const RuntimeState& state,
    const galaxy::host::GuestAddressSpace& address_space,
    galaxy::GuestMemoryV1* memory,
    const galaxy::PpcContext& context,
    std::uint32_t message_queue) {
    const std::uint32_t current_thread = address_space.read_u32(0x800000E4u);
    const std::uint32_t current_context = address_space.read_u32(0x800000D4u);
    const std::uint32_t run_queue_bits = address_space.read_u32(0x806A2D30u);
    const std::uint32_t r1_owner =
        (memory != nullptr && state.services != nullptr)
            ? guest_r1_owner_thread(memory, state.services, context.gpr[1])
            : 0u;
    out << " currentThread=" << hexadecimal(current_thread)
        << " currentCtx=" << hexadecimal(current_context)
        << " runbits=" << hexadecimal(run_queue_bits)
        << " r1-owner=" << hexadecimal(r1_owner)
        << " live=" << format_context_stack(g_live_ctx_stack)
        << " active=" << format_context_stack(g_active_nested_ctx_stack);
    append_audio_thread_state_summary(
        out, address_space, "main", kRmge01MainThreadContext);
    append_audio_thread_state_summary(
        out, address_space, "audio", kRmge01JasAudioThreadContext);
    append_audio_message_queue_summary(out, address_space, message_queue);
    if (mapped_guest_range(address_space, context.gpr[1] + 8u, 4u)) {
        out << " stackMsg="
            << hexadecimal(address_space.read_u32(context.gpr[1] + 8u));
    }
    append_audio_sda_summary(out, address_space, context);
}

void log_audio_thread_call_entry(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context,
    galaxy::GuestMemoryV1* memory) {
    if (!trace_audio_thread_loop_enabled() ||
        !trace_vi_window(
            state,
            "GALAXY_TRACE_AUDIO_THREAD_LOOP_START_VI",
            "GALAXY_TRACE_AUDIO_THREAD_LOOP_END_VI") ||
        state.address_space == nullptr) {
        return;
    }
    const char* label = audio_thread_call_label(guest_address);
    if (label == nullptr) {
        return;
    }

    const auto& address_space = *state.address_space;
    const std::uint32_t message_queue =
        resolve_audio_thread_message_queue(address_space, guest_address, context);
    if (!audio_thread_trace_relevant(
            address_space,
            memory,
            state.services,
            guest_address,
            context,
            message_queue)) {
        return;
    }

    const std::uint64_t log_index = ++state.audio_thread_call_logs;
    const bool frequent_message_call =
        guest_address == 0x804A88E4u || guest_address == 0x804A89ACu ||
        guest_address == 0x804ABFBCu;
    const std::uint64_t cadence = frequent_message_call ? 512u : 2048u;
    if (log_index > 256u && (log_index % cadence) != 0u) {
        return;
    }

    std::cerr << "[audio-thread] #" << log_index
              << " kind=call"
              << " vi=" << state.vi_retrace_count
              << " pc=" << hexadecimal(guest_address)
              << " label=\"" << label << '"'
              << " lr=" << hexadecimal(context.lr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " r3=" << hexadecimal(context.gpr[3])
              << " r4=" << hexadecimal(context.gpr[4])
              << " r5=" << hexadecimal(context.gpr[5])
              << " r30=" << hexadecimal(context.gpr[30])
              << " r31=" << hexadecimal(context.gpr[31]);
    append_audio_thread_common_summary(
        std::cerr, state, address_space, memory, context, message_queue);
    std::cerr << '\n';
}

void log_audio_thread_loop_checkpoint(
    RuntimeState& state,
    std::uint32_t guest_pc,
    std::uint64_t site_count,
    const galaxy::PpcContext& context,
    galaxy::GuestMemoryV1* memory) {
    if (!trace_audio_thread_loop_enabled() ||
        !trace_vi_window(
            state,
            "GALAXY_TRACE_AUDIO_THREAD_LOOP_START_VI",
            "GALAXY_TRACE_AUDIO_THREAD_LOOP_END_VI") ||
        state.address_space == nullptr) {
        return;
    }
    const char* label = audio_thread_loop_checkpoint_label(guest_pc);
    if (label == nullptr) {
        return;
    }

    const auto& address_space = *state.address_space;
    const std::uint32_t message_queue =
        resolve_audio_thread_message_queue(address_space, guest_pc, context);
    if (!audio_thread_trace_relevant(
            address_space,
            memory,
            state.services,
            guest_pc,
            context,
            message_queue)) {
        return;
    }

    const std::uint64_t log_index = ++state.audio_thread_loop_logs;
    const bool ring_copy =
        guest_pc == 0x8049465Cu || guest_pc == 0x8049468Cu;
    const std::uint64_t cadence = ring_copy ? 100000u : 2048u;
    if (log_index > 256u && (site_count % cadence) != 0u) {
        return;
    }

    std::cerr << "[audio-thread] #" << log_index
              << " kind=checkpoint"
              << " vi=" << state.vi_retrace_count
              << " pc=" << hexadecimal(guest_pc)
              << " label=\"" << label << '"'
              << " site=" << site_count
              << " checkpoint=" << state.checkpoint_count
              << " lr=" << hexadecimal(context.lr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " r3=" << hexadecimal(context.gpr[3])
              << " r4=" << hexadecimal(context.gpr[4])
              << " r5=" << hexadecimal(context.gpr[5])
              << " r30=" << hexadecimal(context.gpr[30])
              << " r31=" << hexadecimal(context.gpr[31])
              << " ctr=" << hexadecimal(context.ctr);
    append_audio_thread_common_summary(
        std::cerr, state, address_space, memory, context, message_queue);
    std::cerr << '\n';
}

void append_fileholder_entry_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t entry) {
    if (!mapped_guest_range(address_space, entry, 0x38u)) {
        out << " entry=unmapped";
        return;
    }
    out << " entry=" << hexadecimal(entry)
        << " entry-context=" << hexadecimal(address_space.read_u32(entry + 0x04u))
        << " entry-heap=" << hexadecimal(address_space.read_u32(entry + 0x08u))
        << " entry-state=" << address_space.read_u32(entry + 0x0Cu)
        << " entry-contextSet="
        << static_cast<unsigned>(read_guest_u8(address_space, entry + 0x34u));
    append_message_queue_summary(out, address_space, entry + 0x10u);
}

void append_request_file_info_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t request) {
    if (!mapped_guest_range(address_space, request, 0x90u)) {
        out << " req=unmapped";
        return;
    }
    const std::uint32_t file_entry = address_space.read_u32(request + 0x8Cu);
    out << " req=" << hexadecimal(request)
        << " req-type=" << address_space.read_u32(request + 0x04u)
        << " req-state=" << address_space.read_u32(request + 0x88u)
        << " req-file=\"" << read_guest_string(address_space, request + 0x08u, 128)
        << '"'
        << " req-entry=" << hexadecimal(file_entry);
    if (file_entry != 0u) {
        append_fileholder_entry_summary(out, address_space, file_entry);
    }
}

void append_guest_word_dump(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const char* label,
    std::uint32_t base,
    std::uint32_t bytes) {
    out << ' ' << label << '[' << hexadecimal(base) << "]:";
    for (std::uint32_t off = 0; off < bytes; off += 4u) {
        if (mapped_guest_range(address_space, base + off, 4u)) {
            out << " [+" << std::hex << off << "]="
                << hexadecimal(address_space.read_u32(base + off));
        } else {
            out << " [+" << std::hex << off << "]=<unmapped>";
        }
    }
    out << std::dec;
}

bool fileloader_request_entry_context_matches(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t request,
    std::uint32_t entry_context) {
    if (!mapped_guest_range(address_space, request, 0x90u)) {
        return false;
    }
    const std::uint32_t file_entry = address_space.read_u32(request + 0x8Cu);
    if (!mapped_guest_range(address_space, file_entry, 0x10u)) {
        return false;
    }
    return entry_context == 0u ||
           address_space.read_u32(file_entry + 0x04u) == entry_context;
}

bool looks_like_fileloader_request(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t request) {
    if (!mapped_guest_range(address_space, request, 0x90u)) {
        return false;
    }

    const std::uint32_t type = address_space.read_u32(request + 0x04u);
    const std::uint32_t state = address_space.read_u32(request + 0x88u);
    if (type > 8u || state > 8u) {
        return false;
    }

    const std::string path = read_guest_string(address_space, request + 0x08u, 128);
    return path.size() > 4u &&
           path.front() == '/' &&
           path.find(".arc") != std::string::npos;
}

void append_fileloader_request_stack_candidates(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t stack,
    std::uint32_t entry_context) {
    if (!mapped_guest_range(address_space, stack, 4u)) {
        out << " stackReq=unmapped-stack";
        return;
    }

    const std::uint32_t scan_start = stack >= 0x40u ? stack - 0x40u : stack;
    const std::uint32_t scan_end =
        stack <= 0xFFFFFF3Fu ? stack + 0xC0u : 0xFFFFFFFFu;
    std::uint32_t emitted = 0u;
    for (std::uint32_t address = scan_start;
         address < scan_end && emitted < 8u;
         address += 4u) {
        if (!mapped_guest_range(address_space, address, 4u)) {
            continue;
        }
        const std::uint32_t request = address_space.read_u32(address);
        if (!looks_like_fileloader_request(address_space, request)) {
            continue;
        }
        const bool context_match =
            fileloader_request_entry_context_matches(
                address_space, request, entry_context);
        if (address >= stack) {
            out << " stackReq+0x" << std::hex << (address - stack) << std::dec;
        } else {
            out << " stackReq-0x" << std::hex << (stack - address) << std::dec;
        }
        append_request_file_info_summary(out, address_space, request);
        out << " req-entry-context-match=" << (context_match ? 1 : 0);
        ++emitted;
    }
    if (emitted == 0u) {
        out << " stackReq=none";
    }
}

bool should_log_yaz0_buffer_summary(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t source,
    std::uint32_t compressed_size) {
    if (!mapped_guest_range(address_space, source, 0x10u) ||
        address_space.read_u32(source) != 0x59617A30u) {
        return false;
    }
    const std::uint32_t output_size = address_space.read_u32(source + 0x04u);
    return output_size == 0x20E0u ||
           compressed_size == 0x1180u ||
           output_size == 0x12E20u ||
           compressed_size == 0x9700u;
}

void append_yaz0_buffer_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const char* label,
    std::uint32_t source,
    std::uint32_t dest) {
    out << ' ' << label << " src=" << hexadecimal(source)
        << " dst=" << hexadecimal(dest);
    if (!mapped_guest_range(address_space, source, 0x10u)) {
        out << " srcHeader=unmapped";
        return;
    }

    const std::uint32_t magic = address_space.read_u32(source);
    const std::uint32_t output_size = address_space.read_u32(source + 0x04u);
    out << " srcMagic=" << hexadecimal(magic)
        << " outLen=" << hexadecimal(output_size)
        << " dstEnd=" << hexadecimal(dest + output_size);
    append_guest_word_dump(out, address_space, "src64", source, 0x40u);
    append_guest_word_dump(out, address_space, "dst80", dest, 0x80u);
}

bool get_yaz0_sda_target_summary(
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context,
    std::uint32_t& source_buffer,
    std::uint32_t& source_limit,
    std::uint32_t& consumed_size,
    std::uint32_t& remaining_size,
    std::uint32_t& output_size,
    std::uint32_t& dest_base) {
    const std::uint32_t sda_2870 = context.gpr[13] + 0xFFFFD790u;
    const std::uint32_t sda_2868 = context.gpr[13] + 0xFFFFD798u;
    const std::uint32_t sda_2864 = context.gpr[13] + 0xFFFFD79Cu;
    const std::uint32_t sda_2860 = context.gpr[13] + 0xFFFFD7A0u;
    if (!mapped_guest_range(address_space, sda_2870, 4u) ||
        !mapped_guest_range(address_space, sda_2868, 4u) ||
        !mapped_guest_range(address_space, sda_2864, 4u) ||
        !mapped_guest_range(address_space, sda_2860, 4u)) {
        return false;
    }

    source_buffer = address_space.read_u32(sda_2870);
    source_limit = address_space.read_u32(sda_2868);
    consumed_size = address_space.read_u32(sda_2864);
    remaining_size = address_space.read_u32(sda_2860);
    if (consumed_size == 0x07A0u && remaining_size == 0u) {
        output_size = 0x0F20u;
    } else if (consumed_size == 0x07E0u && remaining_size == 0u) {
        output_size = 0x0F80u;
    } else if (consumed_size == 0x09C0u && remaining_size == 0u) {
        output_size = 0x11E0u;
    } else if (consumed_size == 0x1180u && remaining_size == 0u) {
        output_size = 0x20E0u;
    } else if (consumed_size == 0x9700u && remaining_size == 0u) {
        output_size = 0x12E20u;
    } else {
        return false;
    }
    if (context.gpr[30] < output_size) {
        return false;
    }
    dest_base = context.gpr[30] - output_size;
    return mapped_guest_range(address_space, source_buffer, 0x10u) &&
           mapped_guest_range(address_space, dest_base, 0x10u);
}

bool should_log_yaz0_sda_target(
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context) {
    std::uint32_t source_buffer = 0;
    std::uint32_t source_limit = 0;
    std::uint32_t consumed_size = 0;
    std::uint32_t remaining_size = 0;
    std::uint32_t output_size = 0;
    std::uint32_t dest_base = 0;
    return get_yaz0_sda_target_summary(
        address_space,
        context,
        source_buffer,
        source_limit,
        consumed_size,
        remaining_size,
        output_size,
        dest_base);
}

bool should_log_yaz0_sda_target_checkpoint(
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context,
    std::uint64_t already_logged) {
    if (already_logged >= 2048u) {
        return false;
    }

    std::uint32_t source_buffer = 0;
    std::uint32_t source_limit = 0;
    std::uint32_t consumed_size = 0;
    std::uint32_t remaining_size = 0;
    std::uint32_t output_size = 0;
    std::uint32_t dest_base = 0;
    if (!get_yaz0_sda_target_summary(
            address_space,
            context,
            source_buffer,
            source_limit,
            consumed_size,
            remaining_size,
            output_size,
            dest_base)) {
        return false;
    }

    if (already_logged < 16u) {
        return true;
    }
    if (context.gpr[31] < dest_base) {
        return false;
    }
    const std::uint32_t progress = context.gpr[31] - dest_base;
    return (progress % 0x400u) == 0u ||
           progress + 0x100u >= output_size;
}

void append_yaz0_sda_target_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context,
    const char* label) {
    std::uint32_t source_buffer = 0;
    std::uint32_t source_limit = 0;
    std::uint32_t consumed_size = 0;
    std::uint32_t remaining_size = 0;
    std::uint32_t output_size = 0;
    std::uint32_t dest_base = 0;
    if (!get_yaz0_sda_target_summary(
            address_space,
            context,
            source_buffer,
            source_limit,
            consumed_size,
            remaining_size,
            output_size,
            dest_base)) {
        out << ' ' << label << "=unavailable";
        return;
    }

    const std::uint64_t output_progress =
        context.gpr[31] >= dest_base
            ? static_cast<std::uint64_t>(context.gpr[31] - dest_base)
            : 0u;
    out << ' ' << label
        << " srcBuf=" << hexadecimal(source_buffer)
        << " srcLimit=" << hexadecimal(source_limit)
        << " srcCursor=" << hexadecimal(context.gpr[3])
        << " consumed=" << hexadecimal(consumed_size)
        << " remaining=" << hexadecimal(remaining_size)
        << " dstBase=" << hexadecimal(dest_base)
        << " dstCursor=" << hexadecimal(context.gpr[31])
        << " dstEnd=" << hexadecimal(context.gpr[30])
        << " outLen=" << hexadecimal(output_size)
        << " outProgress=" << output_progress;
    append_guest_word_dump(out, address_space, "srcBuf80", source_buffer, 0x80u);
    if (context.gpr[3] != source_buffer &&
        mapped_guest_range(address_space, context.gpr[3], 0x40u)) {
        append_guest_word_dump(
            out,
            address_space,
            "srcCursor40",
            context.gpr[3],
            0x40u);
    }
    append_guest_word_dump(out, address_space, "dst80", dest_base, 0x80u);
    if (context.gpr[31] != dest_base &&
        mapped_guest_range(address_space, context.gpr[31], 0x40u)) {
        append_guest_word_dump(
            out,
            address_space,
            "dstCursor40",
            context.gpr[31],
            0x40u);
    }
}

void append_watched_fileholder_summary(
    std::ostream& out,
    const RuntimeState& state,
    const galaxy::host::GuestAddressSpace& address_space) {
    if (state.fileholder_watch_entry == 0u) {
        return;
    }

    out << " watchedEntry=" << hexadecimal(state.fileholder_watch_entry)
        << " watchedMQ=" << hexadecimal(state.fileholder_watch_entry + 0x10u)
        << " watchedSleepQ=" << hexadecimal(state.fileholder_watch_queue)
        << " watchedAgeVi="
        << (state.vi_retrace_count >= state.fileholder_watch_vi
                ? state.vi_retrace_count - state.fileholder_watch_vi
                : 0u);
    append_fileholder_entry_summary(
        out,
        address_space,
        state.fileholder_watch_entry);
}

void append_yaz0_sda_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context) {
    out << " r3=" << hexadecimal(context.gpr[3])
        << " r4=" << hexadecimal(context.gpr[4])
        << " r6=" << hexadecimal(context.gpr[6])
        << " r7=" << hexadecimal(context.gpr[7])
        << " r8=" << hexadecimal(context.gpr[8])
        << " r13=" << hexadecimal(context.gpr[13])
        << " r30=" << hexadecimal(context.gpr[30])
        << " r31=" << hexadecimal(context.gpr[31]);

    const auto append_sda_word = [&](const char* name, std::uint32_t offset) {
        const std::uint32_t address = context.gpr[13] + offset;
        out << ' ' << name << '@' << hexadecimal(address) << '=';
        if (mapped_guest_range(address_space, address, 4u)) {
            out << hexadecimal(address_space.read_u32(address));
        } else {
            out << "unmapped";
        }
    };

    append_sda_word("sda-2870", 0xFFFFD790u);
    append_sda_word("sda-286C", 0xFFFFD794u);
    append_sda_word("sda-2868", 0xFFFFD798u);
    append_sda_word("sda-2864", 0xFFFFD79Cu);
    append_sda_word("sda-2860", 0xFFFFD7A0u);
    append_sda_word("sda-285C", 0xFFFFD7A4u);
}

void record_yaz0_handoff_checkpoint(
    RuntimeState& state,
    const galaxy::PpcContext& context) {
    if (!state.trace_yaz0_handoff || state.address_space == nullptr) {
        return;
    }

    const auto& address_space = *state.address_space;
    const std::uint32_t source_buffer_address =
        context.gpr[13] + 0xFFFFD790u;
    const std::uint32_t source_limit_address =
        context.gpr[13] + 0xFFFFD794u;
    const std::uint32_t source_consumed_address =
        context.gpr[13] + 0xFFFFD79Cu;
    const std::uint32_t source_remaining_address =
        context.gpr[13] + 0xFFFFD7A0u;
    if (!mapped_guest_range(address_space, source_buffer_address, 4u) ||
        !mapped_guest_range(address_space, source_limit_address, 4u) ||
        !mapped_guest_range(address_space, source_consumed_address, 4u) ||
        !mapped_guest_range(address_space, source_remaining_address, 4u)) {
        return;
    }

    const std::uint32_t dest_base = context.gpr[27];
    const std::uint32_t output_size = context.gpr[29];
    const std::uint32_t dest_end = context.gpr[30];
    if (output_size == 0u || output_size > 0x04000000u ||
        dest_end != dest_base + output_size ||
        !mapped_guest_range(address_space, dest_base, 1u)) {
        return;
    }

    RuntimeState::Yaz0HandoffRecord* record = nullptr;
    if (state.yaz0_handoff_active <
        RuntimeState::kYaz0HandoffRecordCount) {
        auto& active =
            state.yaz0_handoff_records[state.yaz0_handoff_active];
        if (active.dest_base == dest_base &&
            active.output_size == output_size &&
            active.file_info == context.gpr[26] &&
            context.gpr[31] >= active.dest_cursor) {
            record = &active;
        }
    }

    if (record == nullptr) {
        const std::size_t index = state.yaz0_handoff_next;
        state.yaz0_handoff_next =
            (state.yaz0_handoff_next + 1u) %
            RuntimeState::kYaz0HandoffRecordCount;
        state.yaz0_handoff_active = index;
        auto& next = state.yaz0_handoff_records[index];
        next = {};
        next.sequence = ++state.yaz0_handoff_sequence;
        next.first_vi = state.vi_retrace_count;
        next.file_info = context.gpr[26];
        next.compressed_size = context.gpr[28];
        next.dest_base = dest_base;
        next.dest_end = dest_end;
        next.output_size = output_size;
        next.first_source_cursor = context.gpr[3];
        next.first_source_consumed =
            address_space.read_u32(source_consumed_address);
        next.first_source_remaining =
            address_space.read_u32(source_remaining_address);
        next.first_dest_cursor = context.gpr[31];
        next.first_r7 = context.gpr[7];
        next.first_r8 = context.gpr[8];
        next.first_cr = context.cr;
        record = &next;

        const std::uint32_t source_buffer =
            address_space.read_u32(source_buffer_address);
        if (mapped_guest_range(address_space, source_buffer, 0x10u)) {
            for (std::size_t word = 0; word < 4u; ++word) {
                record->source_words[word] = address_space.read_u32(
                    source_buffer + static_cast<std::uint32_t>(word * 4u));
            }
        }
        if (mapped_guest_range(address_space, dest_base, 0x10u)) {
            for (std::size_t word = 0; word < 4u; ++word) {
                record->dest_words[word] = address_space.read_u32(
                    dest_base + static_cast<std::uint32_t>(word * 4u));
            }
        }
        if (mapped_guest_range(address_space, context.gpr[3], 0x10u)) {
            for (std::size_t word = 0; word < 4u; ++word) {
                record->first_source_cursor_words[word] =
                    address_space.read_u32(
                        context.gpr[3] +
                        static_cast<std::uint32_t>(word * 4u));
            }
        }
    }

    record->last_vi = state.vi_retrace_count;
    ++record->checkpoints;
    record->source_buffer = address_space.read_u32(source_buffer_address);
    record->source_limit = address_space.read_u32(source_limit_address);
    record->source_cursor = context.gpr[3];
    record->source_consumed =
        address_space.read_u32(source_consumed_address);
    record->source_remaining =
        address_space.read_u32(source_remaining_address);
    record->dest_cursor = context.gpr[31];
    if (record->dest_cursor <= record->dest_end &&
        record->dest_end - record->dest_cursor <= 0x40u &&
        mapped_guest_range(address_space, record->dest_base, 0x10u)) {
        for (std::size_t word = 0; word < 4u; ++word) {
            record->final_dest_words[word] = address_space.read_u32(
                record->dest_base +
                static_cast<std::uint32_t>(word * 4u));
        }
        record->final_dest_words_valid = true;
    }
}

void log_fileloader_header_copy_checkpoint(
    RuntimeState& state,
    std::uint32_t guest_pc,
    const galaxy::PpcContext& context) {
    static const bool enabled =
        read_env_flag("GALAXY_TRACE_FILELOADER_HEADER_COPY", false);
    if (!enabled || guest_pc != 0x803E7528u ||
        state.address_space == nullptr ||
        context.gpr[3] < 0x10u || context.gpr[4] < 0x10u) {
        return;
    }

    const std::uint32_t destination = context.gpr[3] - 0x10u;
    const std::uint32_t source = context.gpr[4] - 0x10u;
    const bool watched_copy =
        destination == 0x808DE180u || destination == 0x808FE160u;
    if (!watched_copy || context.ctr != 1u) {
        return;
    }

    static std::uint64_t count = 0;
    ++count;
    std::cout << "[fileloader-header-copy] #" << count
              << " vi=" << state.vi_retrace_count
              << " src=" << hexadecimal(source)
              << " dst=" << hexadecimal(destination)
              << " ctr=" << context.ctr
              << " currentCtx="
              << hexadecimal(
                     state.address_space->read_u32(0x800000D4u))
              << " currentThread="
              << hexadecimal(
                     state.address_space->read_u32(0x800000E4u))
              << " lastSaved=" << hexadecimal(g_last_saved_ctx)
              << " live=" << format_context_stack(g_live_ctx_stack)
              << " active="
              << format_context_stack(g_active_nested_ctx_stack);
    append_guest_word_dump(
        std::cout, *state.address_space, "src20", source, 0x20u);
    append_guest_word_dump(
        std::cout, *state.address_space, "dst20", destination, 0x20u);
    std::cout << '\n';
}

void dump_yaz0_handoff_records(
    std::ostream& out,
    const RuntimeState& state,
    const char* reason) {
    if (!state.trace_yaz0_handoff || state.yaz0_handoff_sequence == 0u) {
        return;
    }

    const std::uint64_t first_sequence =
        state.yaz0_handoff_sequence >=
                RuntimeState::kYaz0HandoffRecordCount
            ? state.yaz0_handoff_sequence -
                  RuntimeState::kYaz0HandoffRecordCount + 1u
            : 1u;
    out << "[yaz0-handoff] reason=" << reason
        << " records="
        << (state.yaz0_handoff_sequence - first_sequence + 1u)
        << " latest=" << state.yaz0_handoff_sequence << '\n';
    for (std::uint64_t sequence = first_sequence;
         sequence <= state.yaz0_handoff_sequence;
         ++sequence) {
        const auto& record = state.yaz0_handoff_records[
            static_cast<std::size_t>(
                (sequence - 1u) %
                RuntimeState::kYaz0HandoffRecordCount)];
        if (record.sequence != sequence) {
            continue;
        }
        out << "[yaz0-handoff] seq=" << record.sequence
            << " vi=" << record.first_vi << '-' << record.last_vi
            << " checkpoints=" << record.checkpoints
            << " fileInfo=" << hexadecimal(record.file_info)
            << " src=" << hexadecimal(record.source_buffer)
            << " srcLimit=" << hexadecimal(record.source_limit)
            << " firstSrcCursor="
            << hexadecimal(record.first_source_cursor)
            << " srcCursor=" << hexadecimal(record.source_cursor)
            << " firstConsumed="
            << hexadecimal(record.first_source_consumed)
            << " consumed=" << hexadecimal(record.source_consumed)
            << " firstRemaining="
            << hexadecimal(record.first_source_remaining)
            << " remaining=" << hexadecimal(record.source_remaining)
            << " compressed=" << hexadecimal(record.compressed_size)
            << " dst=" << hexadecimal(record.dest_base)
            << " firstDstCursor="
            << hexadecimal(record.first_dest_cursor)
            << " dstCursor=" << hexadecimal(record.dest_cursor)
            << " dstEnd=" << hexadecimal(record.dest_end)
            << " outLen=" << hexadecimal(record.output_size)
            << " firstR7=" << hexadecimal(record.first_r7)
            << " firstR8=" << hexadecimal(record.first_r8)
            << " firstCR=" << hexadecimal(record.first_cr)
            << " srcWords=";
        for (const std::uint32_t word : record.source_words) {
            out << hexadecimal(word) << ',';
        }
        out << " firstSrcCursorWords=";
        for (const std::uint32_t word : record.first_source_cursor_words) {
            out << hexadecimal(word) << ',';
        }
        out << " dstWords=";
        for (const std::uint32_t word : record.dest_words) {
            out << hexadecimal(word) << ',';
        }
        out << " finalDstWords=";
        if (record.final_dest_words_valid) {
            for (const std::uint32_t word : record.final_dest_words) {
                out << hexadecimal(word) << ',';
            }
        } else {
            out << "unavailable";
        }
        out << '\n';
    }
}

void log_fileholder_wait(
    RuntimeState& state,
    const galaxy::PpcContext& context,
    std::uint32_t receive_queue) {
    if (!trace_fileloader_flow_enabled() ||
        state.address_space == nullptr ||
        receive_queue < 0x80000018u ||
        receive_queue >= 0x94000000u) {
        return;
    }

    const auto& address_space = *state.address_space;
    const std::uint32_t entry = receive_queue - 0x18u;
    const std::uint32_t entry_filter = trace_fileloader_entry_filter();
    if (entry_filter != 0u && entry != entry_filter) {
        return;
    }
    const std::uint32_t message_queue = receive_queue - 0x08u;
    const bool plausible_fileholder =
        mapped_guest_range(address_space, entry, 0x38u) &&
        address_space.read_u32(message_queue + 0x14u) <= 4u;
    if (!plausible_fileholder) {
        return;
    }

    const bool changed = state.fileholder_watch_queue != receive_queue;
    state.fileholder_watch_queue = receive_queue;
    state.fileholder_watch_entry = entry;
    state.fileholder_watch_vi = state.vi_retrace_count;
    if (changed) {
        state.fileholder_watch_decomp_logs = 0;
        state.fileholder_watch_mq_logs = 0;
    }
    const std::uint64_t log_index = ++state.fileholder_wait_logs;
    if (!changed && log_index > 64u && (log_index % 1024u) != 0u) {
        return;
    }

    std::cerr << "[fileholder-wait] #" << log_index
              << " vi=" << state.vi_retrace_count
              << " q=" << hexadecimal(receive_queue)
              << " pc=" << hexadecimal(context.pc)
              << " lr=" << hexadecimal(context.lr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " currentThread="
              << hexadecimal(address_space.read_u32(0x800000E4u))
              << " currentCtx="
              << hexadecimal(address_space.read_u32(0x800000D4u));
    append_fileholder_entry_summary(std::cerr, address_space, entry);
    std::cerr << '\n';
}

void log_fileloader_flow_checkpoint(
    RuntimeState& state,
    std::uint32_t guest_pc,
    const galaxy::PpcContext& context) {
    if (!trace_fileloader_flow_enabled() || state.address_space == nullptr) {
        return;
    }

    const auto& address_space = *state.address_space;
    const std::uint32_t entry_filter = trace_fileloader_entry_filter();
    if (entry_filter != 0u &&
        state.fileholder_watch_entry != entry_filter) {
        return;
    }
    const std::uint64_t log_index = ++state.fileloader_flow_logs;
    const bool rare_log = log_index <= 96u || (log_index % 2048u) == 0u;
    const bool watch_active = state.fileholder_watch_entry != 0u;
    const bool yaz0_loop = is_yaz0_loop_checkpoint_pc(guest_pc);
    const bool yaz0_edge = is_yaz0_edge_checkpoint_pc(guest_pc);
    const bool yaz0_buffer_target =
        yaz0_edge &&
        should_log_yaz0_buffer_summary(
            address_space, context.gpr[26], context.gpr[28]);
    const bool yaz0_sda_target =
        (yaz0_loop || yaz0_edge) &&
        should_log_yaz0_sda_target(address_space, context);
    const bool yaz0_sda_target_log =
        yaz0_sda_target &&
        should_log_yaz0_sda_target_checkpoint(
            address_space,
            context,
            state.fileloader_yaz0_target_logs);
    if (!rare_log &&
        guest_pc != 0x80398458u &&
        guest_pc != 0x80398464u &&
        !yaz0_loop &&
        !(watch_active && yaz0_edge) &&
        !yaz0_buffer_target &&
        !yaz0_sda_target_log) {
        return;
    }

    if (yaz0_loop) {
        const std::uint64_t decomp_index = ++state.fileloader_decomp_logs;
        const std::uint64_t watch_decomp_index =
            watch_active ? ++state.fileholder_watch_decomp_logs : 0u;
        const bool log_loop =
            decomp_index <= 64u ||
            (watch_active &&
             (watch_decomp_index <= 64u ||
              (watch_decomp_index % 1024u) == 0u)) ||
            (!watch_active && (decomp_index % 8192u) == 0u) ||
            yaz0_sda_target_log;
        if (!log_loop) {
            return;
        }

        std::cerr << "[fileloader-decomp] #" << decomp_index
                  << " watch#=" << watch_decomp_index
                  << " vi=" << state.vi_retrace_count
                  << " pc=" << hexadecimal(guest_pc)
                  << ' ' << fileloader_flow_checkpoint_label(guest_pc)
                  << " r1=" << hexadecimal(context.gpr[1])
                  << " lr=" << hexadecimal(context.lr)
                  << " currentThread="
                  << hexadecimal(address_space.read_u32(0x800000E4u))
                  << " currentCtx="
                  << hexadecimal(address_space.read_u32(0x800000D4u));
        append_yaz0_sda_summary(std::cerr, address_space, context);
        if (yaz0_sda_target_log) {
            ++state.fileloader_yaz0_target_logs;
            append_yaz0_sda_target_summary(
                std::cerr,
                address_space,
                context,
                "yaz0-target");
        }
        append_watched_fileholder_summary(std::cerr, state, address_space);
        std::cerr << '\n';
        return;
    }

    if (guest_pc == 0x80398458u || guest_pc == 0x80398464u) {
        const std::uint32_t request =
            mapped_guest_range(address_space, context.gpr[1] + 0x08u, 4u)
                ? address_space.read_u32(context.gpr[1] + 0x08u)
                : 0u;
        std::cerr << "[fileloader-flow] #" << log_index
                  << " vi=" << state.vi_retrace_count
                  << " pc=" << hexadecimal(guest_pc)
                  << (guest_pc == 0x80398464u ? " after-mount" : " after-load")
                  << " r1=" << hexadecimal(context.gpr[1])
                  << " lr=" << hexadecimal(context.lr)
                  << " currentThread="
                  << hexadecimal(address_space.read_u32(0x800000E4u))
                  << " currentCtx="
                  << hexadecimal(address_space.read_u32(0x800000D4u));
        append_request_file_info_summary(std::cerr, address_space, request);
        append_watched_fileholder_summary(std::cerr, state, address_space);
        std::cerr << '\n';
        return;
    }

    if (yaz0_edge) {
        std::cerr << "[fileloader-flow] #" << log_index
                  << " vi=" << state.vi_retrace_count
                  << " pc=" << hexadecimal(guest_pc)
                  << ' ' << fileloader_flow_checkpoint_label(guest_pc)
                  << " r1=" << hexadecimal(context.gpr[1])
                  << " lr=" << hexadecimal(context.lr)
                  << " currentThread="
                  << hexadecimal(address_space.read_u32(0x800000E4u))
                  << " currentCtx="
                  << hexadecimal(address_space.read_u32(0x800000D4u));
        append_yaz0_sda_summary(std::cerr, address_space, context);
        if (yaz0_buffer_target) {
            append_yaz0_buffer_summary(
                std::cerr,
                address_space,
                "yaz0-edge-buffer",
                context.gpr[26],
                context.gpr[27]);
        }
        if (yaz0_sda_target_log) {
            ++state.fileloader_yaz0_target_logs;
            append_yaz0_sda_target_summary(
                std::cerr,
                address_space,
                context,
                "yaz0-target");
        }
        append_watched_fileholder_summary(std::cerr, state, address_space);
        std::cerr << '\n';
        return;
    }

    if (guest_pc == 0x803986F8u || guest_pc == 0x80398844u) {
        std::cerr << "[fileloader-flow] #" << log_index
                  << " vi=" << state.vi_retrace_count
                  << " pc=" << hexadecimal(guest_pc)
                  << " dvd-retry"
                  << " r1=" << hexadecimal(context.gpr[1])
                  << " lr=" << hexadecimal(context.lr)
                  << " r3=" << hexadecimal(context.gpr[3])
                  << " r26=" << hexadecimal(context.gpr[26])
                  << " r27=" << hexadecimal(context.gpr[27])
                  << " r28=" << hexadecimal(context.gpr[28])
                  << " r29=" << hexadecimal(context.gpr[29])
                  << " r30=" << hexadecimal(context.gpr[30])
                  << " r31=" << hexadecimal(context.gpr[31])
                  << " ipc-pending="
                  << (address_space.ipc_interrupt_pending() ? 1 : 0)
                  << " currentThread="
                  << hexadecimal(address_space.read_u32(0x800000E4u))
                  << " currentCtx="
                  << hexadecimal(address_space.read_u32(0x800000D4u));
        append_watched_fileholder_summary(std::cerr, state, address_space);
        std::cerr << '\n';
    }
}

void log_os_wakeup_checkpoint(
    RuntimeState& state,
    std::uint32_t guest_pc,
    const galaxy::PpcContext& context) {
    if (!trace_fileloader_flow_enabled() ||
        state.address_space == nullptr ||
        guest_pc != 0x804AC164u) {
        return;
    }

    const auto& address_space = *state.address_space;
    const std::uint32_t queue = context.gpr[30];
    const bool interesting =
        queue == 0x806A2F10u ||
        is_mem2_address(queue) ||
        (state.fileholder_watch_queue != 0u &&
         queue == state.fileholder_watch_queue);
    if (!interesting) {
        return;
    }

    const std::uint64_t log_index = ++state.os_wakeup_trace_logs;
    if (log_index > 256u && (log_index % 2048u) != 0u) {
        return;
    }

    const std::uint32_t wake_thread = context.gpr[8];
    std::cerr << "[oswakeup-trace] #" << log_index
              << " vi=" << state.vi_retrace_count
              << " q=" << hexadecimal(queue)
              << " pc=" << hexadecimal(guest_pc)
              << " lr=" << hexadecimal(context.lr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " r3=" << hexadecimal(context.gpr[3])
              << " r8=" << hexadecimal(context.gpr[8])
              << " msr=" << hexadecimal(context.msr)
              << " dispatchVi=" << (state.dispatching_vi_retrace ? 1 : 0)
              << " dispatchIpc=" << (state.dispatching_ipc_interrupt ? 1 : 0)
              << " dispatchDsp=" << state.dsp_interrupt_depth
              << " live=" << format_context_stack(g_live_ctx_stack)
              << " active=" << format_context_stack(g_active_nested_ctx_stack)
              << " wakeThread=" << hexadecimal(wake_thread)
              << " currentThread="
              << hexadecimal(address_space.read_u32(0x800000E4u))
              << " currentCtx="
              << hexadecimal(address_space.read_u32(0x800000D4u))
              << " watchedQ=" << hexadecimal(state.fileholder_watch_queue);
    if (queue >= 0x80000008u && mapped_guest_range(address_space, queue - 8u, 0x20u)) {
        append_message_queue_summary(std::cerr, address_space, queue - 8u);
    }
    if (mapped_guest_range(address_space, wake_thread + 0x2C8u, 0x38u)) {
        std::cerr << " wake.state="
                  << address_space.read_u32(wake_thread + 0x2C8u)
                  << " wake.suspend="
                  << static_cast<std::int32_t>(
                         address_space.read_u32(wake_thread + 0x2CCu))
                  << " wake.prio="
                  << address_space.read_u32(wake_thread + 0x2D0u)
                  << " wake.queue="
                  << hexadecimal(address_space.read_u32(wake_thread + 0x2DCu))
                  << " wake.srr0="
                  << hexadecimal(address_space.read_u32(wake_thread + 0x198u));
    }
    std::cerr << '\n';
}

void log_fileloader_call_entry(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    if (!trace_fileloader_flow_enabled() || state.address_space == nullptr) {
        return;
    }

    const auto& address_space = *state.address_space;
    const std::uint32_t entry_filter = trace_fileloader_entry_filter();
    const bool message_call =
        guest_address == 0x804A88E4u ||
        guest_address == 0x804A89ACu ||
        guest_address == 0x804A8A88u;
    if (message_call) {
        const std::uint32_t watched_mq =
            state.fileholder_watch_entry != 0u
                ? state.fileholder_watch_entry + 0x10u
                : 0u;
        if (watched_mq == 0u || context.gpr[3] != watched_mq) {
            return;
        }

        const std::uint64_t log_index = ++state.fileholder_watch_mq_logs;
        if (log_index > 128u && (log_index % 256u) != 0u) {
            return;
        }

        const char* op = guest_address == 0x804A88E4u
            ? "send"
            : (guest_address == 0x804A8A88u ? "jam" : "recv");
        std::cerr << "[fileholder-mq] #" << log_index
                  << " vi=" << state.vi_retrace_count
                  << " op=" << op
                  << " addr=" << hexadecimal(guest_address)
                  << " mq=" << hexadecimal(context.gpr[3])
                  << " msg=" << hexadecimal(context.gpr[4])
                  << " flags=" << hexadecimal(context.gpr[5])
                  << " lr=" << hexadecimal(context.lr)
                  << " r1=" << hexadecimal(context.gpr[1])
                  << " currentThread="
                  << hexadecimal(address_space.read_u32(0x800000E4u))
                  << " currentCtx="
                  << hexadecimal(address_space.read_u32(0x800000D4u));
        append_message_queue_summary(std::cerr, address_space, context.gpr[3]);
        append_watched_fileholder_summary(std::cerr, state, address_space);
        std::cerr << '\n';
        return;
    }

    const char* label = nullptr;
    switch (guest_address) {
        case 0x80397A38u: label = "FileHolderFileEntry::waitReadDone"; break;
        case 0x80397A84u: label = "FileHolderFileEntry::setContext"; break;
        case 0x803983DCu: label = "FileLoaderThread::run"; break;
        case 0x80398468u: label = "FileLoaderThread::loadToMainRAM"; break;
        case 0x803984BCu:
            label = "FileLoaderThread::mountArchiveAndStartCreateResource";
            break;
        case 0x803989BCu: label = "JKRDecomp::decodeYaz0"; break;
        case 0x803CE030u: label = "MR::createAndAddArchive"; break;
        default: return;
    }

    const auto request_targets_watch = [&]() {
        if (state.fileholder_watch_entry == 0u ||
            (guest_address != 0x80398468u &&
             guest_address != 0x803984BCu)) {
            return false;
        }
        const std::uint32_t request = context.gpr[4];
        return mapped_guest_range(address_space, request + 0x8Cu, 4u) &&
               address_space.read_u32(request + 0x8Cu) ==
                   state.fileholder_watch_entry;
    };
    const auto request_targets_filter = [&]() {
        if (entry_filter == 0u ||
            (guest_address != 0x80398468u &&
             guest_address != 0x803984BCu)) {
            return false;
        }
        const std::uint32_t request = context.gpr[4];
        return mapped_guest_range(address_space, request + 0x8Cu, 4u) &&
               address_space.read_u32(request + 0x8Cu) == entry_filter;
    };
    const bool watch_entry_call =
        state.fileholder_watch_entry != 0u &&
        (guest_address == 0x80397A38u ||
         guest_address == 0x80397A84u) &&
        context.gpr[3] == state.fileholder_watch_entry;
    const bool watch_request_call = request_targets_watch();
    const bool filter_entry_call =
        entry_filter != 0u &&
        (guest_address == 0x80397A38u ||
         guest_address == 0x80397A84u) &&
        context.gpr[3] == entry_filter;
    const bool filter_request_call = request_targets_filter();
    const bool yaz0_buffer_call =
        guest_address == 0x803989BCu &&
        should_log_yaz0_buffer_summary(
            address_space, context.gpr[3], context.gpr[5]);
    if (entry_filter != 0u &&
        !filter_entry_call &&
        !filter_request_call &&
        !watch_entry_call &&
        !watch_request_call &&
        !yaz0_buffer_call) {
        return;
    }
    const std::uint64_t log_index = ++state.fileloader_flow_logs;
    if (!watch_entry_call &&
        !watch_request_call &&
        !filter_entry_call &&
        !filter_request_call &&
        !yaz0_buffer_call &&
        log_index > 256u &&
        (log_index % 2048u) != 0u) {
        return;
    }

    std::cerr << "[fileloader-call] #" << log_index
              << " vi=" << state.vi_retrace_count
              << " fn=" << label
              << " addr=" << hexadecimal(guest_address)
              << " lr=" << hexadecimal(context.lr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " r3=" << hexadecimal(context.gpr[3])
              << " r4=" << hexadecimal(context.gpr[4])
              << " r5=" << hexadecimal(context.gpr[5])
              << " currentThread="
              << hexadecimal(address_space.read_u32(0x800000E4u))
              << " currentCtx="
              << hexadecimal(address_space.read_u32(0x800000D4u));
    if (guest_address == 0x80397A38u || guest_address == 0x80397A84u) {
        append_fileholder_entry_summary(std::cerr, address_space, context.gpr[3]);
    } else if (guest_address == 0x80398468u ||
               guest_address == 0x803984BCu) {
        append_request_file_info_summary(std::cerr, address_space, context.gpr[4]);
    } else if (guest_address == 0x803989BCu) {
        append_yaz0_buffer_summary(
            std::cerr,
            address_space,
            "yaz0-entry-buffer",
            context.gpr[3],
            context.gpr[4]);
    } else if (guest_address == 0x803CE030u) {
        std::cerr << " archive-path=\""
                  << read_guest_string(address_space, context.gpr[5], 128)
                  << '"';
    }
    append_watched_fileholder_summary(std::cerr, state, address_space);
    std::cerr << '\n';
}

bool trace_model_resource_enabled() {
    static const bool enabled =
        read_env_flag("GALAXY_TRACE_MODEL_RESOURCE", false);
    return enabled;
}

void append_model_object_summary(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t object) {
    out << " obj=" << hexadecimal(object);
    if (!mapped_guest_range(address_space, object, 0x90u)) {
        out << " obj=unmapped";
        return;
    }

    constexpr std::uint32_t kOffsets[] = {
        0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x18u, 0x1Cu,
        0x20u, 0x24u, 0x28u, 0x2Cu, 0x30u, 0x34u, 0x38u, 0x3Cu,
        0x40u, 0x44u, 0x48u, 0x4Cu, 0x50u, 0x54u, 0x58u, 0x5Cu,
        0x60u, 0x64u, 0x68u, 0x6Cu, 0x70u, 0x74u, 0x78u, 0x7Cu,
        0x80u, 0x84u, 0x88u, 0x8Cu};
    out << " words=";
    for (const std::uint32_t offset : kOffsets) {
        if (offset != 0u) {
            out << ',';
        }
        out << '+' << std::hex << offset << '=' << std::dec
            << hexadecimal(address_space.read_u32(object + offset));
    }

    const std::uint32_t name_table = address_space.read_u32(object + 0x70u);
    out << " nameTable=" << hexadecimal(name_table);
    if (mapped_guest_range(address_space, name_table, 0x10u)) {
        out << " nameTableWords="
            << hexadecimal(address_space.read_u32(name_table + 0x00u)) << ','
            << hexadecimal(address_space.read_u32(name_table + 0x04u)) << ','
            << hexadecimal(address_space.read_u32(name_table + 0x08u)) << ','
            << hexadecimal(address_space.read_u32(name_table + 0x0Cu));
    } else {
        out << " nameTable=unmapped";
    }
}

void log_model_resource_probe(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    if (!trace_model_resource_enabled() || state.address_space == nullptr) {
        return;
    }
    const auto& address_space = *state.address_space;
    switch (guest_address) {
        case 0x803EFEB4u:
            std::cerr << "[model-resource] vi=" << state.vi_retrace_count
                      << " fn=MR::getResource"
                      << " namePtr=" << hexadecimal(context.gpr[3])
                      << " name=\""
                      << read_guest_string(address_space, context.gpr[3], 128)
                      << "\" lr=" << hexadecimal(context.lr)
                      << " r1=" << hexadecimal(context.gpr[1])
                      << '\n';
            return;
        case 0x803A73C4u:
            std::cerr << "[model-resource] vi=" << state.vi_retrace_count
                      << " fn=model-create"
                      << " r3=" << hexadecimal(context.gpr[3])
                      << " r4=" << hexadecimal(context.gpr[4])
                      << " name=\""
                      << read_guest_string(address_space, context.gpr[4], 128)
                      << "\" lr=" << hexadecimal(context.lr)
                      << " r1=" << hexadecimal(context.gpr[1]);
            append_model_object_summary(std::cerr, address_space, context.gpr[3]);
            std::cerr << '\n';
            return;
        case 0x80160CC4u:
            std::cerr << "[model-resource] vi=" << state.vi_retrace_count
                      << " fn=model-has-dummy"
                      << " lookup=\""
                      << read_guest_string(address_space, context.gpr[4], 128)
                      << "\" lr=" << hexadecimal(context.lr)
                      << " r1=" << hexadecimal(context.gpr[1]);
            append_model_object_summary(std::cerr, address_space, context.gpr[3]);
            std::cerr << '\n';
            return;
        default:
            return;
    }
}

void log_model_name_table_lookup_probe(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    if (guest_address != 0x80416BA8u || state.address_space == nullptr) {
        return;
    }

    const auto& address_space = *state.address_space;
    const auto mapped = [&](std::uint32_t address, std::uint32_t size) {
        return address_space.pointer_or_null(address, size) != nullptr;
    };
    const auto read_word_or = [&](std::uint32_t address) {
        return mapped(address, 4u) ? address_space.read_u32(address)
                                   : std::uint32_t{0xFFFFFFFFu};
    };

    const bool from_model_dummy =
        context.lr == 0x80160CECu || context.lr == 0x80160D0Cu;
    const bool table_unmapped = !mapped(context.gpr[3], 0x10u);
    const bool trace_requested =
        trace_model_resource_enabled() || trace_jpa_resources_enabled();
    if (!table_unmapped && !trace_requested) {
        return;
    }

    static std::uint32_t s_model_lookup_logs = 0;
    if (!table_unmapped && (!from_model_dummy || s_model_lookup_logs >= 256u)) {
        return;
    }
    ++s_model_lookup_logs;
    if (s_model_lookup_logs > 1024u) {
        return;
    }

    const std::uint32_t parent_frame = read_word_or(context.gpr[1]);
    const std::uint32_t parent_saved_r29 =
        mapped(parent_frame + 0x14u, 4u) ? address_space.read_u32(parent_frame + 0x14u)
                                         : 0u;
    const std::uint32_t parent_saved_r30 =
        mapped(parent_frame + 0x08u, 4u) ? address_space.read_u32(parent_frame + 0x08u)
                                         : 0u;
    const std::uint32_t owner =
        mapped(context.gpr[29], 0x90u)
            ? context.gpr[29]
            : (mapped(context.gpr[30], 0x90u)
                   ? context.gpr[30]
                   : (mapped(parent_saved_r29, 0x90u)
                          ? parent_saved_r29
                          : (mapped(parent_saved_r30, 0x90u)
                                 ? parent_saved_r30
                                 : 0u)));

    std::cerr << "[model-name-table-lookup]"
              << " log=" << s_model_lookup_logs
              << " vi=" << state.vi_retrace_count
              << " table=" << hexadecimal(context.gpr[3])
              << " tableMapped=" << (mapped(context.gpr[3], 0x10u) ? 1 : 0)
              << " lookupPtr=" << hexadecimal(context.gpr[4])
              << " lookup=\""
              << read_guest_string(address_space, context.gpr[4], 96)
              << "\" lr=" << hexadecimal(context.lr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " r29=" << hexadecimal(context.gpr[29])
              << " r30=" << hexadecimal(context.gpr[30])
              << " parentFrame=" << hexadecimal(parent_frame)
              << " parentSavedR29=" << hexadecimal(parent_saved_r29)
              << " parentSavedR30=" << hexadecimal(parent_saved_r30);
    if (owner != 0u) {
        append_model_object_summary(std::cerr, address_space, owner);
    }
    std::cerr << '\n';
}

bool try_read_guest_u32(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address,
    std::uint32_t& out) {
    if (address < 0x80000000u || address >= 0x94000000u ||
        address_space.pointer_or_null(address, sizeof(std::uint32_t)) ==
            nullptr) {
        return false;
    }
    out = address_space.read_u32(address);
    return true;
}

std::uint32_t read_guest_u32_or_zero(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address) {
    std::uint32_t value = 0;
    static_cast<void>(try_read_guest_u32(address_space, address, value));
    return value;
}

std::uint8_t read_guest_u8_or_zero(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address) {
    return mapped_guest_range(address_space, address, 1u)
               ? read_guest_u8(address_space, address)
               : 0u;
}

RuntimeState::FunctionAsyncCausalityObservation
capture_function_async_causality_observation(RuntimeState& state) {
    RuntimeState::FunctionAsyncCausalityObservation observation{};
    observation.vi = state.vi_retrace_count;
    observation.wii_ticks = state.timeline != nullptr
        ? state.timeline->now_ticks()
        : 0u;
    observation.xfb_production_serial = galaxy::gx::xfb_copy_count();
    observation.gameplay_pointer_consumer_serial =
        state.gameplay_pointer_consumer_serial;

    if (state.address_space == nullptr) {
        return observation;
    }
    const galaxy::host::GuestAddressSpace& address_space =
        *state.address_space;
    observation.current_context =
        read_guest_u32_or_zero(address_space, 0x800000D4u);
    observation.current_thread =
        read_guest_u32_or_zero(address_space, 0x800000E4u);

    constexpr std::uint32_t kKpad0QueueState =
        galaxy::input::kRmge01KpadBase + 0x10Eu;
    if (mapped_guest_range(address_space, kKpad0QueueState, 2u)) {
        observation.kpad0_write_index =
            read_guest_u8(address_space, kKpad0QueueState);
        observation.kpad0_queue_count =
            read_guest_u8(address_space, kKpad0QueueState + 1u);
        observation.kpad0_queue_valid = true;
    }

    observation.ai_audio_submits = address_space.ai_audio_submit_count();
    const galaxy::host::DspAudioStats dsp = address_space.dsp_audio_stats();
    observation.dsp_render_batches = dsp.render_batches;
    const galaxy::host::AudioSinkStats audio =
        address_space.audio_sink_stats();
    observation.audio_submitted_buffers = audio.submitted_buffers;
    observation.audio_underruns = audio.queue_empty_events;
    return observation;
}

std::uint64_t function_async_counter_delta(
    std::uint64_t end,
    std::uint64_t start) {
    return end >= start ? end - start : 0u;
}

void log_function_async_causality_observation(
    const RuntimeState::FunctionAsyncCausalitySpan& span,
    const char* phase,
    const RuntimeState::FunctionAsyncCausalityObservation& observation) {
    std::ostringstream output;
    output << "[function-async-causality]"
           << " phase=" << phase
           << " seq=" << span.sequence
           << " path=" << (span.path != nullptr ? span.path : "unknown")
           << " info=" << hexadecimal(span.info)
           << " name-ptr=" << hexadecimal(span.name_ptr)
           << " name=\"" << span.name << '"'
           << " opfn=" << hexadecimal(span.opfn)
           << " thread=" << hexadecimal(observation.current_thread)
           << " context=" << hexadecimal(observation.current_context)
           << " vi=" << observation.vi
           << " wii-ticks=" << observation.wii_ticks
           << " xfb-production-serial="
           << observation.xfb_production_serial
           << " gameplay-pointer-consumer-serial="
           << observation.gameplay_pointer_consumer_serial
           << " kpad0-queue-valid="
           << (observation.kpad0_queue_valid ? 1 : 0)
           << " kpad0-write="
           << static_cast<unsigned>(observation.kpad0_write_index)
           << " kpad0-queue="
           << static_cast<unsigned>(observation.kpad0_queue_count)
           << " ai-audio-submits=" << observation.ai_audio_submits
           << " dsp-render-batches=" << observation.dsp_render_batches
           << " audio-submitted-buffers="
           << observation.audio_submitted_buffers
           << " audio-underruns=" << observation.audio_underruns;
    if (phase[0] == 'c') {
        output << " duration-wii-ticks="
               << function_async_counter_delta(
                      observation.wii_ticks, span.start.wii_ticks)
               << " xfb-production-delta="
               << function_async_counter_delta(
                      observation.xfb_production_serial,
                      span.start.xfb_production_serial)
               << " gameplay-pointer-consumer-delta="
               << function_async_counter_delta(
                      observation.gameplay_pointer_consumer_serial,
                      span.start.gameplay_pointer_consumer_serial)
               << " ai-audio-submit-delta="
               << function_async_counter_delta(
                      observation.ai_audio_submits,
                      span.start.ai_audio_submits)
               << " dsp-render-batch-delta="
               << function_async_counter_delta(
                      observation.dsp_render_batches,
                      span.start.dsp_render_batches)
               << " audio-submit-delta="
               << function_async_counter_delta(
                      observation.audio_submitted_buffers,
                      span.start.audio_submitted_buffers)
               << " audio-underrun-delta="
               << function_async_counter_delta(
                      observation.audio_underruns,
                      span.start.audio_underruns);
    }
    output << '\n';
    std::cerr << output.str();
    // A worker or synchronous opfn can stall indefinitely. Persist its start
    // record immediately instead of relying on normal process teardown.
    std::cerr.flush();
}

RuntimeState::FunctionAsyncCausalitySpan begin_function_async_causality_span(
    RuntimeState& state,
    const char* path,
    std::uint32_t info,
    std::uint32_t name_ptr,
    std::uint32_t opfn) {
    RuntimeState::FunctionAsyncCausalitySpan span{};
    if (!galaxy::trace_function_async_causality_enabled()) {
        return span;
    }
    if (state.function_async_causality_logged_spans >=
        RuntimeState::kFunctionAsyncCausalitySpanLogLimit) {
        if (!state.function_async_causality_limit_reported) {
            state.function_async_causality_limit_reported = true;
            std::cerr
                << "[function-async-causality] phase=limit span-limit="
                << RuntimeState::kFunctionAsyncCausalitySpanLogLimit << '\n';
            std::cerr.flush();
        }
        return span;
    }

    ++state.function_async_causality_logged_spans;
    if (state.function_async_causality_sequence !=
        std::numeric_limits<std::uint64_t>::max()) {
        ++state.function_async_causality_sequence;
    }
    span.active = true;
    span.sequence = state.function_async_causality_sequence;
    span.path = path;
    span.info = info;
    span.name_ptr = name_ptr;
    span.opfn = opfn;
    if (state.address_space != nullptr) {
        span.name = read_guest_string(*state.address_space, name_ptr, 96);
    }
    span.start = capture_function_async_causality_observation(state);
    log_function_async_causality_observation(span, "start", span.start);
    return span;
}

void complete_function_async_causality_span(
    RuntimeState& state,
    const RuntimeState::FunctionAsyncCausalitySpan& span) {
    if (!span.active) {
        return;
    }
    const RuntimeState::FunctionAsyncCausalityObservation completion =
        capture_function_async_causality_observation(state);
    log_function_async_causality_observation(
        span, "complete", completion);
}

void resolve_function_async_exec_info(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t info,
    std::uint32_t& name_ptr,
    std::uint32_t& opfn) {
    name_ptr = 0u;
    opfn = 0u;
    if (!mapped_guest_range(address_space, info, 0x0Cu)) {
        return;
    }
    const std::uint32_t mfunc = address_space.read_u32(info);
    name_ptr = address_space.read_u32(info + 0x08u);
    if (!mapped_guest_range(address_space, mfunc, 4u)) {
        return;
    }
    const std::uint32_t vtable = address_space.read_u32(mfunc);
    if (mapped_guest_range(address_space, vtable + 0x08u, 4u)) {
        opfn = address_space.read_u32(vtable + 0x08u);
    }
}

bool function_async_proof_enabled() {
    static const bool enabled =
        read_env_flag("GALAXY_REQUIRE_GUEST_ASYNC_PROOF", false);
    return enabled;
}

void register_function_async_main_queue(
    RuntimeState& state,
    std::uint32_t executor,
    std::uint32_t info,
    std::uint32_t name_ptr,
    std::uint32_t count_before,
    std::uint32_t count_after) {
    if (info == 0u ||
        state.function_async_main_queue_sequence ==
            std::numeric_limits<std::uint64_t>::max()) {
        throw RuntimeFailure(
            "translated FunctionAsync main-thread queue produced an invalid "
            "proof identity");
    }
    const std::uint64_t sequence =
        ++state.function_async_main_queue_sequence;
    const auto [it, inserted] =
        state.function_async_main_queued_infos.emplace(info, sequence);
    (void)it;
    if (!inserted) {
        throw RuntimeFailure(
            "translated FunctionAsync main-thread queue reused a live "
            "exec-info " + hexadecimal(info));
    }

    std::ostringstream output;
    output << "[function-async-main-proof] event=queued accepted=1"
           << " sequence=" << sequence
           << " info=" << hexadecimal(info)
           << " executor=" << hexadecimal(executor)
           << " name=" << hexadecimal(name_ptr)
           << " count-before=" << count_before
           << " count-after=" << count_after << '\n';
    std::cerr << output.str();
    std::cerr.flush();
}

bool consume_function_async_main_reap(
    RuntimeState& state,
    std::uint32_t info) {
    const auto found = state.function_async_main_queued_infos.find(info);
    if (found == state.function_async_main_queued_infos.end()) {
        return false;
    }
    const std::uint64_t sequence = found->second;
    state.function_async_main_queued_infos.erase(found);
    if (state.function_async_main_reaped ==
        std::numeric_limits<std::uint64_t>::max()) {
        throw RuntimeFailure(
            "translated FunctionAsync main-thread reap counter overflowed");
    }
    ++state.function_async_main_reaped;

    std::ostringstream output;
    output << "[function-async-main-proof] event=reaped accepted=1"
           << " sequence=" << sequence
           << " info=" << hexadecimal(info) << '\n';
    std::cerr << output.str();
    std::cerr.flush();
    return true;
}

void observe_function_async_flight(
    RuntimeState& state,
    galaxy::scheduler::FunctionAsyncEvent event,
    std::uint32_t info,
    std::uint32_t worker,
    bool boundary_succeeded = true) {
    if (!function_async_proof_enabled()) {
        return;
    }
    const galaxy::scheduler::FunctionAsyncObservation observation =
        state.function_async_flights.observe(
            event, info, worker, boundary_succeeded);
    // std::cerr is unit-buffered. Building the record first keeps this exact
    // boundary observation to one redirected-pipe write instead of flushing
    // once per field and perturbing the cadence that the proof is measuring.
    std::ostringstream output;
    output << "[function-async-proof] event="
           << galaxy::scheduler::function_async_event_name(observation.event)
           << " accepted=" << (observation.accepted ? 1 : 0)
           << " failure="
           << galaxy::scheduler::function_async_failure_name(
                  observation.failure)
           << " flight=" << observation.flight_sequence
           << " info=" << hexadecimal(observation.exec_info)
           << " worker=" << hexadecimal(observation.worker) << '\n';
    std::cerr << output.str();
    std::cerr.flush();
}

void log_function_async_proof_summary(RuntimeState& state) {
    if (!function_async_proof_enabled() ||
        state.function_async_proof_summary_logged) {
        return;
    }
    state.function_async_proof_summary_logged = true;
    const galaxy::scheduler::FunctionAsyncSummary summary =
        state.function_async_flights.summary();
    const bool migration_ready =
        summary.migration_ready() &&
        state.function_async_main_queued_infos.empty();
    std::ostringstream output;
    output << "[function-async-proof] phase=summary"
           << " observations=" << summary.observations
           << " completed=" << summary.completed_flights
           << " active=" << summary.active_flights
           << " failures=" << summary.protocol_failures
           // This machine-readable field is retained for proof compatibility.
           // It is an invariant now: no synchronous FunctionAsync path exists.
           << " sync-hle=0"
           << " migration-ready=" << (migration_ready ? 1 : 0)
           << '\n';
    std::cerr << output.str();
    std::cerr.flush();

    std::ostringstream main_output;
    main_output
        << "[function-async-main-proof] phase=summary"
        << " queued=" << state.function_async_main_queue_sequence
        << " reaped=" << state.function_async_main_reaped
        << " active=" << state.function_async_main_queued_infos.size()
        << " migration-ready=" << (migration_ready ? 1 : 0) << '\n';
    std::cerr << main_output.str();
    std::cerr.flush();
}

bool observe_function_async_causality_marker(
    RuntimeState& state,
    std::uint32_t marker,
    galaxy::PpcContext* context) {
    switch (marker) {
    case galaxy::kFunctionAsyncTracePointerConsumer:
        if (galaxy::trace_function_async_causality_enabled() &&
            state.gameplay_pointer_consumer_serial !=
                std::numeric_limits<std::uint64_t>::max()) {
            ++state.gameplay_pointer_consumer_serial;
        }
        return true;
    case galaxy::kFunctionAsyncTraceWorkerDequeued:
        {
            // The marker is before 0x80398E6C, after 0x80398E68 loaded the
            // received exec-info into r29. r28 is the preserved worker object.
            const std::uint32_t info =
                context != nullptr ? context->gpr[29] : 0u;
            const std::uint32_t worker =
                context != nullptr ? context->gpr[28] : 0u;
            if (function_async_proof_enabled() &&
                state.function_async_main_queued_infos.contains(info)) {
                throw RuntimeFailure(
                    "translated FunctionAsync worker dequeue reused a live "
                    "main-thread exec-info " +
                    hexadecimal(info));
            }
            observe_function_async_flight(
                state,
                galaxy::scheduler::FunctionAsyncEvent::WorkerDequeued,
                info,
                worker);
        }
        return true;
    case galaxy::kFunctionAsyncTraceWorkerBegin:
        {
            // This callback is immediately before the worker's real execute
            // call. r29 and r28 are its preserved exec-info and worker object.
            const std::uint32_t info =
                context != nullptr ? context->gpr[29] : 0u;
            const std::uint32_t worker =
                context != nullptr ? context->gpr[28] : 0u;
            observe_function_async_flight(
                state,
                galaxy::scheduler::FunctionAsyncEvent::ExecuteBegin,
                info,
                worker);
        }
        // The strict flight proof already records this boundary durably. Do
        // not also run the older, verbose causality snapshot in proof mode;
        // its synchronous diagnostic I/O would contaminate the cadence proof.
        if (!galaxy::trace_function_async_causality_enabled() ||
            function_async_proof_enabled()) {
            return true;
        }
        if (state.function_async_causality_stack_depth >=
            RuntimeState::kFunctionAsyncCausalityStackCapacity) {
            if (state.function_async_causality_overflow_depth !=
                std::numeric_limits<std::size_t>::max()) {
                ++state.function_async_causality_overflow_depth;
            }
            if (!state.function_async_causality_stack_limit_reported) {
                state.function_async_causality_stack_limit_reported = true;
                std::cerr
                    << "[function-async-causality] phase=limit stack-capacity="
                    << RuntimeState::kFunctionAsyncCausalityStackCapacity
                    << '\n';
                std::cerr.flush();
            }
            return true;
        }
        {
            const std::uint32_t info = context != nullptr
                ? context->gpr[3]
                : 0u;
            std::uint32_t name_ptr = 0u;
            std::uint32_t opfn = 0u;
            if (state.address_space != nullptr) {
                resolve_function_async_exec_info(
                    *state.address_space, info, name_ptr, opfn);
            }
            state.function_async_causality_stack
                [state.function_async_causality_stack_depth++] =
                    begin_function_async_causality_span(
                        state,
                        "guest-worker-execute",
                        info,
                        name_ptr,
                        opfn);
        }
        return true;
    case galaxy::kFunctionAsyncTraceWorkerComplete:
        {
            // The completion marker is at architectural return PC 0x80398E80,
            // so this observation remains reachable after OSLoadContext/RFI
            // unwinds the native call stack and later resumes the worker.
            const std::uint32_t info =
                context != nullptr ? context->gpr[29] : 0u;
            const std::uint32_t worker =
                context != nullptr ? context->gpr[28] : 0u;
            observe_function_async_flight(
                state,
                galaxy::scheduler::FunctionAsyncEvent::ExecuteReturned,
                info,
                worker);
        }
        if (!galaxy::trace_function_async_causality_enabled() ||
            function_async_proof_enabled()) {
            return true;
        }
        if (state.function_async_causality_overflow_depth != 0u) {
            --state.function_async_causality_overflow_depth;
            return true;
        }
        if (state.function_async_causality_stack_depth == 0u) {
            if (!state.function_async_causality_orphan_reported) {
                state.function_async_causality_orphan_reported = true;
                std::cerr
                    << "[function-async-causality] phase=orphan-complete\n";
                std::cerr.flush();
            }
            return true;
        }
        --state.function_async_causality_stack_depth;
        {
            RuntimeState::FunctionAsyncCausalitySpan span = std::move(
                state.function_async_causality_stack
                    [state.function_async_causality_stack_depth]);
            state.function_async_causality_stack
                [state.function_async_causality_stack_depth] = {};
            complete_function_async_causality_span(state, span);
        }
        return true;
    case galaxy::kFunctionAsyncTraceDoneMessagePosted:
        {
            // At the 0x80398E90 return continuation, r3 is the real
            // OSSendMessage BOOL. A rejected nonblocking post fails closed.
            const std::uint32_t info =
                context != nullptr ? context->gpr[29] : 0u;
            const std::uint32_t worker =
                context != nullptr ? context->gpr[28] : 0u;
            const bool posted = context != nullptr && context->gpr[3] != 0u;
            observe_function_async_flight(
                state,
                galaxy::scheduler::FunctionAsyncEvent::DoneMessagePosted,
                info,
                worker,
                posted);
        }
        return true;
    case galaxy::kFunctionAsyncTraceEndFlagPublished:
        {
            // The marker is after the byte store at 0x80398E90. Read the
            // game-visible byte back rather than inferring that it committed.
            const std::uint32_t info =
                context != nullptr ? context->gpr[29] : 0u;
            const std::uint32_t worker =
                context != nullptr ? context->gpr[28] : 0u;
            const bool published =
                state.address_space != nullptr &&
                info <= std::numeric_limits<std::uint32_t>::max() - 0x0Cu &&
                mapped_guest_range(state.address_space, info + 0x0Cu, 4u) &&
                (state.address_space->read_u32(info + 0x0Cu) &
                    0xFF000000u) == 0x01000000u;
            observe_function_async_flight(
                state,
                galaxy::scheduler::FunctionAsyncEvent::EndFlagPublished,
                info,
                worker,
                published);
        }
        return true;
    case galaxy::kFunctionAsyncTraceExecInfoPublished:
        {
            // createAndAddExecInfo has incremented the vector count and stored
            // r30 into its new slot, but has not yet called the mutex unlock
            // at 0x80399424. Classify this identity while publication is still
            // atomic with respect to a concurrent waitForEnd. Post-return
            // snapshots are racy: a waiter can remove and free the entry as
            // soon as this mutex is released.
            if (!function_async_proof_enabled()) {
                return true;
            }
            if (state.address_space == nullptr || context == nullptr) {
                throw RuntimeFailure(
                    "translated FunctionAsync exec-info publication proof "
                    "lacks runtime state");
            }
            constexpr std::uint32_t kVectorCountOffset = 0x40Cu;
            constexpr std::uint32_t kVectorOffset = 0x0Cu;
            constexpr std::uint32_t kVectorCapacity = 256u;
            constexpr std::uint32_t kWorkerStartReturn = 0x80399074u;
            constexpr std::uint32_t kMainStartReturn = 0x80399114u;
            const std::uint32_t info = context->gpr[30];
            const std::uint32_t executor = context->gpr[27];
            const std::uint32_t stack = context->gpr[1];
            if (info == 0u ||
                executor >
                    std::numeric_limits<std::uint32_t>::max() -
                        (kVectorCountOffset + 4u) ||
                stack >
                    std::numeric_limits<std::uint32_t>::max() - 0x28u ||
                !mapped_guest_range(state.address_space, info, 0x0Cu) ||
                !mapped_guest_range(
                    state.address_space,
                    executor,
                    kVectorCountOffset + 4u) ||
                !mapped_guest_range(
                    state.address_space, stack + 0x24u, 4u)) {
                throw RuntimeFailure(
                    "translated FunctionAsync published an invalid exec-info "
                    "proof identity");
            }
            const std::uint32_t origin_return =
                state.address_space->read_u32(stack + 0x24u);
            const std::uint32_t count_after =
                state.address_space->read_u32(executor + kVectorCountOffset);
            if (count_after == 0u || count_after > kVectorCapacity) {
                throw RuntimeFailure(
                    "translated FunctionAsync publication observed an "
                    "invalid vector count");
            }
            const std::uint32_t slot =
                executor + kVectorOffset + (count_after - 1u) * 4u;
            if (!mapped_guest_range(state.address_space, slot, 4u) ||
                state.address_space->read_u32(slot) != info) {
                throw RuntimeFailure(
                    "translated FunctionAsync publication did not expose "
                    "the exact appended exec-info while locked");
            }
            if (origin_return == kMainStartReturn) {
                if (state.function_async_flights.has_active_exec_info(info)) {
                    throw RuntimeFailure(
                        "translated FunctionAsync main-thread publication "
                        "reused an active worker exec-info " +
                        hexadecimal(info));
                }
                register_function_async_main_queue(
                    state,
                    executor,
                    info,
                    state.address_space->read_u32(info + 0x08u),
                    count_after - 1u,
                    count_after);
            } else if (origin_return != kWorkerStartReturn) {
                throw RuntimeFailure(
                    "translated FunctionAsync publication has unknown caller " +
                    hexadecimal(origin_return));
            }
        }
        return true;
    case galaxy::kFunctionAsyncTraceReaped:
        {
            // waitForEnd reaches 0x80399268 only after vector removal, mutex
            // unlock, and destructor/free. r31 is identity only: never read
            // through this freed exec-info address. The tracker restores the
            // worker identity from the active flight.
            const std::uint32_t info =
                context != nullptr ? context->gpr[31] : 0u;
            if (consume_function_async_main_reap(state, info)) {
                return true;
            }
            observe_function_async_flight(
                state,
                galaxy::scheduler::FunctionAsyncEvent::Reaped,
                info,
                0u);
        }
        return true;
    default:
        return false;
    }
}

const char* native_input_stack_trace_label(std::uint32_t guest_address) {
    switch (guest_address) {
        case 0x804506D8u:
            return "KPADRead";
        case 0x80451198u:
            return "KPADiSamplingCallback";
        case 0x804D8ACCu:
            return "WPADProbe";
        case 0x804D93C8u:
            return "WPADRead";
        default:
            return nullptr;
    }
}

bool is_native_input_stack_trace_address(std::uint32_t guest_address) {
    return native_input_stack_trace_label(guest_address) != nullptr;
}

bool is_native_ir_report_decoder_address(std::uint32_t guest_address) {
    return guest_address == 0x804DFF98u ||  // report 0x33
           guest_address == 0x804E0C98u ||  // report 0x36
           guest_address == 0x804E0ED0u;    // report 0x37
}

bool is_translated_wpad_report_decoder_address(std::uint32_t guest_address) {
    // Exact non-invalid entries from RMGE01's report-id dispatch table at
    // 0x805EC4E8, indexed by report_id - 0x20. Generated-code audit confirms
    // every entry except the 0x3D no-op writes the alternating WPAD status
    // slot and flips control+0x8C8 once. Invalidating on the 0x3D no-op is
    // conservative and prevents it from preserving an identity by accident.
    switch (guest_address) {
    case 0x804DE4F0u:  // 0x20
    case 0x804DE910u:  // 0x21
    case 0x804DED18u:  // 0x22
    case 0x804DF3C4u:  // 0x30
    case 0x804DF57Cu:  // 0x31
    case 0x804DF7BCu:  // 0x32
    case 0x804DFF98u:  // 0x33
    case 0x804E020Cu:  // 0x34
    case 0x804E0418u:  // 0x35
    case 0x804E0C98u:  // 0x36
    case 0x804E0ED0u:  // 0x37
    case 0x804E175Cu:  // 0x3D
    case 0x804E1760u:  // 0x3E
    case 0x804E1D44u:  // 0x3F
        return true;
    default:
        return false;
    }
}

std::uint32_t native_ir_report_decoder_byte_count(
    std::uint32_t guest_address) {
    switch (guest_address) {
    case 0x804DFF98u:
        return 18u;  // report id + 17-byte 0x33 body; A1 is stripped by HID
    case 0x804E0C98u:
    case 0x804E0ED0u:
        return 22u;  // report id + 21-byte 0x36/0x37 body
    default:
        return 0u;
    }
}

const char* bt_wpad_command_trace_label(std::uint32_t guest_address) {
    switch (guest_address) {
        case 0x804D7858u:
            return "WPADInitFinalReadCallback";
        case 0x804D792Cu:
            return "WPADCommandAckCallback";
        case 0x804D7A10u:
            return "WPADInitProbeReadCallback";
        case 0x804DC4D0u:
            return "WPADSendCommand";
        case 0x804F2364u:
            return "BTA_HhSendData";
        default:
            return nullptr;
    }
}

bool is_bt_wpad_command_trace_address(std::uint32_t guest_address) {
    return bt_wpad_command_trace_label(guest_address) != nullptr;
}

void dump_bt_wpad_command_state(
    std::ostream& output,
    const RuntimeState& state,
    const char* tag) {
    if (state.address_space == nullptr) {
        return;
    }
    const auto& address_space = *state.address_space;
    const auto has = [&](std::uint32_t address, std::uint32_t size) {
        return address >= 0x80000000u && address < 0x94000000u &&
            address_space.pointer_or_null(address, size) != nullptr;
    };
    const auto u8 = [&](std::uint32_t address) -> std::uint8_t {
        return has(address, 1u) ? read_guest_u8(address_space, address) : 0u;
    };
    const auto u16 = [&](std::uint32_t address) -> std::uint16_t {
        return static_cast<std::uint16_t>(
            (static_cast<std::uint16_t>(u8(address)) << 8u) |
            u8(address + 1u));
    };
    const auto u32 = [&](std::uint32_t address) -> std::uint32_t {
        return has(address, sizeof(std::uint32_t))
            ? read_guest_u32_or_zero(address_space, address)
            : 0u;
    };
    const auto byte_hex = [&](std::uint8_t value) {
        std::ostringstream text;
        text << "0x" << std::hex << std::uppercase << std::setfill('0')
             << std::setw(2) << static_cast<unsigned>(value);
        return text.str();
    };
    const auto bytes_hex =
        [&](std::uint32_t address, std::uint32_t length) {
            std::ostringstream text;
            text << std::hex << std::uppercase << std::setfill('0');
            for (std::uint32_t i = 0; i < length; ++i) {
                if (i != 0u) {
                    text << ' ';
                }
                if (!has(address + i, 1u)) {
                    text << "??";
                } else {
                    text << std::setw(2)
                         << static_cast<unsigned>(u8(address + i));
                }
            }
            return text.str();
        };

    constexpr std::uint32_t kWpadControlBlockTable = 0x80660170u;
    const std::uint32_t wpad0 = u32(kWpadControlBlockTable);
    output << tag << " wpad0=" << hexadecimal(wpad0);
    if (!has(wpad0, 0x990u)) {
        output << " unavailable\n";
        return;
    }
    const std::uint32_t ring_base = u32(wpad0 + 0x164u);
    const std::uint32_t ring_capacity = u32(wpad0 + 0x168u);
    output << " type=" << hexadecimal(u32(wpad0 + 0x8BCu))
           << " init=" << hexadecimal(u32(wpad0 + 0x8E0u))
           << " ready=" << hexadecimal(u32(wpad0 + 0x8DCu))
           << " cb=" << hexadecimal(u32(wpad0 + 0x89Cu))
           << " cur-report=" << byte_hex(u8(wpad0 + 0x987u))
           << " stat=" << byte_hex(u8(wpad0 + 0x8C1u))
           << " dev=" << byte_hex(u8(wpad0 + 0x8C3u))
           << " active-slot=" << byte_hex(u8(wpad0 + 0x8C8u))
           << " q=(" << byte_hex(u8(wpad0 + 0x160u))
           << ',' << byte_hex(u8(wpad0 + 0x161u))
           << '/' << ring_capacity << ')'
           << " read-buf=" << hexadecimal(u32(wpad0 + 0x974u))
           << " read-addr=" << hexadecimal(u32(wpad0 + 0x978u))
           << " read-err=" << hexadecimal(u32(wpad0 + 0x97Cu))
           << " read-size=0x" << std::hex << std::uppercase
           << static_cast<unsigned>(u16(wpad0 + 0x980u))
           << std::dec
           << " timeout-armed=" << static_cast<unsigned>(u8(wpad0 + 0x910u))
           << " timeout-flag=" << static_cast<unsigned>(u8(wpad0 + 0x986u))
           << '\n';

    if (!has(ring_base, 0x30u) || ring_capacity == 0u || ring_capacity > 32u) {
        return;
    }
    for (std::uint32_t i = 0; i < ring_capacity; ++i) {
        const std::uint32_t entry = ring_base + i * 0x30u;
        bool non_empty = u32(entry + 0x2Cu) != 0u;
        for (std::uint32_t j = 0; j < 0x30u && !non_empty; ++j) {
            non_empty = u8(entry + j) != 0u;
        }
        if (i >= 4u && !non_empty) {
            continue;
        }
        output << tag << " qslot[" << i << "] raw="
               << bytes_hex(entry, 16u)
               << " cb=" << hexadecimal(u32(entry + 0x2Cu))
               << '\n';
    }
}

void dump_bt_wpad_send_buffer(
    std::ostream& output,
    const RuntimeState& state,
    const char* tag,
    std::uint32_t guest_address,
    std::uint32_t arg3,
    std::uint32_t arg4) {
    if (state.address_space == nullptr) {
        return;
    }
    const auto& address_space = *state.address_space;
    const auto has = [&](std::uint32_t address, std::uint32_t size) {
        return address >= 0x80000000u && address < 0x94000000u &&
            address_space.pointer_or_null(address, size) != nullptr;
    };
    const auto u8 = [&](std::uint32_t address) -> std::uint8_t {
        return has(address, 1u) ? read_guest_u8(address_space, address) : 0u;
    };
    const auto bytes_hex =
        [&](std::uint32_t address, std::uint32_t length) {
            std::ostringstream text;
            text << std::hex << std::uppercase << std::setfill('0');
            for (std::uint32_t i = 0; i < length; ++i) {
                if (i != 0u) {
                    text << ' ';
                }
                if (!has(address + i, 1u)) {
                    text << "??";
                } else {
                    text << std::setw(2)
                         << static_cast<unsigned>(u8(address + i));
                }
            }
            return text.str();
        };

    if (guest_address == 0x804DC4D0u) {
        output << tag << " send-command chan=" << hexadecimal(arg3)
               << " cmd=" << hexadecimal(arg4);
        if (has(arg4, 0x30u)) {
            output << " raw=" << bytes_hex(arg4, 0x30u);
        } else {
            output << " unavailable";
        }
        output << '\n';
        return;
    }
    if (guest_address == 0x804F2364u) {
        output << tag << " bta-send dev=" << hexadecimal(arg3)
               << " buf=" << hexadecimal(arg4);
        if (has(arg4, 0x24u)) {
            output << " raw=" << bytes_hex(arg4, 0x24u);
        } else {
            output << " unavailable";
        }
        output << '\n';
    }
}

void dump_native_input_causal_sample(
    std::ostream& output,
    const galaxy::input::NativeInputCausalKpadSample* sample) {
    if (sample == nullptr) {
        output << " acl-causal=ambiguous acl-reason=missing-kpad-causal-frame";
        return;
    }
    if (!sample->exact) {
        output << " acl-causal=ambiguous acl-reason="
               << galaxy::input::native_input_causality_reason_name(
                      sample->reason);
        return;
    }

    const auto& identity = sample->delivery;
    std::ostringstream text;
    text << " acl-causal=exact"
         << " acl-epoch=" << identity.logical_epoch
         << " acl-sample=" << identity.sample_sequence
         << " acl-deadline-wii-ticks=" << identity.deadline_wii_ticks
         << " acl-production-wii-ticks=" << identity.production_wii_ticks
         << " acl-delivery-wii-ticks=" << identity.delivery_wii_ticks
         << " acl-host-domain="
         << galaxy::host::host_pointer_sequence_domain_name(
                identity.host_pointer_sequence_domain)
         << " acl-host-seq=" << identity.host_pointer_sequence
         << " acl-host-acquired-ms=" << identity.host_pointer_acquired_ms
         << " acl-host-sampled=" << (identity.host_pointer_sampled ? 1 : 0)
         << " acl-report=0x" << std::hex << std::nouppercase
         << std::setfill('0') << std::setw(2)
         << static_cast<unsigned>(identity.report_id)
         << std::dec << std::setfill(' ')
         << " acl-payload-size=" << identity.payload_size
         << " acl-payload-bytes=" << std::hex << std::setfill('0');
    for (std::uint32_t index = 0; index < identity.payload_size; ++index) {
        text << (index == 0u ? "" : ":") << std::setw(2)
             << static_cast<unsigned>(identity.payload[index]);
    }
    text << " acl-payload-fnv1a64=0x" << std::setw(16)
         << identity.payload_fingerprint
         << " acl-ios-request=0x" << std::setw(8) << identity.ios_request
         << " acl-decode-seq=" << std::dec << sample->decode_sequence
         << " acl-channel=" << sample->channel
         << " acl-decoder=" << hexadecimal(sample->decoder_address)
         << " acl-decoder-wii-ticks="
         << sample->decoder_observation_wii_ticks
         << " acl-decoder-lr=" << hexadecimal(sample->decoder_entry_lr)
         << " acl-decoder-thread="
         << hexadecimal(sample->decoder_current_thread)
         << " acl-decoder-context="
         << hexadecimal(sample->decoder_current_context)
         << " acl-pending-depth="
         << sample->decoder_pending_delivery_depth
         << " acl-oldest-pending-age-wii-ticks="
         << sample->decoder_oldest_delivery_age_wii_ticks
         << " acl-wpad-slot=" << hexadecimal(sample->wpad_slot_address)
         << " acl-copy-pc=" << hexadecimal(sample->wpad_copy_call_pc)
         << " acl-copy-src=" << hexadecimal(sample->wpad_copy_source)
         << " acl-copy-dst=" << hexadecimal(sample->kpad_copy_destination)
         << " acl-copy-size=" << sample->copied_size
         << " acl-kpad-copy-wii-ticks="
         << sample->kpad_copy_completion_wii_ticks
         << " acl-delivery-to-decode-ticks="
         << sample->decoder_observation_wii_ticks -
                identity.delivery_wii_ticks
         << " acl-delivery-to-kpad-copy-ticks="
         << sample->kpad_copy_completion_wii_ticks -
                identity.delivery_wii_ticks
         << " acl-decode-to-kpad-copy-ticks="
         << sample->kpad_copy_completion_wii_ticks -
                sample->decoder_observation_wii_ticks;
    output << text.str();
}

void dump_native_input_stack_state(
    std::ostream& output,
    const RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context,
    std::uint32_t arg3,
    std::uint32_t arg4,
    std::uint32_t arg5,
    std::uint64_t call_index,
    const galaxy::input::NativeInputCausalKpadSample* causal_sample) {
    if (state.address_space == nullptr) {
        return;
    }
    const auto& address_space = *state.address_space;
    const auto has = [&](std::uint32_t address, std::uint32_t size) {
        return address >= 0x80000000u && address < 0x94000000u &&
            address_space.pointer_or_null(address, size) != nullptr;
    };
    const auto u8 = [&](std::uint32_t address) -> std::uint8_t {
        return has(address, 1u) ? read_guest_u8(address_space, address) : 0u;
    };
    const auto u16 = [&](std::uint32_t address) -> std::uint16_t {
        return static_cast<std::uint16_t>(
            (static_cast<std::uint16_t>(u8(address)) << 8u) |
            u8(address + 1u));
    };
    const auto u32 = [&](std::uint32_t address) -> std::uint32_t {
        return has(address, sizeof(std::uint32_t))
            ? read_guest_u32_or_zero(address_space, address)
            : 0u;
    };
    const auto byte_hex = [&](std::uint8_t value) {
        std::ostringstream text;
        text << "0x" << std::hex << std::uppercase << std::setfill('0')
             << std::setw(2) << static_cast<unsigned>(value);
        return text.str();
    };
    const auto half_hex = [&](std::uint16_t value) {
        std::ostringstream text;
        text << "0x" << std::hex << std::uppercase << std::setfill('0')
             << std::setw(4) << static_cast<unsigned>(value);
        return text.str();
    };
    const auto f32_bits_text = [&](std::uint32_t address) {
        std::ostringstream text;
        const std::uint32_t bits = u32(address);
        const float value = std::bit_cast<float>(bits);
        text << hexadecimal(bits);
        if (std::isfinite(value) && std::fabs(value) < 100000.0f) {
            text << '/' << std::fixed << std::setprecision(3) << value;
        }
        return text.str();
    };

    constexpr std::uint32_t kWpadControlBlockTable = 0x80660170u;
    constexpr std::uint32_t kKpadBase = 0x8061D340u;
    constexpr std::uint32_t kWpadSlot0 = 0xA0u;
    constexpr std::uint32_t kWpadSlot1 = 0x100u;
    constexpr std::uint32_t kKpadRingBase = 0x110u;
    constexpr std::uint32_t kKpadStatusSize = 0x38u;

    if (trace_native_input_stack_compact_enabled()) {
        // This is the sampling-ring stage only. The exact identity here must
        // never be attached to channel-global KPAD coordinates: those globals
        // can remain stale while the 0x78-entry queue fills. The separate
        // protected KPADRead and WPadPointer checkpoints prove the caller-owned
        // gameplay output status.
        if (guest_address != 0x80451198u) {
            return;
        }
        output << "[input-stack] vi=" << state.vi_retrace_count
               << " call=" << call_index
               << " fn=" << native_input_stack_trace_label(guest_address)
               << " acl-stage=kpad-ring"
               << " kpad(write=" << byte_hex(u8(kKpadBase + 0x10Eu))
               << " queue=" << byte_hex(u8(kKpadBase + 0x10Fu)) << ')';
        dump_native_input_causal_sample(output, causal_sample);
        output << '\n';
        return;
    }

    const std::uint32_t wpad0 = u32(kWpadControlBlockTable);
    output << "[input-stack] vi=" << state.vi_retrace_count
           << " call=" << call_index
           << " fn=" << native_input_stack_trace_label(guest_address)
           << " addr=" << hexadecimal(guest_address)
           << " args=(" << hexadecimal(arg3) << ',' << hexadecimal(arg4)
           << ',' << hexadecimal(arg5) << ')'
           << " ret=" << hexadecimal(context.gpr[3])
           << " lr=" << hexadecimal(context.lr);

    output << " wpad0=" << hexadecimal(wpad0);
    if (has(wpad0, 0x900u)) {
        output << " wpad.type=" << hexadecimal(u32(wpad0 + 0x8BCu))
               << " ready=" << hexadecimal(u32(wpad0 + 0x8DCu))
               << " stat=" << byte_hex(u8(wpad0 + 0x8C1u))
               << " fmt=" << hexadecimal(u32(wpad0 + 0x8B8u))
               << " active=" << byte_hex(u8(wpad0 + 0x8C8u))
               << " ring=(" << byte_hex(u8(wpad0 + 0x160u)) << ','
               << byte_hex(u8(wpad0 + 0x161u)) << ')';
        const auto dump_wpad_slot =
            [&](const char* label, std::uint32_t slot) {
                output << ' ' << label
                       << "(btn=" << half_hex(u16(slot))
                       << " type=" << byte_hex(u8(slot + 0x28u))
                       << " err=" << byte_hex(u8(slot + 0x29u))
                       << " ext=" << byte_hex(u8(slot + 0x2Au))
                       << " data0=" << byte_hex(u8(slot + 0x2Bu))
                       << ')';
            };
        dump_wpad_slot("slot0", wpad0 + kWpadSlot0);
        dump_wpad_slot("slot1", wpad0 + kWpadSlot1);
    }
    // The translated WPAD extension decoder at 0x804E3124 decodes each
    // extension-data octet as `(wire ^ xor_key[i]) + add_key[i]`, using these
    // two eight-byte tables in the channel control block.  Emit them only on
    // the sampling callback: this gives a bounded, primary-evidence record of
    // the active retail key material without adding any I/O to the hot input
    // producer path.  It is diagnostic-only and is gated by the existing
    // native-input-stack trace.
    if (guest_address == 0x80451198u && has(wpad0 + 0x934u, 8u)) {
        output << " ext-add=";
        for (std::uint32_t i = 0; i < 8u; ++i) {
            output << (i == 0u ? "[" : ",")
                   << byte_hex(u8(wpad0 + 0x924u + i));
        }
        output << "] ext-xor=";
        for (std::uint32_t i = 0; i < 8u; ++i) {
            output << (i == 0u ? "[" : ",")
                   << byte_hex(u8(wpad0 + 0x92Cu + i));
        }
        output << ']';
    }

    output << " kpad(write=" << byte_hex(u8(kKpadBase + 0x10Eu))
           << " queue=" << byte_hex(u8(kKpadBase + 0x10Fu))
           << " busy=" << byte_hex(u8(kKpadBase + 0x1BDCu))
           << " ext=" << byte_hex(u8(kKpadBase + 0x5Cu))
           << " probe=" << byte_hex(u8(kKpadBase + 0x5Du))
           << " flags=" << byte_hex(u8(kKpadBase + 0x1BDEu)) << '/'
           << byte_hex(u8(kKpadBase + 0x1BDFu)) << '/'
           << byte_hex(u8(kKpadBase + 0x1BE0u)) << '/'
           << byte_hex(u8(kKpadBase + 0x1BE1u)) << ')';
    output << " kstatus(hold=" << hexadecimal(u32(kKpadBase))
           << " trig=" << hexadecimal(u32(kKpadBase + 4u))
           << " rel=" << hexadecimal(u32(kKpadBase + 8u))
           << " err=" << byte_hex(u8(kKpadBase + 0x5Du))
           << " dev=" << byte_hex(u8(kKpadBase + 0x5Cu))
           << " dpd=" << byte_hex(u8(kKpadBase + 0x5Eu))
           << " fmt=" << byte_hex(u8(kKpadBase + 0x5Fu))
           << " pos=(" << f32_bits_text(kKpadBase + 0x20u)
           << ',' << f32_bits_text(kKpadBase + 0x24u) << ')'
           << " vec=(" << f32_bits_text(kKpadBase + 0x28u)
           << ',' << f32_bits_text(kKpadBase + 0x2Cu) << ')'
           << " speed=" << f32_bits_text(kKpadBase + 0x30u)
           << " horizon=(" << f32_bits_text(kKpadBase + 0x34u)
           << ',' << f32_bits_text(kKpadBase + 0x38u) << ')'
           << " dist=" << f32_bits_text(kKpadBase + 0x48u)
           << " accv=(" << f32_bits_text(kKpadBase + 0x54u)
           << ',' << f32_bits_text(kKpadBase + 0x58u) << ')'
           << ')';
    output << " kdpd(valid_objs=" << half_hex(u16(kKpadBase + 0x10Cu))
           << " sec_len=" << f32_bits_text(kKpadBase + 0x1B50u)
           << " sec_nrm=(" << f32_bits_text(kKpadBase + 0x1B54u)
           << ',' << f32_bits_text(kKpadBase + 0x1B58u) << ')'
           << " obj_hori=(" << f32_bits_text(kKpadBase + 0x1B70u)
           << ',' << f32_bits_text(kKpadBase + 0x1B74u) << ')'
           << " acc_hori=(" << f32_bits_text(kKpadBase + 0x1B78u)
           << ',' << f32_bits_text(kKpadBase + 0x1B7Cu) << ')'
           << ')';
    constexpr std::uint32_t kKpadObjectSize = 0x0Cu;
    constexpr std::uint32_t kKpadSampleBase = 0xC4u;
    constexpr std::uint32_t kKpadRegularBase = 0xF4u;
    for (std::uint32_t i = 0; i < 4u; ++i) {
        const std::uint32_t object =
            kKpadBase + kKpadSampleBase + i * kKpadObjectSize;
        output << " obj" << i
               << "(center=(" << f32_bits_text(object)
               << ',' << f32_bits_text(object + 4u) << ')'
               << " err=" << byte_hex(u8(object + 8u))
               << " state=" << byte_hex(u8(object + 9u))
               << ')';
    }
    for (std::uint32_t i = 0; i < 2u; ++i) {
        const std::uint32_t object =
            kKpadBase + kKpadRegularBase + i * kKpadObjectSize;
        output << " reg" << i
               << "(center=(" << f32_bits_text(object)
               << ',' << f32_bits_text(object + 4u) << ')'
               << " err=" << byte_hex(u8(object + 8u))
               << " state=" << byte_hex(u8(object + 9u))
               << ')';
    }
    for (std::uint32_t i = 0; i < 2u; ++i) {
        const std::uint32_t slot =
            kKpadBase + kKpadRingBase + i * kKpadStatusSize;
        output << " uwslot" << i
               << "(hold=" << hexadecimal(u32(slot))
               << " trig=" << hexadecimal(u32(slot + 4u))
               << " rel=" << hexadecimal(u32(slot + 8u))
               << " type=" << byte_hex(u8(slot + 0x28u))
               << " err=" << byte_hex(u8(slot + 0x29u))
               << " ext=" << byte_hex(u8(slot + 0x2Au))
               << ')';
    }

    if (guest_address == 0x804506D8u && has(arg4, 0x60u)) {
        output << " out0(hold=" << hexadecimal(u32(arg4))
               << " trig=" << hexadecimal(u32(arg4 + 4u))
               << " rel=" << hexadecimal(u32(arg4 + 8u))
               << " err=" << byte_hex(u8(arg4 + 0x5Du))
               << " ext=" << byte_hex(u8(arg4 + 0x5Cu))
               << " dpd=" << byte_hex(u8(arg4 + 0x5Eu))
               << " fmt=" << byte_hex(u8(arg4 + 0x5Fu))
               << " pos=(" << hexadecimal(u32(arg4 + 0x20u))
               << ',' << hexadecimal(u32(arg4 + 0x24u)) << ')'
               << " vec=(" << hexadecimal(u32(arg4 + 0x28u))
               << ',' << hexadecimal(u32(arg4 + 0x2Cu)) << ')'
               << " dist=" << hexadecimal(u32(arg4 + 0x48u))
               << ')';
    } else if (guest_address == 0x804D93C8u && has(arg4, 0x2Au)) {
        output << " wpad_out(btn=" << half_hex(u16(arg4))
               << " type=" << byte_hex(u8(arg4 + 0x28u))
               << " err=" << byte_hex(u8(arg4 + 0x29u))
               << " ext=" << byte_hex(u8(arg4 + 0x2Au))
               << ')';
    } else if (guest_address == 0x804D8ACCu && has(arg4, 4u)) {
        output << " probe_out=" << hexadecimal(u32(arg4));
    }
    if (guest_address == 0x80451198u) {
        output << " acl-stage=kpad-ring";
        dump_native_input_causal_sample(output, causal_sample);
    }
    output << '\n';
}

bool try_read_guest_f32(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address,
    float& out) {
    std::uint32_t bits = 0;
    if (!try_read_guest_u32(address_space, address, bits)) {
        return false;
    }
    const float value = std::bit_cast<float>(bits);
    if (!std::isfinite(value) || std::fabs(value) > 100000000.0f) {
        return false;
    }
    out = value;
    return true;
}

bool try_read_guest_vec3(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address,
    std::array<float, 3>& out) {
    return try_read_guest_f32(address_space, address + 0u, out[0]) &&
           try_read_guest_f32(address_space, address + 4u, out[1]) &&
           try_read_guest_f32(address_space, address + 8u, out[2]);
}

float vec3_delta2(
    const std::array<float, 3>& a,
    const std::array<float, 3>& b) {
    const float dx = a[0] - b[0];
    const float dy = a[1] - b[1];
    const float dz = a[2] - b[2];
    return dx * dx + dy * dy + dz * dz;
}

bool try_read_performance_mario_actor(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t self,
    std::array<float, 3>& position,
    std::array<float, 3>& velocity,
    std::array<float, 3>& previous_position) {
    constexpr std::uint32_t kActorAddressBegin = 0x80000000u;
    constexpr std::uint32_t kActorAddressEnd = 0x94000000u;
    constexpr std::uint32_t kActorProbeBytes = 0x2A0u;
    if (self < kActorAddressBegin ||
        self > kActorAddressEnd - kActorProbeBytes ||
        (self & 3u) != 0u ||
        address_space.pointer_or_null(self, kActorProbeBytes) == nullptr) {
        return false;
    }
    return try_read_guest_vec3(address_space, self + 0x0Cu, position) &&
           try_read_guest_vec3(address_space, self + 0x30u, velocity) &&
           try_read_guest_vec3(
               address_space, self + 0x294u, previous_position);
}

bool try_resolve_performance_mario_actor(
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext& context,
    std::uint32_t& chosen_register,
    std::uint32_t& self,
    std::array<float, 3>& position,
    std::array<float, 3>& velocity,
    std::array<float, 3>& previous_position) {
    constexpr std::array<std::uint32_t, 3> kCandidateRegisters{3u, 31u, 30u};
    for (const std::uint32_t candidate : kCandidateRegisters) {
        const std::uint32_t candidate_self = context.gpr[candidate];
        if (try_read_performance_mario_actor(
                address_space,
                candidate_self,
                position,
                velocity,
                previous_position)) {
            chosen_register = candidate;
            self = candidate_self;
            return true;
        }
    }
    return false;
}

PerformanceActorSemanticSample make_performance_actor_semantic_sample(
    std::uint32_t self,
    const std::array<float, 3>& position,
    const std::array<float, 3>& velocity,
    const std::array<float, 3>& previous_position) {
    PerformanceActorSemanticSample sample{};
    sample.mario_self = self;
    for (std::size_t component = 0u; component < 3u; ++component) {
        sample.position_bits[component] =
            std::bit_cast<std::uint32_t>(position[component]);
        sample.velocity_bits[component] =
            std::bit_cast<std::uint32_t>(velocity[component]);
        sample.previous_position_bits[component] =
            std::bit_cast<std::uint32_t>(previous_position[component]);
    }
    return sample;
}

bool is_route_marker_mario_address(std::uint32_t address);
bool is_route_marker_mario_control_address(std::uint32_t address);

bool performance_mario_marker_probe_needed(
    const RuntimeState& state,
    std::uint32_t guest_address) {
    if (!state.performance_runtime_v3 || state.benchmark_vi_started ||
        state.performance_mario_marker_proof.first_movement_seen) {
        return false;
    }
    if (!state.performance_mario_marker_proof.first_control_seen) {
        return is_route_marker_mario_control_address(guest_address);
    }
    return is_route_marker_mario_address(guest_address);
}

void observe_performance_mario_marker(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    PerformanceMarioMarkerProof& proof =
        state.performance_mario_marker_proof;
    if (!state.performance_runtime_v3 || state.benchmark_vi_started ||
        proof.first_movement_seen ||
        !is_route_marker_mario_address(guest_address)) {
        return;
    }
    if (state.address_space == nullptr) {
        throw RuntimeFailure(
            "native performance Mario marker has no guest address space");
    }

    std::array<float, 3> position{};
    std::array<float, 3> velocity{};
    std::array<float, 3> previous_position{};
    if (!proof.first_control_seen) {
        if (!is_route_marker_mario_control_address(guest_address)) {
            return;
        }
        std::uint32_t chosen_register = 0u;
        std::uint32_t self = 0u;
        if (!try_resolve_performance_mario_actor(
                *state.address_space,
                context,
                chosen_register,
                self,
                position,
                velocity,
                previous_position)) {
            throw RuntimeFailure(
                "native performance first Mario-control actor is unreadable "
                "in r3-r31-r30 priority");
        }
        proof.first_control_seen = true;
        proof.first_control_pc = guest_address;
        proof.first_control_boundary_ticks = runtime_time_base_ticks(state);
        proof.chosen_register = chosen_register;
        proof.anchor = make_performance_actor_semantic_sample(
            self, position, velocity, previous_position);
        proof.last_position = position;
        proof.last_position_valid = true;
        return;
    }

    if (!try_read_performance_mario_actor(
            *state.address_space,
            proof.anchor.mario_self,
            position,
            velocity,
            previous_position)) {
        return;
    }
    const float sample_delta2 = proof.last_position_valid
        ? vec3_delta2(position, proof.last_position)
        : 0.0f;
    const float actor_delta2 = vec3_delta2(position, previous_position);
    const float velocity2 =
        velocity[0] * velocity[0] + velocity[1] * velocity[1] +
        velocity[2] * velocity[2];
    proof.last_position = position;
    proof.last_position_valid = true;
    constexpr float kWalkingThreshold2 = 0.000001f;
    if (sample_delta2 <= kWalkingThreshold2 &&
        actor_delta2 <= kWalkingThreshold2 &&
        velocity2 <= kWalkingThreshold2) {
        return;
    }
    proof.first_movement_seen = true;
    proof.first_movement_pc = guest_address;
    proof.first_movement_boundary_ticks = runtime_time_base_ticks(state);
    proof.first_movement = make_performance_actor_semantic_sample(
        proof.anchor.mario_self, position, velocity, previous_position);
}

PerformanceStartSemanticState capture_performance_start_semantic_state(
    RuntimeState& state) {
    const PerformanceMarioMarkerProof& proof =
        state.performance_mario_marker_proof;
    if (!proof.first_control_seen || !proof.first_movement_seen ||
        proof.first_control_boundary_ticks == 0u ||
        proof.first_movement_boundary_ticks == 0u ||
        proof.first_movement_boundary_ticks <
            proof.first_control_boundary_ticks ||
        proof.anchor.mario_self == 0u ||
        proof.first_movement.mario_self != proof.anchor.mario_self ||
        state.address_space == nullptr) {
        throw RuntimeFailure(
            "native performance route lacks pre-window Mario control and "
            "playable-movement proof");
    }

    std::array<float, 3> position{};
    std::array<float, 3> velocity{};
    std::array<float, 3> previous_position{};
    if (!try_read_performance_mario_actor(
            *state.address_space,
            proof.anchor.mario_self,
            position,
            velocity,
            previous_position)) {
        throw RuntimeFailure(
            "native performance start Mario semantic state is unreadable");
    }

    PerformanceStartSemanticState snapshot{};
    snapshot.captured = true;
    snapshot.start = make_performance_actor_semantic_sample(
        proof.anchor.mario_self, position, velocity, previous_position);
    if (snapshot.start.mario_self != proof.anchor.mario_self) {
        throw RuntimeFailure(
            "native performance Mario self changed before measurement start");
    }
    append_performance_semantic_literal(snapshot, "domain=");
    append_performance_semantic_literal(
        snapshot, kPerformanceStartSemanticStateDomain);
    append_performance_semantic_literal(snapshot, "\n");
    append_performance_semantic_hex_field(
        snapshot, "anchorPc", proof.first_control_pc);
    append_performance_semantic_register_field(snapshot, proof.chosen_register);
    append_performance_semantic_sample(snapshot, "anchor", proof.anchor);
    append_performance_semantic_hex_field(
        snapshot, "firstMovementPc", proof.first_movement_pc);
    append_performance_semantic_sample(
        snapshot, "firstMovement", proof.first_movement);
    append_performance_semantic_sample(snapshot, "start", snapshot.start);
    snapshot.canonical_sealed = true;
    return snapshot;
}

template <std::size_t Size>
void capture_route_marker_guest_string(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t address,
    std::array<char, Size>& snapshot) {
    static_assert(Size > 0u);
    snapshot.fill('\0');
    if (address < 0x80000000u || address >= 0x94000000u) {
        return;
    }
    for (std::size_t index = 0u; index + 1u < snapshot.size(); ++index) {
        const std::uint32_t current =
            address + static_cast<std::uint32_t>(index);
        if (address_space.pointer_or_null(current, 1u) == nullptr) {
            return;
        }
        const unsigned char value = read_guest_u8(address_space, current);
        if (value == 0u) {
            return;
        }
        snapshot[index] = value < 0x20u || value >= 0x7Fu
            ? '?'
            : static_cast<char>(value);
    }
}

template <std::size_t Size>
void capture_route_marker_name_obj_name(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t object,
    std::array<char, Size>& snapshot) {
    std::uint32_t name = 0u;
    if (!try_read_guest_u32(address_space, object + 0x04u, name)) {
        snapshot.fill('\0');
        return;
    }
    capture_route_marker_guest_string(address_space, name, snapshot);
}

template <std::size_t Size>
void capture_route_marker_hit_sensor_host_name(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t sensor,
    std::array<char, Size>& snapshot) {
    std::uint32_t host = 0u;
    if (!try_read_guest_u32(address_space, sensor + 0x24u, host)) {
        snapshot.fill('\0');
        return;
    }
    capture_route_marker_name_obj_name(address_space, host, snapshot);
}

void capture_route_marker_kcl_snapshot(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t kcl,
    RuntimeState::RouteMarkerKclSnapshot& snapshot) {
    snapshot = {};
    snapshot.address = kcl;
    if (!mapped_guest_range(address_space, kcl, 0x38u)) {
        return;
    }
    snapshot.mapped = true;
    snapshot.positions = address_space.read_u32(kcl + 0x00u);
    snapshot.normals = address_space.read_u32(kcl + 0x04u);
    snapshot.prisms = address_space.read_u32(kcl + 0x08u);
    snapshot.octree = address_space.read_u32(kcl + 0x0Cu);
    snapshot.thickness_valid =
        try_read_guest_f32(address_space, kcl + 0x10u, snapshot.thickness);
    snapshot.shifts = {
        static_cast<std::int32_t>(address_space.read_u32(kcl + 0x2Cu)),
        static_cast<std::int32_t>(address_space.read_u32(kcl + 0x30u)),
        static_cast<std::int32_t>(address_space.read_u32(kcl + 0x34u))};
}

void append_route_marker_kcl_snapshot(
    std::ostream& out,
    const RuntimeState::RouteMarkerKclSnapshot& snapshot) {
    out << " kcl=" << hexadecimal(snapshot.address);
    if (!snapshot.mapped) {
        out << " kclMapped=0";
        return;
    }
    const bool swizzled = (snapshot.positions & 0x80000000u) != 0u;
    out << " kclMapped=1"
        << " kclKind=" << (swizzled ? "swizzled" : "raw")
        << " pos=" << hexadecimal(snapshot.positions)
        << " norms=" << hexadecimal(snapshot.normals)
        << " prisms=" << hexadecimal(snapshot.prisms)
        << " octree=" << hexadecimal(snapshot.octree);
    if (snapshot.thickness_valid) {
        out << " thickness=" << snapshot.thickness;
    }
    out << " shifts=" << snapshot.shifts[0] << ',' << snapshot.shifts[1]
        << ',' << snapshot.shifts[2];
}

enum class SaveTraceNerveKind {
    SaveSequence,
    SaveDataHandler,
    NandErrorSequence,
};

const char* save_sequence_nerve_label(
    std::uint32_t r13,
    std::uint32_t nerve) {
    switch (nerve - r13) {
        case 0xFFFFD930u: return "seq:NoOperation";
        case 0xFFFFD934u: return "seq:CheckEnableToCreate";
        case 0xFFFFD938u: return "seq:SaveConfirm";
        case 0xFFFFD93Cu: return "seq:Save";
        case 0xFFFFD940u: return "seq:SaveWindowDisappear";
        case 0xFFFFD944u: return "seq:SaveDoneKeyWait";
        case 0xFFFFD948u: return "seq:SaveAllWithoutKeyWait";
        case 0xFFFFD94Cu: return "seq:SaveAllWithoutKeyWaitDisappear";
        case 0xFFFFD950u: return "seq:SaveAllWithoutWindow";
        case 0xFFFFD954u: return "seq:PreLoad";
        case 0xFFFFD958u: return "seq:PreLoadDone";
        case 0xFFFFD95Cu: return "seq:NoSaveConfirmRemind";
        case 0xFFFFD960u: return "seq:ErrorHandling";
        default: return nullptr;
    }
}

