void append_labeled_nerve(
    std::ostream& out,
    const char* name,
    std::uint32_t r13,
    std::uint32_t nerve,
    const char* (*label_fn)(std::uint32_t, std::uint32_t)) {
    out << ' ' << name << '=' << hexadecimal(nerve);
    if (const char* label = label_fn(r13, nerve)) {
        out << '(' << label << ')';
    }
}

void append_nerve(
    std::ostream& out,
    const char* name,
    SaveTraceNerveKind kind,
    std::uint32_t r13,
    std::uint32_t nerve) {
    out << ' ' << name << '=' << hexadecimal(nerve);
    if (const char* label = save_trace_nerve_label(kind, r13, nerve)) {
        out << '(' << label << ')';
    }
}

void append_generic_spine_state(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t r13,
    const char* name,
    std::uint32_t owner,
    const char* (*label_fn)(std::uint32_t, std::uint32_t)) {
    const std::uint32_t spine = read_guest_u32_or_zero(address_space, owner + 4u);
    const std::uint32_t curr = read_guest_u32_or_zero(address_space, spine + 4u);
    const std::uint32_t next = read_guest_u32_or_zero(address_space, spine + 8u);
    const std::uint32_t step = read_guest_u32_or_zero(address_space, spine + 0x0Cu);
    out << ' ' << name << '=' << hexadecimal(owner)
        << " spine=" << hexadecimal(spine);
    append_labeled_nerve(out, "curr", r13, curr, label_fn);
    append_labeled_nerve(out, "next", r13, next, label_fn);
    out << " step=" << static_cast<std::int32_t>(step);
}

void append_spine_state(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t r13,
    const char* name,
    SaveTraceNerveKind kind,
    std::uint32_t owner) {
    const std::uint32_t spine = read_guest_u32_or_zero(address_space, owner + 4u);
    const std::uint32_t curr = read_guest_u32_or_zero(address_space, spine + 4u);
    const std::uint32_t next = read_guest_u32_or_zero(address_space, spine + 8u);
    const std::uint32_t step = read_guest_u32_or_zero(address_space, spine + 0x0Cu);
    out << ' ' << name << '=' << hexadecimal(owner)
        << " spine=" << hexadecimal(spine);
    append_nerve(out, "curr", kind, r13, curr);
    append_nerve(out, "next", kind, r13, next);
    out << " step=" << static_cast<std::int32_t>(step);
}

void append_guest_words(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const char* label,
    std::uint32_t base,
    std::initializer_list<std::uint32_t> offsets) {
    out << ' ' << label << "Words=";
    bool first = true;
    for (const std::uint32_t offset : offsets) {
        if (!first) {
            out << ',';
        }
        first = false;
        out << hexadecimal(offset) << ':'
            << hexadecimal(read_guest_u32_or_zero(address_space, base + offset));
    }
}

void append_guest_string_probe(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    const char* label,
    std::uint32_t address,
    std::size_t max_length = 64u) {
    out << ' ' << label << '=' << hexadecimal(address)
        << ":'" << read_guest_string(address_space, address, max_length) << '\'';
}

void append_save_data_handler_snapshot(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t r13,
    const char* label,
    std::uint32_t handler) {
    out << ' ' << label << '=' << hexadecimal(handler);
    if (!mapped_guest_range(address_space, handler, 0x28u)) {
        out << ".mapped=0";
        return;
    }

    append_spine_state(
        out,
        address_space,
        r13,
        label,
        SaveTraceNerveKind::SaveDataHandler,
        handler);
    const std::uint32_t op08 = read_guest_u32_or_zero(address_space, handler + 0x08u);
    const std::uint32_t nand0c =
        read_guest_u32_or_zero(address_space, handler + 0x0Cu);
    out << ' ' << label << ".check="
        << read_guest_u32_or_zero(address_space, handler + 0x10u)
        << ' ' << label << ".op08=" << hexadecimal(op08)
        << ' ' << label << ".nand0c=" << hexadecimal(nand0c)
        << ' ' << label << ".buf14="
        << hexadecimal(read_guest_u32_or_zero(address_space, handler + 0x14u))
        << ' ' << label << ".buf18="
        << hexadecimal(read_guest_u32_or_zero(address_space, handler + 0x18u))
        << ' ' << label << ".count20="
        << read_guest_u32_or_zero(address_space, handler + 0x20u)
        << ' ' << label << ".flags="
        << static_cast<unsigned>(read_guest_u8_or_zero(address_space, handler + 0x24u))
        << static_cast<unsigned>(read_guest_u8_or_zero(address_space, handler + 0x25u))
        << static_cast<unsigned>(read_guest_u8_or_zero(address_space, handler + 0x26u));
    append_guest_words(
        out,
        address_space,
        (std::string(label) + ".op08").c_str(),
        op08,
        {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x40u, 0x44u,
         0x48u, 0x5Cu, 0x60u});
    append_guest_words(
        out,
        address_space,
        (std::string(label) + ".nand0c").c_str(),
        nand0c,
        {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x40u, 0x44u,
         0x48u, 0x5Cu, 0x60u, 0x68u, 0xACu});
    append_guest_string_probe(
        out,
        address_space,
        (std::string(label) + ".op08.s0").c_str(),
        op08);
    append_guest_string_probe(
        out,
        address_space,
        (std::string(label) + ".op08.s1").c_str(),
        op08 + 1u);
    append_guest_string_probe(
        out,
        address_space,
        (std::string(label) + ".nand0c.s8").c_str(),
        nand0c + 0x08u);
}

void append_save_scene_gate_snapshot(
    std::ostream& out,
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t r13,
    std::uint32_t scene_system) {
    const std::uint32_t gate =
        read_guest_u32_or_zero(address_space, scene_system + 0x98u);
    const std::uint32_t ac =
        read_guest_u32_or_zero(address_space, scene_system + 0xACu);
    const std::uint32_t b8 =
        read_guest_u32_or_zero(address_space, scene_system + 0xB8u);
    const std::uint32_t window =
        read_guest_u32_or_zero(address_space, scene_system + 0xBCu);

    out << " sceneGate.system=" << hexadecimal(scene_system)
        << " sceneGate.ptr98=" << hexadecimal(gate)
        << " sceneGate.ptrAC=" << hexadecimal(ac)
        << " sceneGate.ptrB8=" << hexadecimal(b8)
        << " sceneGate.ptrBC=" << hexadecimal(window);

    if (gate != 0u) {
        append_generic_spine_state(
            out,
            address_space,
            r13,
            " sceneGate.98",
            gate,
            scene_gate_nerve_label);
        out << " sceneGate.98.word0C="
            << read_guest_u32_or_zero(address_space, gate + 0x0Cu)
            << " sceneGate.98.bytes="
            << static_cast<unsigned>(read_guest_u8_or_zero(address_space, gate + 0x0Cu))
            << ','
            << static_cast<unsigned>(read_guest_u8_or_zero(address_space, gate + 0x0Du))
            << ','
            << static_cast<unsigned>(read_guest_u8_or_zero(address_space, gate + 0x0Eu))
            << ','
            << static_cast<unsigned>(read_guest_u8_or_zero(address_space, gate + 0x0Fu));
    }

    if (window != 0u) {
        append_generic_spine_state(
            out,
            address_space,
            r13,
            " sceneGate.BC",
            window,
            scene_window_nerve_label);
        out << " sceneGate.BC.flags14="
            << static_cast<unsigned>(read_guest_u8_or_zero(address_space, window + 0x14u))
            << " flags15="
            << static_cast<unsigned>(read_guest_u8_or_zero(address_space, window + 0x15u))
            << " flags28="
            << static_cast<unsigned>(read_guest_u8_or_zero(address_space, window + 0x28u))
            << " word18="
            << hexadecimal(read_guest_u32_or_zero(address_space, window + 0x18u))
            << " word1C="
            << hexadecimal(read_guest_u32_or_zero(address_space, window + 0x1Cu))
            << " word20="
            << hexadecimal(read_guest_u32_or_zero(address_space, window + 0x20u));
    }
}

