void record_jutvideo_mq_entry(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext* context,
    std::uint32_t caller_lr);

// Generated modules emit only this fixed marker set from statically selected
// C++ function entries.  Consume them before the normal diagnostic logger
// filters Trace output, so collecting the evidence is independent of
// stdout/stderr timing and cannot become a per-frame logging cost.
bool capture_generated_main_frame_trace(
    void* user,
    galaxy::LogLevelV1 level,
    const char* message) {
    if (level != galaxy::LogLevelV1::Trace || user == nullptr) {
        return false;
    }
    if (capture_scene_nerve_child_marker(*static_cast<RuntimeState*>(user), message)) {
        return true;
    }
    // The generated leaf intentionally flushes on the first call AFTER its
    // window closes. Consume before window/ordinary Trace filtering, then
    // print only from the existing terminal main-frame dump.
    if (static_cast<RuntimeState*>(user)->psmtx_guard_trace.capture(message)) {
        return true;
    }
    const std::uint32_t guest_address =
        generated_main_frame_trace_marker_address(message);
    if (guest_address == 0u) {
        return false;
    }
    record_main_frame_call(
        *static_cast<RuntimeState*>(user), guest_address, 0u);
    return true;
}

struct GeneratedJutVideoMqTraceMarker {
    std::uint32_t guest_address{};
    std::uint32_t caller_lr{};
};

bool decode_fixed_hex_u32(const char* text, std::uint32_t* value) {
    if (text == nullptr || value == nullptr) {
        return false;
    }
    std::uint32_t decoded = 0u;
    for (std::size_t index = 0u; index < 8u; ++index) {
        const unsigned char character =
            static_cast<unsigned char>(text[index]);
        std::uint32_t nibble = 0u;
        if (character >= static_cast<unsigned char>('0') &&
            character <= static_cast<unsigned char>('9')) {
            nibble = character - static_cast<unsigned char>('0');
        } else if (character >= static_cast<unsigned char>('A') &&
                   character <= static_cast<unsigned char>('F')) {
            nibble = 10u + character - static_cast<unsigned char>('A');
        } else {
            return false;
        }
        decoded = (decoded << 4u) | nibble;
    }
    *value = decoded;
    return true;
}

bool parse_generated_jutvideo_mq_trace_marker(
    const char* message,
    GeneratedJutVideoMqTraceMarker* marker) {
    if (message == nullptr || marker == nullptr) {
        return false;
    }
    constexpr char kPrefix[] = "__galaxy_jutvideo_mq_entry:";
    constexpr std::size_t kPrefixLength = sizeof(kPrefix) - 1u;
    if (std::strncmp(message, kPrefix, kPrefixLength) != 0) {
        return false;
    }
    const char* suffix = message + kPrefixLength;
    const std::size_t suffix_length = std::strlen(suffix);
    if (suffix_length != 8u && suffix_length != 17u) {
        return false;
    }
    if (suffix_length == 17u && suffix[8] != ':') {
        return false;
    }
    GeneratedJutVideoMqTraceMarker parsed{};
    if (!decode_fixed_hex_u32(suffix, &parsed.guest_address) ||
        (suffix_length == 17u &&
         !decode_fixed_hex_u32(suffix + 9u, &parsed.caller_lr))) {
        return false;
    }
    if (parsed.guest_address != 0x80419554u &&
        parsed.guest_address != 0x804A88E4u &&
        parsed.guest_address != 0x804A89ACu &&
        parsed.guest_address != 0x804A8A88u) {
        return false;
    }
    *marker = parsed;
    return true;
}

// The installer-time compiler emits this fixed marker set at the three
// translated JUTVideo queue entries.  It is captured before the ordinary log
// filtering and dumped only after the measured interval, so it cannot become
// a producer/consumer timing input.
bool capture_generated_jutvideo_mq_trace(
    void* user,
    galaxy::LogLevelV1 level,
    const char* message) {
    if (level != galaxy::LogLevelV1::Trace || user == nullptr) {
        return false;
    }
    GeneratedJutVideoMqTraceMarker marker{};
    if (!parse_generated_jutvideo_mq_trace_marker(message, &marker)) {
        return false;
    }
    record_jutvideo_mq_entry(
        *static_cast<RuntimeState*>(user), marker.guest_address, nullptr,
        marker.caller_lr);
    return true;
}

const char* jutvideo_mq_operation_label(std::uint32_t guest_address) {
    switch (guest_address) {
        case 0x80419554u: return "producer-entry";
        case 0x804A88E4u: return "send";
        case 0x804A89ACu: return "receive";
        case 0x804A8A88u: return "jam";
        default: return "unknown";
    }
}

void dump_jutvideo_mq_trace(
    const RuntimeState& state,
    std::ostream& output) {
    if (!trace_jutvideo_mq()) {
        return;
    }
    const std::size_t capacity = jutvideo_mq_trace_capacity();
    const std::size_t count = std::min(
        state.jutvideo_mq_record_count, capacity);
    const std::size_t start = state.jutvideo_mq_record_count >= capacity
        ? state.jutvideo_mq_record_count % capacity
        : 0u;
    if (state.jutvideo_mq_record_count > capacity) {
        output << "[jut-mq] retained-last=" << count
               << " total-samples=" << state.jutvideo_mq_record_count
               << " dropped=" << (state.jutvideo_mq_record_count - count)
               << '\n';
    }
    bool has_previous_sample = false;
    std::uint64_t previous_host_time_ns = 0u;
    for (std::size_t index = 0u; index < count; ++index) {
        const RuntimeState::JutVideoMqRecord& record =
            state.jutvideo_mq_records[(start + index) % capacity];
        const std::uint64_t delta_us =
            has_previous_sample && record.host_time_ns >= previous_host_time_ns
                ? (record.host_time_ns - previous_host_time_ns) / 1'000u
                : 0u;
        output << "[jut-mq] vi=" << record.vi
               << " hostNs=" << record.host_time_ns
               << " deltaBaselineAvailable=" << (has_previous_sample ? 1 : 0)
               << " deltaUs=" << delta_us
               << " op=" << jutvideo_mq_operation_label(record.guest_address)
               << " entry=" << hexadecimal(record.guest_address)
               << " callerLr=" << hexadecimal(record.caller_lr)
               << " curCtx=" << hexadecimal(record.current_context)
               << " curThr=" << hexadecimal(record.current_thread)
               << " mq=" << hexadecimal(record.message_queue)
               << " count=" << record.message_count
               << " first=" << record.first_index
               << " used=" << record.used_count
               << " nextMsg=" << hexadecimal(record.next_message)
               << '\n';
        has_previous_sample = true;
        previous_host_time_ns = record.host_time_ns;
    }
}

void dump_main_frame_dsp_poll_timing(
    std::ostream& output,
    const galaxy::cadence::DspPollTimingSnapshot& snapshot) {
    constexpr std::array<const char*, 4u> labels{
        "dsp-preflight-poll", "dsp-publication-poll",
        "dsp-preflight-yield", "dsp-publication-yield"};
    output << " dsp-poll-measured=" << (snapshot.valid ? 1 : 0);
    for (std::size_t index = 0u; index < labels.size(); ++index) {
        output << ' ' << labels[index] << "-count=" << snapshot.counts[index]
               << ' ' << labels[index] << "-ns=" << snapshot.total_ns[index];
    }
}

void dump_main_frame_trace(const RuntimeState& state, std::ostream& output) {
    state.psmtx_guard_trace.dump(output);
    if (!trace_main_frame_enabled()) {
        return;
    }
    if (trace_main_frame_relative_to_mario_control_enabled()) {
        output << "[main-frame-window] mode=mario-control-relative"
               << " anchorSeen="
               << (state.route_marker_first_mario_control_seen ? 1u : 0u)
               << " anchorVi=" << state.route_marker_first_mario_control_vi
               << " startAge="
               << read_env_u64(
                      "GALAXY_TRACE_MAIN_FRAME_AFTER_MARIO_CONTROL_START_VI",
                      0u)
               << " endAge="
               << read_env_u64(
                      "GALAXY_TRACE_MAIN_FRAME_AFTER_MARIO_CONTROL_END_VI",
                      0u)
               << '\n';
    }
    for (const auto& summary : state.main_frame_scene_summaries) {
        if (summary.samples == 0u && summary.failed_snapshots == 0u) continue;
        output << "[main-frame-scene-summary] pc=" << hexadecimal(summary.first.pc)
               << " samples=" << summary.samples
               << " failed=" << summary.failed_snapshots
               << " firstHostNs=" << summary.first.host_time_ns
               << " lastHostNs=" << summary.last.host_time_ns
               << " firstVi=" << summary.first.vi << " lastVi=" << summary.last.vi
               << " firstOwner=" << hexadecimal(summary.first.scene_owner)
               << " lastOwner=" << hexadecimal(summary.last.scene_owner)
               << " firstNerve=" << hexadecimal(summary.first.scene_curr_nerve)
               << " lastNerve=" << hexadecimal(summary.last.scene_curr_nerve)
               << " firstStep=" << summary.first.scene_step
               << " lastStep=" << summary.last.scene_step
               << " stepIncrements=" << summary.step_increments
               << " repeatedSteps=" << summary.repeated_steps
               << " discontinuities=" << summary.discontinuities
               << " maxStepJump=" << summary.max_step_jump << '\n';
    }
    const std::size_t count = std::min(
        state.main_frame_call_record_count,
        state.main_frame_call_records.size());
    const std::size_t start =
        state.main_frame_call_record_count >=
                state.main_frame_call_records.size()
            ? state.main_frame_call_record_count %
                state.main_frame_call_records.size()
            : 0u;
    if (state.main_frame_call_record_count >
        state.main_frame_call_records.size()) {
        output << "[main-frame] retained-last=" << count
               << " total-samples=" << state.main_frame_call_record_count
               << " dropped="
               << (state.main_frame_call_record_count - count) << '\n';
    }
    bool has_previous_sample = false;
    std::uint64_t previous_host_time_ns = 0u;
    std::uint64_t previous_thread_cpu_time_100ns = 0u;
    std::uint64_t previous_thread_cycle_count = 0u;
    for (std::size_t index = 0u; index < count; ++index) {
        const RuntimeState::MainFrameCallRecord& record =
            state.main_frame_call_records[
                (start + index) % state.main_frame_call_records.size()];
        if (record.nerve_owner_kind != 0u) {
            continue; // Do not alter the original stage-to-stage deltas.
        }
        const char* label = main_frame_call_label(record.pc);
        const std::uint64_t delta_us =
            has_previous_sample && record.host_time_ns >= previous_host_time_ns
                ? (record.host_time_ns - previous_host_time_ns) / 1'000u
                : 0u;
        const std::uint64_t cpu_delta_us =
            has_previous_sample && record.thread_cpu_time_100ns >= previous_thread_cpu_time_100ns
                ? (record.thread_cpu_time_100ns -
                   previous_thread_cpu_time_100ns) /
                    10u
                : 0u;
        const std::uint64_t cycle_delta =
            has_previous_sample && record.thread_cycle_count >= previous_thread_cycle_count
                ? record.thread_cycle_count - previous_thread_cycle_count
                : 0u;
        output << "[main-frame] vi=" << record.vi
               << " hostNs=" << record.host_time_ns
               << " deltaBaselineAvailable=" << (has_previous_sample ? 1 : 0)
               << " deltaUs=" << delta_us
               << " threadCpu100ns=" << record.thread_cpu_time_100ns
               << " cpuDeltaUs=" << cpu_delta_us
               << " threadCycles=" << record.thread_cycle_count
               << " cycleDelta=" << cycle_delta
               << " call=" << (label != nullptr ? label : "?")
               << " pc=" << hexadecimal(record.pc)
               << " lr=" << hexadecimal(record.lr)
               << " ctx=" << hexadecimal(record.current_context)
               << " thr=" << hexadecimal(record.current_thread)
               << " runbits=" << hexadecimal(record.run_queue_bits)
               << " xfb.drawing=" << record.drawing
               << " xfb.drawn=" << record.drawn
               << " xfb.displaying=" << record.displaying
               << " renderCounter=" << record.render_counter
               << " doRender=" << static_cast<unsigned>(record.do_render);
        dump_main_frame_dsp_poll_timing(output, record.dsp_poll_timing);
        if (record.pc == 0x80399AF0u || record.pc == 0x803A00FCu) {
            output << " sceneSnapshot=" << (record.scene_spine_snapshot ? 1 : 0)
                   << " sceneSnapshotFailure="
                   << static_cast<unsigned>(record.scene_snapshot_failure);
            if (record.scene_spine_snapshot) {
                output << " sceneOwner=" << hexadecimal(record.scene_owner)
                       << " sceneSpine=" << hexadecimal(record.scene_spine)
                       << " sceneCurrNerve="
                       << hexadecimal(record.scene_curr_nerve)
                       << " sceneNextNerve="
                       << hexadecimal(record.scene_next_nerve)
                       << " sceneStep="
                       << static_cast<std::int32_t>(record.scene_step);
            }
        }
        output << " input-timeline-vi=" << record.input_timeline_vi << '\n';
        has_previous_sample = true;
        previous_host_time_ns = record.host_time_ns;
        previous_thread_cpu_time_100ns = record.thread_cpu_time_100ns;
        previous_thread_cycle_count = record.thread_cycle_count;
    }
    const std::size_t dynamic_count = std::min(
        state.main_frame_dynamic_call_record_count,
        state.main_frame_dynamic_call_records.size());
    const std::size_t dynamic_start =
        state.main_frame_dynamic_call_record_count >=
                state.main_frame_dynamic_call_records.size()
            ? state.main_frame_dynamic_call_record_count %
                state.main_frame_dynamic_call_records.size()
            : 0u;
    if (state.main_frame_dynamic_call_record_count >
        state.main_frame_dynamic_call_records.size()) {
        output << "[main-frame-dynamic] retained-last=" << dynamic_count
               << " total-samples=" << state.main_frame_dynamic_call_record_count
               << " dropped="
               << (state.main_frame_dynamic_call_record_count - dynamic_count)
               << '\n';
    }
    if (trace_main_frame_member_targets_enabled()) {
        output << "[main-frame-member-coverage] schema=1"
               << " scope=observed-dispatch-boundaries"
               << " cold-unresolved-interceptor=unknown"
               << " pre-dispatch-input-transfer=unobserved"
               << " numeric-category=unobserved" << '\n';
    }
    for (std::size_t index = 0u; index < dynamic_count; ++index) {
        const RuntimeState::MainFrameDynamicCallRecord& record =
            state.main_frame_dynamic_call_records[
                (dynamic_start + index) %
                state.main_frame_dynamic_call_records.size()];
        output << "[main-frame-dynamic] vi=" << record.vi
               << " call-pc=" << hexadecimal(record.call_pc)
               << " target=" << hexadecimal(record.target)
               << " path=" << (record.cached ? "cached" : "resolved")
               << " stage=" << (record.completed ? "return" : "entry")
               << " wall-us=" << record.elapsed_ns / 1'000u
               << " cpu-us=" << record.thread_cpu_elapsed_100ns / 10u
               << " hostNs=" << record.host_time_ns
               << " serial=" << record.serial
               << " entry-serial=" << record.entry_serial
               << " boundary="
               << (record.host_boundary ? "cached-host-wrapper" : "guest-body")
               << " register-snapshot=" << (record.register_snapshot ? 1 : 0);
        dump_main_frame_dsp_poll_timing(output, record.dsp_poll_timing);
        if (record.register_snapshot) {
            constexpr auto& registers =
                galaxy::diagnostics::kMemberEntryRegisters;
            for (std::size_t reg = 0u; reg < registers.size(); ++reg) {
                output << " r" << registers[reg] << '='
                       << hexadecimal(record.entry_gpr[reg]);
            }
            output << " ctr=" << hexadecimal(record.entry_ctr);
        }
        output << '\n';
    }
}

bool is_route_marker_call_address(std::uint32_t address) {
    switch (address) {
        case 0x802AFD80u: // MarioActor::movement entry
        case 0x802B0364u: // MarioActor::movement
        case 0x802B0394u: // MarioActor::movement loop checkpoint
        case 0x802B0D0Cu: // MarioActor::updateBindRatio entry
        case 0x802B0D38u: // MarioActor::updateBindRatio interior
        case 0x802B0E18u: // MarioActor::isInPunchTimerRange entry
        case 0x802B0E60u: // MarioActor::isInPunchTimerRange call return
        case 0x802B0FE4u: // MarioActor::doRush entry
        case 0x802B1004u: // MarioActor::doRush interior
        case 0x802B10ECu: // MarioActor::doRush interior
        case 0x802B2A28u: // MarioActor::calcAnimInMovement entry
        case 0x802B2B34u: // MarioActor::calcAnimInMovement
        case 0x802B300Cu: // MarioActor::calcAnim
        case 0x802B321Cu: // MarioActor::calcAndSetBaseMtx entry
        case 0x802B3800u: // MarioActor::calcAndSetBaseMtx
        case 0x802CAC98u: // Mario animation state helper entry
        case 0x802CAD70u: // Mario animation state helper
        case 0x802CAF9Cu: // Mario animation blend helper entry
        case 0x802CB580u: // Mario animation blend helper
        case 0x803EABE0u: // MR::isExistCollisionResource
        case 0x803DF804u: // MR::initCollisionParts
        case 0x80175EA4u: // CollisionParts::init
        case 0x80183140u: // KCollisionServer::init
        case 0x803E1F00u: // MR::getFirstPolyOnLineToMap
        case 0x8037175Cu: // MoviePlayerSimple::exePlaying
        case 0x80371780u: // MoviePlayerSimple::exePlaying loop checkpoint
        case 0x80371FE8u: // MoviePlayingSequence::exePlay
        case 0x8038D2E4u: // THPSimplePlayerWrapper::videoDecode
        case 0x8038D34Cu: // THPSimplePlayerWrapper::readFrameAsync
        case 0x8038D868u: // THPSimplePlayerWrapper::exeReadFrameComp
            return true;
        default:
            return false;
    }
}

bool is_route_marker_mario_address(std::uint32_t address) {
    switch (address) {
        case 0x802AFD80u:
        case 0x802B0364u:
        case 0x802B0394u:
        case 0x802B0D0Cu:
        case 0x802B0D38u:
        case 0x802B0E18u:
        case 0x802B0E60u:
        case 0x802B0FE4u:
        case 0x802B1004u:
        case 0x802B10ECu:
        case 0x802B2A28u:
        case 0x802B2B34u:
        case 0x802B300Cu:
        case 0x802B321Cu:
        case 0x802B3800u:
        case 0x802CAC98u:
        case 0x802CAD70u:
        case 0x802CAF9Cu:
        case 0x802CB580u:
            return true;
        default:
            return false;
    }
}

// Historical route-selector/schema name retained for capture compatibility.
// The six PCs below are RMGE01 actor-update observations, not control entries:
// 0D0C updateBindRatio; 0E18 isInPunchTimerRange; 0FE4 doRush and their interiors.
// Functional input publication additionally requires the exact opening scene.
bool is_route_marker_mario_control_address(std::uint32_t address) {
    switch (address) {
        case 0x802B0D0Cu: // MarioActor::updateBindRatio entry
        case 0x802B0D38u: // MarioActor::updateBindRatio interior
        case 0x802B0E18u: // MarioActor::isInPunchTimerRange entry
        case 0x802B0E60u: // MarioActor::isInPunchTimerRange call return
        case 0x802B0FE4u: // MarioActor::doRush entry
        case 0x802B1004u: // MarioActor::doRush interior
            return true;
        default:
            return false;
    }
}

bool is_route_marker_movie_address(std::uint32_t address) {
    switch (address) {
        case 0x8037175Cu:
        case 0x80371780u:
        case 0x80371FE8u:
        case 0x8038D2E4u:
        case 0x8038D34Cu:
        case 0x8038D868u:
            return true;
        default:
            return false;
    }
}

bool is_route_marker_collision_address(std::uint32_t address) {
    switch (address) {
        case 0x803EABE0u:
        case 0x803DF804u:
        case 0x80175EA4u:
        case 0x80183140u:
        case 0x803E1F00u:
            return true;
        default:
            return false;
    }
}

RuntimeState::RouteMarkerRecord* record_route_marker(
    RuntimeState& state,
    RuntimeState::RouteMarkerKind kind,
    RuntimeState::RouteMarkerSource source,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context,
    std::uint32_t mario_self,
    std::array<float, 3> mario_pos,
    float sample_delta2,
    float actor_delta2,
    float velocity2) {
    if (state.route_marker_record_count >=
        state.route_marker_records.size()) {
        return nullptr;
    }

    RuntimeState::RouteMarkerRecord& record =
        state.route_marker_records[state.route_marker_record_count++];
    record = {};
    record.kind = kind;
    record.source = source;
    record.vi = state.vi_retrace_count;
    // Capture the native HID deadline domain at this actual observation.
    // The relative retrace counter remains a distinct raw measurement.
    record.input_timeline_vi = runtime_time_base_ticks(state) / kViRetracePeriodTicks;
    record.guest_address = guest_address;
    record.lr = context.lr;
    record.r3 = context.gpr[3];
    record.r4 = context.gpr[4];
    record.r5 = context.gpr[5];
    record.r6 = context.gpr[6];
    record.r7 = context.gpr[7];
    record.r8 = context.gpr[8];
    record.r30 = context.gpr[30];
    record.r31 = context.gpr[31];
    record.mario_self = mario_self;
    record.mario_pos = mario_pos;
    record.sample_delta2 = sample_delta2;
    record.actor_delta2 = actor_delta2;
    record.velocity2 = velocity2;
    return &record;
}

void capture_route_marker_collision_snapshot(
    const galaxy::host::GuestAddressSpace& address_space,
    RuntimeState::RouteMarkerRecord& record) {
    switch (record.guest_address) {
        case 0x803EABE0u: // MR::isExistCollisionResource
            capture_route_marker_name_obj_name(
                address_space, record.r3, record.actor_name);
            capture_route_marker_guest_string(
                address_space, record.r4, record.collision_name);
            static_cast<void>(try_read_guest_u32(
                address_space,
                record.r3 + 0x78u,
                record.actor_collision_parts));
            break;
        case 0x803DF804u: // MR::initCollisionParts
            capture_route_marker_name_obj_name(
                address_space, record.r3, record.actor_name);
            capture_route_marker_guest_string(
                address_space, record.r4, record.collision_name);
            capture_route_marker_hit_sensor_host_name(
                address_space, record.r5, record.sensor_host_name);
            break;
        case 0x80175EA4u: // CollisionParts::init
            capture_route_marker_hit_sensor_host_name(
                address_space, record.r5, record.sensor_host_name);
            capture_route_marker_kcl_snapshot(
                address_space, record.r6, record.kcl);
            break;
        case 0x80183140u: // KCollisionServer::init
            capture_route_marker_kcl_snapshot(
                address_space, record.r4, record.kcl);
            break;
        case 0x803E1F00u: // MR::getFirstPolyOnLineToMap
            record.collision_origin_valid = try_read_guest_vec3(
                address_space, record.r5, record.collision_origin);
            record.collision_direction_valid = try_read_guest_vec3(
                address_space, record.r6, record.collision_direction);
            break;
        default:
            break;
    }
}

void log_route_marker_call(
    RuntimeState& state,
    RuntimeState::RouteMarkerSource source,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    observe_performance_mario_marker(state, guest_address, context);
    const bool mario_control_call =
        is_route_marker_mario_control_address(guest_address);
    const bool mario_control_observation =
        mario_control_call && !state.route_marker_first_mario_control_seen;
    const bool mario_control_candidate =
        mario_control_observation &&
        galaxy::input::opening_route_marker_boundary_eligible(
            source == RuntimeState::RouteMarkerSource::CallBoundary,
            guest_address, context.pc, context.lr);
    // Preserve the existing required-address-space failure. An unmapped or
    // malformed scene snapshot below instead leaves the one-shot gate armed.
    if (mario_control_observation && native_input_mario_control_marker_enabled() &&
        state.address_space == nullptr) {
        throw RuntimeFailure(
            "Mario-control input marker has no native guest address space");
    }
    const bool first_mario_control_call =
        mario_control_candidate && state.address_space != nullptr &&
        galaxy::input::opening_route_marker_after_prologue_eligible(
            [&](std::uint32_t address, std::span<std::uint8_t> destination) {
                // Called only at the existing simulation-thread marker before
                // exposure. No architectural load, timing call, guest callback,
                // worker scheduling or guest-state write occurs in this read.
                const auto* plain = state.address_space->pointer_or_null(
                    address, static_cast<std::uint32_t>(destination.size()));
                if (plain == nullptr) return false;
                std::memcpy(destination.data(), plain, destination.size());
                return true;
            }, context.gpr[3], context.gpr[1]);
    // The exact enabled updateBehavior caller additionally requires the
    // selected opening scene's completed registered prologue and Mario owner.
    // Earlier title, file selection and story calls leave startup buttons
    // armed. This functional input boundary still is not human control proof.
    // Publish the qualifying call boundary before the optional trace gate so
    // it can anchor the virtual device even when route logging is off.
    // Once that single boundary has published every consumer, remove only the
    // narrow generated-call flag. Broad route tracing remains independent.
    if (first_mario_control_call) {
        state.route_marker_first_mario_control_vi = state.vi_retrace_count;
        if (native_input_mario_control_marker_enabled()) {
            if (state.address_space == nullptr) {
                throw RuntimeFailure(
                    "Mario-control input marker has no native guest address space");
            }
            // Native HID scripts compare against deadline_ticks / VI period.
            // Use that exact absolute RuntimeTimeline domain here.
            // vi_retrace_count is relative to the later VI-cadence arm and
            // would shift the script by the entire pre-arm startup interval.
            const std::uint64_t input_timeline_vi =
                runtime_time_base_ticks(state) / kViRetracePeriodTicks;
            state.address_space->publish_native_input_first_mario_control_vi(
                input_timeline_vi);
        }
        // Publish the marker-timed input timeline before closing the one-shot
        // gate. Relative stick anchoring and button-script termination share
        // this exact handoff. needs_call_guest_intercept() and
        // branch_checkpoint() use the same simulation-thread state to avoid
        // all later host crossings.
        state.route_marker_first_mario_control_seen = true;
        if (state.services != nullptr) {
            state.services->runtime_flags &=
                ~galaxy::kNativeServiceFlagRelativeMarioInputAnchor;
        }
        // The runtime normally republishes this gate at each retrace. Offset
        // zero begins at the anchor boundary itself, so make the generated
        // marker gate agree immediately for the remainder of this VI.
        state.main_frame_trace_active.store(
            trace_main_frame_vi_window(state), std::memory_order_relaxed);

        if (state.address_space != nullptr &&
            (trace_route_markers_enabled() ||
             trace_main_frame_relative_to_mario_control_enabled())) {
            record_route_marker(
                state,
                RuntimeState::RouteMarkerKind::MarioControlReady,
                source,
                guest_address,
                context,
                0u,
                {},
                0.0f,
                0.0f,
                0.0f);
        }
    }
    const bool main_frame_relative_anchor =
        trace_main_frame_relative_to_mario_control_enabled() &&
        mario_control_call;
    if ((!trace_route_markers_enabled() && !main_frame_relative_anchor) ||
        (!is_route_marker_call_address(guest_address) &&
         !main_frame_relative_anchor) ||
        state.address_space == nullptr) {
        return;
    }

    if (is_route_marker_movie_address(guest_address)) {
        if (state.route_marker_movie_logs++ < 64u) {
            record_route_marker(
                state,
                RuntimeState::RouteMarkerKind::MovieActive,
                source,
                guest_address,
                context,
                0u,
                {},
                0.0f,
                0.0f,
                0.0f);
        }
        return;
    }

    if (is_route_marker_collision_address(guest_address)) {
        if (state.route_marker_collision_logs++ < 96u) {
            RuntimeState::RouteMarkerRecord* const record = record_route_marker(
                state,
                RuntimeState::RouteMarkerKind::Collision,
                source,
                guest_address,
                context,
                0u,
                {},
                0.0f,
                0.0f,
                0.0f);
            if (record != nullptr) {
                capture_route_marker_collision_snapshot(
                    *state.address_space, *record);
            }
        }
        return;
    }

    if (!is_route_marker_mario_address(guest_address)) {
        return;
    }

    // A relative main-frame trace needs only the first exact Mario-control
    // boundary.  Broad route tracing may continue sampling movement, but the
    // narrow anchor must not inherit that per-frame guest-memory work merely
    // because it shares this observation function.
    if (!trace_route_markers_enabled()) {
        return;
    }

    const auto& as = *state.address_space;
    const auto try_mario_self =
        [&](std::uint32_t self,
            std::array<float, 3>& pos,
            std::array<float, 3>& vel,
            std::array<float, 3>& prev) {
            if (self < 0x80000000u || self >= 0x94000000u ||
                as.pointer_or_null(self + 0x2A0u, 4u) == nullptr) {
                return false;
            }
            return try_read_guest_vec3(as, self + 0x0Cu, pos) &&
                   try_read_guest_vec3(as, self + 0x30u, vel) &&
                   try_read_guest_vec3(as, self + 0x294u, prev);
        };

    std::uint32_t self = context.gpr[3];
    std::array<float, 3> pos{};
    std::array<float, 3> vel{};
    std::array<float, 3> prev{};
    if (!try_mario_self(self, pos, vel, prev)) {
        self = context.gpr[31];
        if (!try_mario_self(self, pos, vel, prev)) {
            self = context.gpr[30];
            if (!try_mario_self(self, pos, vel, prev)) {
                return;
            }
        }
    }

    const float sample_delta2 =
        state.route_marker_mario_have_pos &&
                state.route_marker_mario_self == self
            ? vec3_delta2(pos, state.route_marker_mario_last_pos)
            : 0.0f;
    const float actor_delta2 = vec3_delta2(pos, prev);
    const float vel2 = vel[0] * vel[0] + vel[1] * vel[1] + vel[2] * vel[2];
    state.route_marker_mario_self = self;
    state.route_marker_mario_last_pos = pos;
    state.route_marker_mario_have_pos = true;
    if (state.route_marker_first_mario_vi == 0u) {
        state.route_marker_first_mario_vi = state.vi_retrace_count;
    }

    constexpr float kWalkingThreshold2 = 0.000001f;
    const bool moving =
        sample_delta2 > kWalkingThreshold2 ||
        actor_delta2 > kWalkingThreshold2 ||
        vel2 > kWalkingThreshold2;
    if (!moving || state.route_marker_mario_last_vi == state.vi_retrace_count ||
        state.route_marker_mario_logs >= 128u) {
        return;
    }
    state.route_marker_mario_last_vi = state.vi_retrace_count;
    ++state.route_marker_mario_logs;
    record_route_marker(
        state,
        RuntimeState::RouteMarkerKind::PlayableWalking,
        source,
        guest_address,
        context,
        self,
        pos,
        sample_delta2,
        actor_delta2,
        vel2);
}

void dump_route_marker_trace(RuntimeState& state, std::ostream& output) {
    if ((!trace_route_markers_enabled() &&
         !trace_main_frame_relative_to_mario_control_enabled()) ||
        state.route_marker_trace_dumped) {
        return;
    }
    state.route_marker_trace_dumped = true;

    const std::size_t count = std::min(
        state.route_marker_record_count, state.route_marker_records.size());
    for (std::size_t index = 0u; index < count; ++index) {
        const RuntimeState::RouteMarkerRecord& record =
            state.route_marker_records[index];
        const char* const label = main_frame_call_label(record.guest_address);
        const char* const source_label =
            record.source == RuntimeState::RouteMarkerSource::CallBoundary
                ? "call-boundary"
                : "checkpoint";
        switch (record.kind) {
            case RuntimeState::RouteMarkerKind::MovieActive:
                output << "[route-marker] kind=movie-active vi=" << record.vi
                       << " source=" << source_label
                       << " pc=" << hexadecimal(record.guest_address)
                       << " label=\""
                       << (label != nullptr ? label : "movie")
                       << "\" lr=" << hexadecimal(record.lr)
                       << " r3=" << hexadecimal(record.r3) << '\n';
                break;
            case RuntimeState::RouteMarkerKind::Collision: {
                output << "[route-marker] kind=collision vi=" << record.vi
                       << " source=" << source_label
                       << " pc=" << hexadecimal(record.guest_address)
                       << " label=\""
                       << (label != nullptr ? label : "collision")
                       << "\" lr=" << hexadecimal(record.lr)
                       << " r3=" << hexadecimal(record.r3)
                       << " r4=" << hexadecimal(record.r4)
                       << " r5=" << hexadecimal(record.r5);
                switch (record.guest_address) {
                    case 0x803EABE0u: // MR::isExistCollisionResource
                        if (record.actor_name[0] != '\0') {
                            output << " actor=\"" << record.actor_name.data()
                                   << "\"";
                        }
                        if (record.collision_name[0] != '\0') {
                            output << " collisionName=\""
                                   << record.collision_name.data() << "\"";
                        }
                        if (record.actor_collision_parts != 0u) {
                            output << " actorCollisionParts="
                                   << hexadecimal(record.actor_collision_parts);
                        }
                        break;
                    case 0x803DF804u: // MR::initCollisionParts
                        if (record.actor_name[0] != '\0') {
                            output << " actor=\"" << record.actor_name.data()
                                   << "\"";
                        }
                        if (record.collision_name[0] != '\0') {
                            output << " collisionName=\""
                                   << record.collision_name.data() << "\"";
                        }
                        if (record.sensor_host_name[0] != '\0') {
                            output << " sensorHost=\""
                                   << record.sensor_host_name.data() << "\"";
                        }
                        output << " mtx=" << hexadecimal(record.r6);
                        break;
                    case 0x80175EA4u: // CollisionParts::init
                        if (record.sensor_host_name[0] != '\0') {
                            output << " sensorHost=\""
                                   << record.sensor_host_name.data() << "\"";
                        }
                        output << " parts=" << hexadecimal(record.r3)
                               << " sensor=" << hexadecimal(record.r5)
                               << " mapInfo=" << hexadecimal(record.r7)
                               << " keeper=" << record.r8;
                        append_route_marker_kcl_snapshot(output, record.kcl);
                        break;
                    case 0x80183140u: // KCollisionServer::init
                        output << " server=" << hexadecimal(record.r3)
                               << " mapData=" << hexadecimal(record.r5);
                        append_route_marker_kcl_snapshot(output, record.kcl);
                        break;
                    case 0x803E1F00u: // MR::getFirstPolyOnLineToMap
                        if (record.collision_origin_valid) {
                            output << " origin=(" << record.collision_origin[0]
                                   << ',' << record.collision_origin[1] << ','
                                   << record.collision_origin[2] << ')';
                        }
                        if (record.collision_direction_valid) {
                            output << " direction=("
                                   << record.collision_direction[0] << ','
                                   << record.collision_direction[1] << ','
                                   << record.collision_direction[2] << ')';
                        }
                        break;
                    default:
                        break;
                }
                output << '\n';
                break;
            }
            case RuntimeState::RouteMarkerKind::MarioControlReady:
                output << "[route-marker] kind=mario-control-ready vi="
                       << record.vi
                       << " source=" << source_label
                       << " pc=" << hexadecimal(record.guest_address)
                       << " label=\""
                       << (label != nullptr ? label : "MarioActor")
                       << "\" lr=" << hexadecimal(record.lr)
                       << " r3=" << hexadecimal(record.r3)
                       << " r31=" << hexadecimal(record.r31)
                       << " r30=" << hexadecimal(record.r30)
                       << " input-timeline-vi=" << record.input_timeline_vi << '\n';
                break;
            case RuntimeState::RouteMarkerKind::PlayableWalking:
                output << "[route-marker] kind=playable-walking vi="
                       << record.vi
                       << " source=" << source_label
                       << " pc=" << hexadecimal(record.guest_address)
                       << " label=\""
                       << (label != nullptr ? label : "MarioActor")
                       << "\" lr=" << hexadecimal(record.lr)
                       << " self=" << hexadecimal(record.mario_self)
                       << " sampleDelta2=" << record.sample_delta2
                       << " actorDelta2=" << record.actor_delta2
                       << " vel2=" << record.velocity2
                       << " pos=" << record.mario_pos[0] << ','
                       << record.mario_pos[1] << ',' << record.mario_pos[2]
                       << " input-timeline-vi=" << record.input_timeline_vi << '\n';
                break;
        }
    }
}

void log_suspicious_message_sleep(
    RuntimeState& state,
    const galaxy::PpcContext& context,
    std::uint32_t queue) {
    if (!trace_suspicious_message_mq()) {
        return;
    }
    constexpr std::uint32_t kReceiveStart = 0x804A89ACu;
    constexpr std::uint32_t kReceiveEnd = 0x804A8A88u;
    if (state.address_space == nullptr ||
        context.lr < kReceiveStart ||
        context.lr >= kReceiveEnd ||
        queue < 0x90000008u || queue >= 0x94000000u) {
        return;
    }

    static std::uint32_t s_logs = 0;
    if (s_logs++ >= 16u) {
        return;
    }

    const auto& address_space = *state.address_space;
    const auto valid_ram = [](std::uint32_t address) {
        return (address >= 0x80000000u && address < 0x81800000u) ||
               (address >= 0x90000000u && address < 0x94000000u);
    };
    const auto dump_words =
        [&](const char* label, std::uint32_t base, std::uint32_t bytes) {
            std::cout << "[suspicious-mq] " << label << "="
                      << hexadecimal(base) << ':';
            if (!valid_ram(base) ||
                address_space.pointer_or_null(base, bytes) == nullptr) {
                std::cout << " unresolved\n";
                return;
            }
            for (std::uint32_t off = 0; off < bytes; off += 4u) {
                std::cout << ' '
                          << hexadecimal(address_space.read_u32(base + off));
            }
            std::cout << '\n';
        };

    const std::uint32_t message_queue = queue - 8u;
    std::cout << "[suspicious-mq] #" << s_logs
              << " vi=" << state.vi_retrace_count
              << " q=" << hexadecimal(queue)
              << " mq=" << hexadecimal(message_queue)
              << " pc=" << hexadecimal(context.pc)
              << " lr=" << hexadecimal(context.lr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " r3=" << hexadecimal(context.gpr[3])
              << " r4=" << hexadecimal(context.gpr[4])
              << " r5=" << hexadecimal(context.gpr[5])
              << " r6=" << hexadecimal(context.gpr[6])
              << " r7=" << hexadecimal(context.gpr[7])
              << " r8=" << hexadecimal(context.gpr[8]);
    if (address_space.pointer_or_null(0x800000D4u, 0x14u) != nullptr) {
        std::cout << " ctx=" << hexadecimal(address_space.read_u32(0x800000D4u))
                  << " thr=" << hexadecimal(address_space.read_u32(0x800000E4u))
                  << " runbits="
                  << hexadecimal(address_space.read_u32(0x806A2D30u));
    }
    std::cout << '\n';
    dump_words("mq-0x20", message_queue - 0x20u, 0x70u);
    dump_words("stack", context.gpr[1], 0x80u);
    const std::uint32_t current_thread = address_space.read_u32(0x800000E4u);
    if (valid_ram(current_thread)) {
        dump_words("thread", current_thread, 0x80u);
        dump_words("thread+0x2b0", current_thread + 0x2B0u, 0x60u);
    }
    std::cout << "[suspicious-mq] recent calls:";
    state.print_recent_reverse(std::cout, 24);
    std::cout << '\n';
}

void dump_guest_thread_roster(
    const RuntimeState& state,
    std::ostream& out,
    const char* reason,
    std::uint32_t queue,
    std::uint32_t lr) {
    if (state.address_space == nullptr) {
        return;
    }

    const auto& address_space = *state.address_space;
    constexpr std::uint32_t kActiveThreadQueueHead = 0x800000DCu;
    constexpr std::uint32_t kCurrentContextAddress = 0x800000D4u;
    constexpr std::uint32_t kCurrentThreadAddress = 0x800000E4u;
    constexpr std::uint32_t kRunQueueBitsAddress = 0x806A2D30u;
    constexpr std::uint32_t kThreadStateOffset = 0x2C8u;
    constexpr std::uint32_t kThreadSuspendOffset = 0x2CCu;
    constexpr std::uint32_t kThreadPriorityOffset = 0x2D0u;
    constexpr std::uint32_t kThreadQueueOffset = 0x2DCu;
    constexpr std::uint32_t kThreadActiveNextOffset = 0x2FCu;
    constexpr std::uint32_t kThreadSrr0Offset = 0x198u;
    constexpr std::uint32_t kThreadLrOffset = 0x84u;
    constexpr std::uint32_t kThreadStackPointerOffset = 0x04u;

    const auto valid_thread = [](std::uint32_t address) {
        return address >= 0x80000000u && address < 0x81800000u;
    };

    out << "[thread-roster] reason=" << (reason != nullptr ? reason : "trace")
        << " vi=" << state.vi_retrace_count
        << " queue=" << hexadecimal(queue)
        << " lr=" << hexadecimal(lr)
        << " currentCtx="
        << hexadecimal(address_space.read_u32(kCurrentContextAddress))
        << " currentThread="
        << hexadecimal(address_space.read_u32(kCurrentThreadAddress))
        << " runbits="
        << hexadecimal(address_space.read_u32(kRunQueueBitsAddress))
        << '\n';

    std::uint32_t thread = address_space.read_u32(kActiveThreadQueueHead);
    for (int i = 0; i < 32 && valid_thread(thread); ++i) {
        const std::uint32_t state_word =
            address_space.read_u32(thread + kThreadStateOffset);
        const std::uint32_t queue_ptr =
            address_space.read_u32(thread + kThreadQueueOffset);
        const std::uint32_t srr0 =
            address_space.read_u32(thread + kThreadSrr0Offset);
        const std::uint32_t thread_lr =
            address_space.read_u32(thread + kThreadLrOffset);
        out << "[thread-roster]   t=" << hexadecimal(thread)
            << " state=" << (state_word >> 16)
            << " suspend="
            << static_cast<std::int32_t>(
                   address_space.read_u32(thread + kThreadSuspendOffset))
            << " prio="
            << address_space.read_u32(thread + kThreadPriorityOffset)
            << " queue=" << hexadecimal(queue_ptr)
            << " srr0=" << hexadecimal(srr0)
            << " lr=" << hexadecimal(thread_lr);
        // Diagnostic: if this thread is parked on an OSMessageQueue receive
        // wait-queue (queue_ptr == &mq->queueReceive == mq + 0x08), dump the
        // queue's message accounting so we can tell a lost-wakeup (used>0 while
        // parked) from a never-posted producer (used==0). Offsets are the
        // libogc OSMessageQueue layout: msgCount +0x14, firstIndex +0x18,
        // usedCount +0x1C relative to the queue base.
        if (valid_thread(queue_ptr) && queue_ptr >= 0x80000008u) {
            const std::uint32_t mq = queue_ptr - 0x08u;
            const std::uint32_t msg_count = address_space.read_u32(mq + 0x14u);
            const std::uint32_t used_count = address_space.read_u32(mq + 0x1Cu);
            const std::uint32_t first_index = address_space.read_u32(mq + 0x18u);
            if (msg_count != 0u && msg_count < 0x10000u) {
                out << " mq=" << hexadecimal(mq)
                    << " mq-msgCount=" << msg_count
                    << " mq-usedCount=" << used_count
                    << " mq-firstIndex=" << first_index;
            }
        }
        out << '\n';

        std::uint32_t sp =
            address_space.read_u32(thread + kThreadStackPointerOffset);
        out << "[thread-roster]     bt:";
        for (int f = 0; f < 8 && sp >= 0x80000000u && sp < 0x81800000u; ++f) {
            const std::uint32_t saved_lr = address_space.read_u32(sp + 0x04u);
            if (saved_lr >= 0x80004000u && saved_lr < 0x80530000u) {
                out << ' ' << hexadecimal(saved_lr);
            }
            const std::uint32_t up = address_space.read_u32(sp);
            if (up <= sp) {
                break;
            }
            sp = up;
        }
        out << '\n';

        const std::uint32_t next =
            address_space.read_u32(thread + kThreadActiveNextOffset);
        if (next == thread) {
            break;
        }
        thread = next;
    }
}

bool looks_like_guest_message_queue(
    const galaxy::host::GuestAddressSpace& address_space,
    std::uint32_t mq) {
    constexpr std::uint32_t kMessageArrayOffset = 0x10u;
    constexpr std::uint32_t kMessageCountOffset = 0x14u;
    constexpr std::uint32_t kFirstIndexOffset = 0x18u;
    constexpr std::uint32_t kUsedCountOffset = 0x1Cu;
    if (address_space.pointer_or_null(mq, 0x20u) == nullptr) {
        return false;
    }
    const std::uint32_t message_array =
        address_space.read_u32(mq + kMessageArrayOffset);
    const std::uint32_t message_count =
        address_space.read_u32(mq + kMessageCountOffset);
    const std::uint32_t first_index =
        address_space.read_u32(mq + kFirstIndexOffset);
    const std::uint32_t used_count =
        address_space.read_u32(mq + kUsedCountOffset);
    return message_count != 0u && message_count < 0x10000u &&
           first_index < message_count &&
           used_count <= message_count &&
           address_space.pointer_or_null(message_array, 4u) != nullptr;
}

std::uint32_t infer_message_queue_from_context(
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext* context) {
    if (context == nullptr) {
        return 0;
    }
    const std::array<std::uint32_t, 10> candidates{
        context->gpr[31],
        context->gpr[30],
        context->gpr[29],
        context->gpr[28],
        context->gpr[27],
        context->gpr[3],
        context->gpr[4],
        context->gpr[5],
        context->gpr[6],
        context->gpr[7],
    };
    for (const std::uint32_t candidate : candidates) {
        if (looks_like_guest_message_queue(address_space, candidate)) {
            return candidate;
        }
        if (candidate >= 8u &&
            looks_like_guest_message_queue(address_space, candidate - 8u)) {
            return candidate - 8u;
        }
    }
    return 0;
}

bool current_ipc_reply_is_dvd_low_read(RuntimeState& state) {
    if (state.address_space == nullptr) {
        g_main_thread.state = ThreadState::Running;
        return true;
    }

    constexpr std::uint32_t kIosReplyCommand = 8u;
    constexpr std::uint32_t kIosIoctlCommand = 6u;
    constexpr std::uint32_t kIosIoctlvCommand = 7u;
    constexpr std::uint32_t kDiRead = 0x71u;

    const auto snapshot = state.address_space->ipc_debug_snapshot();
    const std::uint32_t request = snapshot.current_reply;
    if (request == 0u ||
        state.address_space->pointer_or_null(request, 0x10u) == nullptr) {
        return false;
    }

    const std::uint32_t command = state.address_space->read_u32(request + 0x00u);
    const std::uint32_t original_command =
        state.address_space->read_u32(request + 0x08u);
    const std::uint32_t ioctl = state.address_space->read_u32(request + 0x0Cu);
    return command == kIosReplyCommand &&
           (original_command == kIosIoctlCommand ||
            original_command == kIosIoctlvCommand) &&
           ioctl == kDiRead;
}

bool current_ipc_reply_is_acked_before_irq_clear(RuntimeState& state) {
    if (state.address_space == nullptr) {
        g_main_thread.state = ThreadState::Running;
        return true;
    }
    const auto snapshot = state.address_space->ipc_debug_snapshot();
    return snapshot.latched_reply_acked &&
           snapshot.latched_reply != 0u &&
           snapshot.latched_reply == snapshot.current_reply;
}

std::uint32_t resolve_message_queue_hint(
    const galaxy::host::GuestAddressSpace& address_space,
    const galaxy::PpcContext* context,
    std::uint32_t hint) {
    if (hint != 0u) {
        if (looks_like_guest_message_queue(address_space, hint)) {
            return hint;
        }
        if (hint >= 8u &&
            looks_like_guest_message_queue(address_space, hint - 8u)) {
            return hint - 8u;
        }
    }
    return infer_message_queue_from_context(address_space, context);
}

void dump_ipc_request_summary(
    const galaxy::host::GuestAddressSpace& address_space,
    std::ostream& out,
    const char* label,
    std::uint32_t request) {
    constexpr std::uint32_t kIosRequestCommandOffset = 0x00u;
    constexpr std::uint32_t kIosRequestStatusOffset = 0x04u;
    constexpr std::uint32_t kIosRequestHandleOffset = 0x08u;
    constexpr std::uint32_t kIosRequestArgumentsOffset = 0x0Cu;
    constexpr std::uint32_t kIosRpcCallbackOffset = 0x20u;
    constexpr std::uint32_t kIosRpcCallbackArgumentOffset = 0x24u;
    out << "[race-probe]   " << label << '=' << hexadecimal(request);
    if (request == 0u) {
        out << " empty\n";
        return;
    }
    if (address_space.pointer_or_null(request, 0x28u) == nullptr) {
        out << " unmapped\n";
        return;
    }
    out << " cmd="
        << address_space.read_u32(request + kIosRequestCommandOffset)
        << " status="
        << hexadecimal(address_space.read_u32(request + kIosRequestStatusOffset))
        << " handle="
        << address_space.read_u32(request + kIosRequestHandleOffset)
        << " arg0="
        << hexadecimal(address_space.read_u32(
               request + kIosRequestArgumentsOffset))
        << " arg1="
        << hexadecimal(address_space.read_u32(
               request + kIosRequestArgumentsOffset + 4u))
        << " cb="
        << hexadecimal(address_space.read_u32(request + kIosRpcCallbackOffset))
        << " cb-arg="
        << hexadecimal(address_space.read_u32(
               request + kIosRpcCallbackArgumentOffset))
        << '\n';
}

void dump_message_queue_summary(
    const galaxy::host::GuestAddressSpace& address_space,
    std::ostream& out,
    std::uint32_t mq) {
    constexpr std::uint32_t kQueueSendOffset = 0x00u;
    constexpr std::uint32_t kQueueReceiveOffset = 0x08u;
    constexpr std::uint32_t kMessageArrayOffset = 0x10u;
    constexpr std::uint32_t kMessageCountOffset = 0x14u;
    constexpr std::uint32_t kFirstIndexOffset = 0x18u;
    constexpr std::uint32_t kUsedCountOffset = 0x1Cu;
    if (mq == 0u) {
        out << "[race-probe]   mq=unresolved\n";
        return;
    }
    out << "[race-probe]   mq=" << hexadecimal(mq);
    if (address_space.pointer_or_null(mq, 0x20u) == nullptr) {
        out << " unmapped\n";
        return;
    }
    const std::uint32_t message_array =
        address_space.read_u32(mq + kMessageArrayOffset);
    const std::uint32_t message_count =
        address_space.read_u32(mq + kMessageCountOffset);
    const std::uint32_t first_index =
        address_space.read_u32(mq + kFirstIndexOffset);
    const std::uint32_t used_count =
        address_space.read_u32(mq + kUsedCountOffset);
    out << " sendQ=" << hexadecimal(address_space.read_u32(mq + kQueueSendOffset))
        << " recvQ="
        << hexadecimal(address_space.read_u32(mq + kQueueReceiveOffset))
        << " msgArray=" << hexadecimal(message_array)
        << " msgCount=" << message_count
        << " first=" << first_index
        << " used=" << used_count;
    if (message_count != 0u && message_count < 0x10000u &&
        used_count != 0u &&
        address_space.pointer_or_null(message_array, message_count * 4u) !=
            nullptr) {
        const std::uint32_t slot = first_index % message_count;
        out << " nextMsg="
            << hexadecimal(address_space.read_u32(message_array + slot * 4u));
    }
    out << '\n';
}

void record_jutvideo_mq_entry(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext* context,
    std::uint32_t caller_lr) {
    if (!trace_jutvideo_mq() || state.address_space == nullptr) {
        return;
    }
    // This diagnostic is intentionally windowed before it looks at the guest
    // queue.  JUTVideo's helpers run every frame; retaining a selected window
    // in memory keeps console I/O outside the real-time guest path.
    static const std::uint64_t s_jut_mq_start_vi =
        read_env_u64("GALAXY_TRACE_JUTVIDEO_MQ_START_VI", 0u);
    static const std::uint64_t s_jut_mq_end_vi =
        read_env_u64("GALAXY_TRACE_JUTVIDEO_MQ_END_VI", 0u);
    if (state.vi_retrace_count < s_jut_mq_start_vi ||
        (s_jut_mq_end_vi != 0u &&
         state.vi_retrace_count > s_jut_mq_end_vi)) {
        return;
    }
    if (guest_address != 0x80419554u &&
        guest_address != 0x804A88E4u &&
        guest_address != 0x804A89ACu &&
        guest_address != 0x804A8A88u) {
        return;
    }

    auto& address_space = *state.address_space;
    constexpr std::uint32_t kJutVideoManagerPtr = 0x806A2850u;
    constexpr std::uint32_t kJutVideoMessageQueueOffset = 0x38u;
    constexpr std::uint32_t kFallbackJutVideoMq = 0x809AE098u;
    constexpr std::uint32_t kMessageArrayOffset = 0x10u;
    constexpr std::uint32_t kMessageCountOffset = 0x14u;
    constexpr std::uint32_t kFirstIndexOffset = 0x18u;
    constexpr std::uint32_t kUsedCountOffset = 0x1Cu;

    std::uint32_t expected_mq = kFallbackJutVideoMq;
    if (address_space.pointer_or_null(kJutVideoManagerPtr, 4u) != nullptr) {
        const std::uint32_t manager =
            address_space.read_u32(kJutVideoManagerPtr);
        if (manager >= 0x80000000u && manager < 0x94000000u) {
            expected_mq = manager + kJutVideoMessageQueueOffset;
        }
    }
    const std::uint32_t mq = context != nullptr ? context->gpr[3] : expected_mq;
    if (context != nullptr && mq != expected_mq && mq != kFallbackJutVideoMq) {
        return;
    }

    const std::size_t capacity = jutvideo_mq_trace_capacity();
    RuntimeState::JutVideoMqRecord& record = state.jutvideo_mq_records[
        state.jutvideo_mq_record_count % capacity];
    record = {};
    record.vi = state.vi_retrace_count;
    const auto now = std::chrono::steady_clock::now();
    const auto elapsed_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
                                now.time_since_epoch())
                                .count();
    record.host_time_ns = elapsed_ns > 0
        ? static_cast<std::uint64_t>(elapsed_ns)
        : 0u;
    record.guest_address = guest_address;
    record.caller_lr = caller_lr != 0u
        ? caller_lr
        : (context != nullptr ? context->lr : 0u);
    record.message_queue = mq;
    record.current_context =
        address_space.pointer_or_null(0x800000D4u, 4u) != nullptr
            ? address_space.read_u32(0x800000D4u)
            : 0u;
    record.current_thread =
        address_space.pointer_or_null(0x800000E4u, 4u) != nullptr
            ? address_space.read_u32(0x800000E4u)
            : 0u;
    if (address_space.pointer_or_null(mq, 0x20u) != nullptr) {
        const std::uint32_t message_array =
            address_space.read_u32(mq + kMessageArrayOffset);
        record.message_count =
            address_space.read_u32(mq + kMessageCountOffset);
        record.first_index =
            address_space.read_u32(mq + kFirstIndexOffset);
        record.used_count = address_space.read_u32(mq + kUsedCountOffset);
        if (record.message_count != 0u &&
            record.message_count < 0x10000u &&
            record.used_count != 0u &&
            address_space.pointer_or_null(
                message_array, record.message_count * 4u) != nullptr) {
            const std::uint32_t slot =
                record.first_index % record.message_count;
            record.next_message =
                address_space.read_u32(message_array + slot * 4u);
        }
    }
    ++state.jutvideo_mq_record_count;
}

void log_jutvideo_mq_call(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    record_jutvideo_mq_entry(state, guest_address, &context, context.lr);
}

void log_archive_mq_call(
    RuntimeState& state,
    std::uint32_t guest_address,
    const galaxy::PpcContext& context) {
    static const bool trace_archive_mq =
        read_env_flag("GALAXY_TRACE_ARCHIVE_MQ", false);
    if (!trace_archive_mq || state.address_space == nullptr) {
        return;
    }
    if (guest_address != 0x804A88E4u &&
        guest_address != 0x804A89ACu &&
        guest_address != 0x804A8A88u) {
        return;
    }

    const std::uint32_t mq = context.gpr[3];
    const bool archive_dispatch_mq = mq == 0x805F85F0u;
    const bool archive_request_mq =
        mq >= 0x806F0000u && mq < 0x80710000u &&
        looks_like_guest_message_queue(*state.address_space, mq);
    const bool archive_callsite =
        context.lr == 0x8040EE60u || context.lr == 0x8040ED8Cu ||
        context.lr == 0x8040EEA8u || context.lr == 0x8040EED4u ||
        context.lr == 0x8040EB94u || context.lr == 0x804132FCu;
    if (!archive_dispatch_mq && !archive_request_mq && !archive_callsite) {
        return;
    }

    static std::uint64_t s_archive_mq_logs = 0;
    ++s_archive_mq_logs;
    const std::uint64_t cap =
        read_env_u64("GALAXY_TRACE_ARCHIVE_MQ_CAP", 2048u);
    if (s_archive_mq_logs > cap && (s_archive_mq_logs % 512u) != 0u) {
        return;
    }

    const char* op = guest_address == 0x804A88E4u
        ? "send"
        : (guest_address == 0x804A8A88u ? "jam" : "recv");
    const std::uint32_t current_context =
        state.address_space->read_u32(0x800000D4u);
    const std::uint32_t current_thread =
        state.address_space->read_u32(0x800000E4u);
    const std::uint32_t runbits =
        state.address_space->read_u32(0x806A2D30u);

    std::cerr << "[archive-mq] #" << s_archive_mq_logs
              << " op=" << op
              << " vi=" << state.vi_retrace_count
              << " mq=" << hexadecimal(mq)
              << " msg=" << hexadecimal(context.gpr[4])
              << " flags=" << hexadecimal(context.gpr[5])
              << " lr=" << hexadecimal(context.lr)
              << " pc=" << hexadecimal(context.pc)
              << " curCtx=" << hexadecimal(current_context)
              << " curThr=" << hexadecimal(current_thread)
              << " runbits=" << hexadecimal(runbits);
    if (looks_like_guest_message_queue(*state.address_space, mq)) {
        std::cerr << ' ';
        dump_message_queue_summary(*state.address_space, std::cerr, mq);
    } else {
        std::cerr << " mq-summary=unavailable\n";
    }
}

void log_usb_callback_context(
    RuntimeState& state,
    const galaxy::PpcContext& context,
    std::uint32_t target,
    const char* reason) {
    if (!trace_usb_callback_context() || state.address_space == nullptr) {
        return;
    }

    static std::uint64_t s_usb_callback_logs = 0;
    ++s_usb_callback_logs;
    static const std::uint64_t s_usb_callback_cap =
        read_env_u64("GALAXY_TRACE_USB_CALLBACK_CONTEXT_CAP", 128u);
    if (s_usb_callback_logs > s_usb_callback_cap) {
        return;
    }

    auto& address_space = *state.address_space;
    const auto safe_u32 = [&](std::uint32_t address) -> std::uint32_t {
        return address_space.pointer_or_null(address, 4u) != nullptr
            ? address_space.read_u32(address)
            : 0u;
    };
    const auto dump_words =
        [&](const char* label, std::uint32_t address, std::uint32_t bytes) {
        std::cerr << "\n[usb-callback]   " << label << '='
                  << hexadecimal(address);
        if (address_space.pointer_or_null(address, bytes) == nullptr) {
            std::cerr << " unmapped";
            return;
        }
        for (std::uint32_t offset = 0; offset < bytes; offset += 4u) {
            std::cerr << " +" << std::hex << offset << '='
                      << hexadecimal(address_space.read_u32(address + offset))
                      << std::dec;
        }
    };

    std::cerr << "[usb-callback] #" << s_usb_callback_logs
              << " reason=" << (reason != nullptr ? reason : "?")
              << " vi=" << state.vi_retrace_count
              << " target=" << hexadecimal(target)
              << " pc=" << hexadecimal(context.pc)
              << " lr=" << hexadecimal(context.lr)
              << " ctr=" << hexadecimal(context.ctr)
              << " r1=" << hexadecimal(context.gpr[1])
              << " r3=" << hexadecimal(context.gpr[3])
              << " r4=" << hexadecimal(context.gpr[4])
              << " r5=" << hexadecimal(context.gpr[5])
              << " r6=" << hexadecimal(context.gpr[6])
              << " r7=" << hexadecimal(context.gpr[7])
              << " r26=" << hexadecimal(context.gpr[26])
              << " r27=" << hexadecimal(context.gpr[27])
              << " r30=" << hexadecimal(context.gpr[30])
              << " r31=" << hexadecimal(context.gpr[31])
              << " curCtx=" << hexadecimal(safe_u32(0x800000D4u))
              << " curThr=" << hexadecimal(safe_u32(0x800000E4u))
              << " runbits=" << hexadecimal(safe_u32(0x806A2D30u))
              << " live=" << format_context_stack(g_live_ctx_stack)
              << " active=" << format_context_stack(g_active_nested_ctx_stack);
    dump_words("iusb-r27", context.gpr[27], 0x40u);
    dump_words("gpr30", context.gpr[30], 0x40u);
    dump_words("target", target, 0x20u);
    std::cerr << '\n';
}

void log_native_dsp_race_probe(
    RuntimeState& state,
    const char* site,
    std::uint32_t guest_pc,
    const galaxy::PpcContext* context,
    std::uint32_t queue_hint) {
    if (!trace_native_dsp_race_active(state) || state.address_space == nullptr) {
        return;
    }

    static std::uint64_t s_probe_count = 0;
    const std::uint64_t probe = ++s_probe_count;
    static const std::uint64_t log_limit =
        read_env_u64("GALAXY_TRACE_NATIVE_DSP_RACE_LIMIT", 96u);
    static const std::uint64_t log_period =
        read_env_u64("GALAXY_TRACE_NATIVE_DSP_RACE_PERIOD", 4096u);
    const bool initial_log = log_limit == 0u || probe <= log_limit;
    const bool periodic_log =
        log_period != 0u && (probe % log_period) == 0u;
    if (!initial_log && !periodic_log) {
        return;
    }

    const auto& address_space = *state.address_space;
    const galaxy::host::IpcDebugSnapshot ipc =
        address_space.ipc_debug_snapshot();
    const galaxy::host::DspDebugSnapshot dsp =
        address_space.dsp_debug_snapshot();
    const std::uint32_t current_context =
        read_guest_u32_or_zero(address_space, 0x800000D4u);
    const std::uint32_t current_thread =
        read_guest_u32_or_zero(address_space, 0x800000E4u);
    const std::uint32_t run_queue_bits =
        read_guest_u32_or_zero(address_space, 0x806A2D30u);
    const std::uint32_t mailbox_ack =
        read_guest_u32_or_zero(address_space, 0x8069E390u);
    const std::uint32_t mq =
        resolve_message_queue_hint(address_space, context, queue_hint);

    std::cerr << "[race-probe] #" << probe
              << " site=" << (site != nullptr ? site : "unknown")
              << " vi=" << state.vi_retrace_count
              << " checkpoint=" << state.checkpoint_count
              << " call=" << state.call_count
              << " guest=" << hexadecimal(guest_pc)
              << " pc="
              << hexadecimal(context != nullptr ? context->pc : 0u)
              << " lr="
              << hexadecimal(context != nullptr ? context->lr : 0u)
              << " msr="
              << hexadecimal(context != nullptr ? context->msr : 0u)
              << " ee="
              << (context != nullptr &&
                          (context->msr & kMsrExternalInterruptEnable) != 0u
                      ? 1
                      : 0)
              << " r1="
              << hexadecimal(context != nullptr ? context->gpr[1] : 0u)
              << " r3="
              << hexadecimal(context != nullptr ? context->gpr[3] : 0u)
              << " r4="
              << hexadecimal(context != nullptr ? context->gpr[4] : 0u)
              << " r5="
              << hexadecimal(context != nullptr ? context->gpr[5] : 0u)
              << " r6="
              << hexadecimal(context != nullptr ? context->gpr[6] : 0u)
              << " r13="
              << hexadecimal(context != nullptr ? context->gpr[13] : 0u)
              << " ctx=" << hexadecimal(current_context)
              << " thread=" << hexadecimal(current_thread)
              << " runbits=" << hexadecimal(run_queue_bits)
              << " mailboxAck=" << hexadecimal(mailbox_ack)
              << " ppcmsg=" << hexadecimal(ipc.ppc_message)
              << " ppcctrl=" << hexadecimal(ipc.ppc_control)
              << " armmsg=" << hexadecimal(ipc.arm_message)
              << " ipc-pending=" << (ipc.interrupt_pending ? 1 : 0)
              << " ipc-replies=" << ipc.pending_reply_count
              << " ipc-next=" << hexadecimal(ipc.next_pending_reply)
              << " dsp-native=" << (dsp.native_dsp_running ? 1 : 0)
              << " dsp-irq=" << (dsp.dsp_interrupt_pending ? 1 : 0)
              << " dsp-from=" << hexadecimal(dsp.from_mail_raw)
              << " dsp-from-ready=" << (dsp.from_mail_ready ? 1 : 0)
              << " dsp-native-present="
              << (dsp.native_from_mail_present ? 1 : 0)
              << " dsp-native-staged="
              << (dsp.native_from_mail_staged ? 1 : 0)
              << " dsp-native-irq-latched="
              << (dsp.native_from_mail_irq_latched ? 1 : 0)
              << " dsp-to-high=0x" << std::hex << dsp.to_mail_high
              << " dsp-to-low=0x" << dsp.to_mail_low
              << std::dec << '\n';

    dump_ipc_request_summary(address_space, std::cerr, "ppcmsg", ipc.ppc_message);
    dump_ipc_request_summary(address_space, std::cerr, "armmsg", ipc.arm_message);
    if (ipc.next_pending_reply != 0u &&
        ipc.next_pending_reply != ipc.arm_message) {
        dump_ipc_request_summary(
            address_space, std::cerr, "queued-reply", ipc.next_pending_reply);
    }
    dump_message_queue_summary(address_space, std::cerr, mq);

    static std::uint64_t s_roster_dumps = 0;
    static const std::uint64_t roster_limit =
        read_env_u64("GALAXY_TRACE_NATIVE_DSP_RACE_ROSTER_LIMIT", 8u);
    if (roster_limit == 0u || s_roster_dumps < roster_limit) {
        ++s_roster_dumps;
        dump_guest_thread_roster(
            state,
            std::cerr,
            site != nullptr ? site : "native-dsp-race",
            mq,
            context != nullptr ? context->lr : 0u);
    }
}

void log_xfb_state(RuntimeState& state, const char* phase) {
    if (!trace_xfb_state_enabled() || state.address_space == nullptr) {
        return;
    }
    static const std::uint64_t start =
        read_env_u64("GALAXY_TRACE_XFB_STATE_START_VI", 0);
    static const std::uint64_t end =
        read_env_u64("GALAXY_TRACE_XFB_STATE_END_VI", 0);
    if (state.vi_retrace_count < start ||
        (end != 0 && state.vi_retrace_count > end)) {
        return;
    }

    const auto& address_space = *state.address_space;
    constexpr std::uint32_t kJutVideoDrawDoneFlag = 0x806A2EF8u;
    // RMGE01's SDA base is 0x806A4CA0.  These are the exact globals used by
    // MainLoop::waitForRetrace (0x803A0778) and VIGetRetraceCount
    // (0x804B38F0), verified against the generated AOT body and retail DOL.
    constexpr std::uint32_t kViRetraceCounter = 0x806A2E84u;
    constexpr std::uint32_t kMainLoopWaitTarget = 0x806A2508u;
    constexpr std::uint32_t kMainLoopWaitInitialized = 0x806A250Cu;
    constexpr std::uint32_t kJutVideoManagerPtr = 0x806A2850u;
    constexpr std::uint32_t kJutVideoMessageQueueOffset = 0x38u;
    constexpr std::uint32_t kMessageQueueArrayOffset = 0x10u;
    constexpr std::uint32_t kMessageQueueCountOffset = 0x14u;
    constexpr std::uint32_t kMessageQueueFirstOffset = 0x18u;
    constexpr std::uint32_t kMessageQueueUsedOffset = 0x1Cu;
    constexpr std::uint32_t kJutXfbManagerPtr = 0x806A2868u;
    constexpr std::uint32_t kMainLoopFrameworkManagerPtr = 0x806A2500u;

    const std::uint32_t xfb = address_space.read_u32(kJutXfbManagerPtr);
    const std::uint32_t framework =
        address_space.read_u32(kMainLoopFrameworkManagerPtr);
    RuntimeState::XfbStateRecord& record = state.xfb_state_records[
        state.xfb_state_record_count % state.xfb_state_records.size()];
    record = {};
    record.vi = state.vi_retrace_count;
    record.copy_serial = galaxy::gx::xfb_copy_count();
    record.causal_render_frame =
        galaxy::gx::xfb_causal_trace_frame_index();
    record.phase = phase;
    record.draw_done = read_guest_u8(address_space, kJutVideoDrawDoneFlag);
    record.pe_token_pending = address_space.pe_token_pending();
    record.pe_finish_pending = address_space.pe_finish_pending();
    record.vi_retrace_counter = address_space.read_u32(kViRetraceCounter);
    record.main_loop_wait_target =
        address_space.read_u32(kMainLoopWaitTarget);
    record.main_loop_wait_initialized =
        read_guest_u8(address_space, kMainLoopWaitInitialized);
    record.jut_video = address_space.read_u32(kJutVideoManagerPtr);
    record.jut_video_valid =
        address_space.pointer_or_null(record.jut_video, 0x3Cu) != nullptr;
    if (record.jut_video_valid) {
        record.jut_queue = record.jut_video + kJutVideoMessageQueueOffset;
        record.jut_queue_valid =
            address_space.pointer_or_null(
                record.jut_queue, kMessageQueueUsedOffset + 4u) != nullptr;
        if (record.jut_queue_valid) {
            record.jut_queue_count = address_space.read_u32(
                record.jut_queue + kMessageQueueCountOffset);
            record.jut_queue_first = address_space.read_u32(
                record.jut_queue + kMessageQueueFirstOffset);
            record.jut_queue_used = address_space.read_u32(
                record.jut_queue + kMessageQueueUsedOffset);
            const std::uint32_t message_array = address_space.read_u32(
                record.jut_queue + kMessageQueueArrayOffset);
            if (record.jut_queue_count != 0u &&
                record.jut_queue_count < 0x10000u &&
                record.jut_queue_used != 0u &&
                address_space.pointer_or_null(
                    message_array, record.jut_queue_count * 4u) != nullptr) {
                const std::uint32_t slot =
                    record.jut_queue_first % record.jut_queue_count;
                record.jut_queue_next_message = address_space.read_u32(
                    message_array + slot * sizeof(std::uint32_t));
            }
        }
    }
    record.xfb = xfb;
    record.xfb_valid = xfb >= 0x80000000u && xfb < 0x82000000u;
    if (record.xfb_valid) {
        record.buffer_count = address_space.read_u32(xfb + 0x10u);
        record.drawing = read_guest_s16(address_space, xfb + 0x14u);
        record.drawn = read_guest_s16(address_space, xfb + 0x16u);
        record.displaying = read_guest_s16(address_space, xfb + 0x18u);
        record.drawing_flag = address_space.read_u32(xfb + 0x1Cu);
        record.slot_count = static_cast<std::uint8_t>(
            std::min<std::uint32_t>(record.buffer_count, 3u));
        for (std::uint8_t slot = 0; slot < record.slot_count; ++slot) {
            record.slots[slot] = address_space.read_u32(
                xfb + static_cast<std::uint32_t>(slot) *
                    sizeof(std::uint32_t));
        }
    }
    record.framework = framework;
    record.framework_valid =
        framework >= 0x80000000u && framework < 0x82000000u;
    if (record.framework_valid) {
        record.retraces = read_guest_s16(address_space, framework + 0x10u);
        record.tick_duration = address_space.read_u32(framework + 0x14u);
        record.render_interval = address_space.read_u32(framework + 0x2Cu);
        record.render_counter = address_space.read_u32(framework + 0x30u);
        record.do_render = read_guest_u8(address_space, framework + 0x34u);
    }
    ++state.xfb_state_record_count;
}

void dump_xfb_state_trace(
    const RuntimeState& state,
    std::ostream& output) {
    if (!trace_xfb_state_enabled()) {
        return;
    }
    const std::size_t count = std::min(
        state.xfb_state_record_count, state.xfb_state_records.size());
    const std::size_t start =
        state.xfb_state_record_count >= state.xfb_state_records.size()
            ? state.xfb_state_record_count % state.xfb_state_records.size()
            : 0u;
    if (state.xfb_state_record_count > state.xfb_state_records.size()) {
        output << "[xfb-state] retained-last=" << count
               << " total-samples=" << state.xfb_state_record_count
               << " dropped="
               << (state.xfb_state_record_count - count) << '\n';
    }
    for (std::size_t index = 0; index < count; ++index) {
        const RuntimeState::XfbStateRecord& record = state.xfb_state_records[
            (start + index) % state.xfb_state_records.size()];
        output << "[xfb-state] vi=" << record.vi
               << " copySerial=" << record.copy_serial
               << " causalRenderFrame=" << record.causal_render_frame
               << " " << (record.phase != nullptr ? record.phase : "?")
               << " drawDone=" << static_cast<unsigned>(record.draw_done)
               << " peT=" << (record.pe_token_pending ? 1 : 0)
               << " peF=" << (record.pe_finish_pending ? 1 : 0)
               << " xfb=" << hexadecimal(record.xfb);
        if (record.xfb_valid) {
            output << " buffers=" << record.buffer_count
                   << " drawing=" << record.drawing
                   << " drawn=" << record.drawn
                   << " displaying=" << record.displaying
                   << " singleFlag=" << record.drawing_flag;
            for (std::uint8_t slot = 0; slot < record.slot_count; ++slot) {
                output << " slot" << static_cast<unsigned>(slot) << "="
                       << hexadecimal(record.slots[slot]);
            }
        }
        output << " framework=" << hexadecimal(record.framework);
        if (record.framework_valid) {
            output << " retraces=" << record.retraces
                   << " tickDur=" << record.tick_duration
                   << " renderInterval=" << record.render_interval
                   << " renderCounter=" << record.render_counter
                   << " doRender=" << static_cast<unsigned>(record.do_render);
        }
        output << " viCounter=" << record.vi_retrace_counter
               << " waitTarget=" << record.main_loop_wait_target
               << " waitInit=" <<
                    static_cast<unsigned>(record.main_loop_wait_initialized)
               << " jutVideo=" << hexadecimal(record.jut_video)
               << " jutVideoValid=" << (record.jut_video_valid ? 1 : 0);
        if (record.jut_queue_valid) {
            output << " jutQueue=" << hexadecimal(record.jut_queue)
                   << " jutQueueCount=" << record.jut_queue_count
                   << " jutQueueFirst=" << record.jut_queue_first
                   << " jutQueueUsed=" << record.jut_queue_used
                   << " jutQueueNext="
                   << record.jut_queue_next_message;
        }
        output << '\n';
    }
}

// This is deliberately an end-of-benchmark snapshot, not a live trace.  The
// JUTVideo callback and queue fields distinguish a guest that is legitimately
// idle from one whose retrace producer was never installed, without adding
// I/O or scheduler work to any realtime checkpoint.
bool benchmark_guest_state_enabled() {
    static const bool enabled =
        read_env_flag("GALAXY_BENCHMARK_GUEST_STATE", false);
    return enabled;
}

// The Bluetooth/WPAD dump is intentionally benchmark-end-only.  The full
// controller state is useful when the game stops producing frames, but walking
// its guest queues while they are live would perturb the exact VI cadence that
// this runtime is required to preserve.
bool benchmark_bluetooth_state_enabled() {
    static const bool enabled =
        read_env_flag("GALAXY_BENCHMARK_BLUETOOTH_STATE", false);
    return enabled;
}

// This deliberately reports only after the benchmark interval. The counters
// are maintained by the native BT/HID producer and its IOS delivery boundary;
// they prove transport activity without making any claim about which game UI
// subsequently consumed an input.
bool benchmark_virtual_input_state_enabled() {
    static const bool enabled =
        read_env_flag("GALAXY_BENCHMARK_INPUT_STATE", false);
    return enabled;
}

void dump_benchmark_virtual_input_state(
    std::ostream& output,
    const galaxy::host::GuestAddressSpace& address_space) {
    const galaxy::host::VirtualWiimoteInputBenchmarkStats& stats =
        address_space.native_virtual_input_benchmark_stats();
    output << "[benchmark-input-state] enabled=" << (stats.enabled ? 1u : 0u)
           << " produced=" << stats.produced_reports
           << " delivered=" << stats.delivered_reports
           << " replay-produced=" << stats.replay_produced_reports
           << " replay-delivered=" << stats.replay_delivered_reports
           << " active-buttons-produced="
           << stats.active_button_produced_reports
           << " active-buttons-delivered="
           << stats.active_button_delivered_reports
           << " a-produced=" << stats.a_button_produced_reports
           << " a-delivered=" << stats.a_button_delivered_reports
           << " ir-produced=" << stats.ir_active_produced_reports
           << " ir-delivered=" << stats.ir_active_delivered_reports
           << " nunchuk-produced=" << stats.nunchuk_active_produced_reports
           << " nunchuk-delivered=" << stats.nunchuk_active_delivered_reports
           << " saw-buttons=" << (stats.saw_active_buttons ? 1u : 0u)
           << " saw-a=" << (stats.saw_a_button ? 1u : 0u)
           << " saw-ir=" << (stats.saw_ir_active ? 1u : 0u)
           << " saw-nunchuk=" << (stats.saw_nunchuk_active ? 1u : 0u)
           << " last-produced-vi=" << stats.last_produced_vi
           << " last-delivered-vi=" << stats.last_delivered_vi
           << " last-produced-buttons="
           << hexadecimal(stats.last_produced_buttons)
           << " last-delivered-buttons="
           << hexadecimal(stats.last_delivered_buttons)
           << " last-report=" << hexadecimal(stats.last_report_mode) << '\n';
}

RuntimeState::BenchmarkGuestStateSnapshot capture_benchmark_guest_state(
    const RuntimeState& state) {
    RuntimeState::BenchmarkGuestStateSnapshot snapshot{};
    snapshot.vi = state.vi_retrace_count;
    snapshot.xfb_copy_serial = galaxy::gx::xfb_copy_count();
    if (state.address_space == nullptr) {
        return snapshot;
    }

    const auto& address_space = *state.address_space;
    const auto read_u32_if_mapped = [&address_space](std::uint32_t address) {
        return address_space.pointer_or_null(address, 4u) != nullptr
            ? address_space.read_u32(address)
            : 0u;
    };
    constexpr std::uint32_t kCurrentContextAddress = 0x800000D4u;
    constexpr std::uint32_t kCurrentThreadAddress = 0x800000E4u;
    constexpr std::uint32_t kInterruptHandlerTable = 0x80003040u;
    constexpr std::uint32_t kViInterrupt = 24u;
    constexpr std::uint32_t kRunQueueBitsAddress = 0x806A2D30u;
    constexpr std::uint32_t kJutVideoManagerPtr = 0x806A2850u;
    constexpr std::uint32_t kJutXfbManagerPtr = 0x806A2868u;
    constexpr std::uint32_t kMainLoopFrameworkManagerPtr = 0x806A2500u;
    constexpr std::uint32_t kViPreRetraceCallback = 0x806A2E54u;
    constexpr std::uint32_t kViPostRetraceCallback = 0x806A2E58u;

    snapshot.available = true;
    snapshot.current_context =
        read_u32_if_mapped(kCurrentContextAddress);
    snapshot.current_thread = read_u32_if_mapped(kCurrentThreadAddress);
    snapshot.current_context_mapped =
        address_space.pointer_or_null(
            snapshot.current_context, kGuestOsContextBytes) != nullptr;
    const auto saved_context_word =
        [&read_u32_if_mapped, &snapshot](
            std::uint32_t offset) {
            return snapshot.current_context_mapped
                ? read_u32_if_mapped(snapshot.current_context + offset)
                : 0u;
        };
    snapshot.saved_r1 = saved_context_word(0x04u);
    snapshot.saved_r3 = saved_context_word(0x0Cu);
    snapshot.saved_r4 = saved_context_word(0x10u);
    snapshot.saved_r5 = saved_context_word(0x14u);
    snapshot.saved_r6 = saved_context_word(0x18u);
    snapshot.saved_r12 = saved_context_word(0x30u);
    snapshot.saved_r29 = saved_context_word(0x74u);
    snapshot.saved_r30 = saved_context_word(0x78u);
    snapshot.saved_r31 = saved_context_word(0x7Cu);
    snapshot.saved_cr = saved_context_word(0x80u);
    snapshot.saved_lr = saved_context_word(0x84u);
    snapshot.saved_ctr = saved_context_word(0x88u);
    snapshot.saved_xer = saved_context_word(0x8Cu);
    snapshot.saved_srr0 = saved_context_word(0x198u);
    snapshot.runbits = read_u32_if_mapped(kRunQueueBitsAddress);
    snapshot.irq24_handler = read_u32_if_mapped(
        kInterruptHandlerTable + kViInterrupt * 4u);
    snapshot.vi_pre_callback = read_u32_if_mapped(kViPreRetraceCallback);
    snapshot.vi_post_callback = read_u32_if_mapped(kViPostRetraceCallback);
    snapshot.jut_video = read_u32_if_mapped(kJutVideoManagerPtr);
    snapshot.jut_video_mapped =
        address_space.pointer_or_null(snapshot.jut_video, 0x3Cu) != nullptr;
    snapshot.jut_callback = snapshot.jut_video_mapped
        ? read_u32_if_mapped(snapshot.jut_video + 0x28u)
        : 0u;
    snapshot.jut_queue = snapshot.jut_video_mapped
        ? snapshot.jut_video + 0x38u
        : 0u;
    snapshot.jut_queue_mapped =
        address_space.pointer_or_null(snapshot.jut_queue, 0x20u) != nullptr;
    snapshot.jut_queue_count = snapshot.jut_queue_mapped
        ? read_u32_if_mapped(snapshot.jut_queue + 0x14u)
        : 0u;
    snapshot.jut_queue_first = snapshot.jut_queue_mapped
        ? read_u32_if_mapped(snapshot.jut_queue + 0x18u)
        : 0u;
    snapshot.jut_queue_used = snapshot.jut_queue_mapped
        ? read_u32_if_mapped(snapshot.jut_queue + 0x1Cu)
        : 0u;
    snapshot.jut_queue_send_head = snapshot.jut_queue_mapped
        ? read_u32_if_mapped(snapshot.jut_queue)
        : 0u;
    snapshot.jut_queue_receive_head = snapshot.jut_queue_mapped
        ? read_u32_if_mapped(snapshot.jut_queue + 0x08u)
        : 0u;
    snapshot.jut_queue_receive_head_mapped = address_space.pointer_or_null(
        snapshot.jut_queue_receive_head, 0x2D0u) != nullptr;
    snapshot.jut_queue_receive_thread_state =
        snapshot.jut_queue_receive_head_mapped
        ? (read_u32_if_mapped(snapshot.jut_queue_receive_head + 0x2C8u) >> 16u)
        : 0u;
    snapshot.jut_queue_receive_thread_srr0 =
        snapshot.jut_queue_receive_head_mapped
        ? read_u32_if_mapped(snapshot.jut_queue_receive_head + 0x198u)
        : 0u;
    snapshot.jut_queue_receive_thread_queue =
        snapshot.jut_queue_receive_head_mapped
        ? read_u32_if_mapped(snapshot.jut_queue_receive_head + 0x2DCu)
        : 0u;
    snapshot.xfb_manager = read_u32_if_mapped(kJutXfbManagerPtr);
    snapshot.framework = read_u32_if_mapped(kMainLoopFrameworkManagerPtr);
    return snapshot;
}

