[[nodiscard]] bool guest_set_current_context_is_valid(
    galaxy::scheduler::GuestSetCurrentContextDisposition disposition) {
    using Disposition =
        galaxy::scheduler::GuestSetCurrentContextDisposition;
    switch (disposition) {
        case Disposition::ValidTemporaryInstall:
        case Disposition::ValidTemporaryRestore:
        case Disposition::ValidFatalContext:
        case Disposition::ValidBootstrapThread:
        case Disposition::ValidSchedulerIdle:
        case Disposition::ValidSchedulerThread:
            return true;
        default:
            return false;
    }
}

enum class GuestSetCurrentContextCommit : std::uint8_t {
    None,
    Push,
    Pop,
};

struct PreparedGuestSetCurrentContext {
    bool active{};
    GuestSetCurrentContextCommit commit{};
    galaxy::scheduler::GuestSetCurrentContextToken token{};
    std::uint32_t requested_context{};
    std::uint32_t return_lr{};
};

PreparedGuestSetCurrentContext prepare_guest_set_current_context(
    RuntimeState& state,
    galaxy::GuestMemoryV1* memory,
    const galaxy::PpcContext& executing_context) {
    if (state.address_space == nullptr || state.services == nullptr ||
        memory == nullptr) {
        throw RuntimeFailure(
            "OSSetCurrentContext validation lacks initialized state");
    }

    constexpr std::uint32_t kCurrentPhysicalContextAddress = 0x800000C0u;
    constexpr std::uint32_t kCurrentContextAddress = 0x800000D4u;
    constexpr std::uint32_t kCurrentThreadAddress = 0x800000E4u;
    constexpr std::uint32_t kThreadStateOffset = 0x2C8u;
    constexpr std::uint32_t kOsThreadBytes = 0x30Cu;
    const std::uint32_t requested_context = executing_context.gpr[3];
    const std::uint32_t current_context =
        state.address_space->read_u32(kCurrentContextAddress);
    const std::uint32_t physical_context =
        state.address_space->read_u32(kCurrentPhysicalContextAddress);
    const std::uint32_t current_thread =
        state.address_space->read_u32(kCurrentThreadAddress);
    const bool requested_context_is_mapped =
        valid_guest_os_context(state.address_space, requested_context);
    const bool current_context_is_mapped =
        valid_guest_os_context(state.address_space, current_context);
    const bool current_thread_is_mapped = mapped_guest_range(
        state.address_space, current_thread, kOsThreadBytes);
    const bool current_thread_is_active =
        current_thread_is_mapped && guest_context_is_active_thread_base(
            state.address_space, current_thread);
    const std::uint16_t current_thread_state = current_thread_is_mapped
        ? galaxy::guest_load_u16(
              memory,
              current_thread + kThreadStateOffset,
              state.services,
              executing_context.pc)
        : 0u;
    const auto* pending = g_pending_os_set_current_contexts.top();
    const galaxy::scheduler::GuestSetCurrentContextEvidence evidence{
        executing_context.lr,
        requested_context,
        current_context,
        physical_context,
        current_thread,
        executing_context.gpr[1],
        current_thread_state,
        requested_context_is_mapped,
        current_context_is_mapped,
        current_thread_is_mapped,
        current_thread_is_active,
        g_pending_os_set_current_contexts.full()};
    const auto disposition =
        galaxy::scheduler::classify_guest_set_current_context(
            evidence, pending);
    if (!guest_set_current_context_is_valid(disposition)) {
        std::ostringstream message;
        message << "OSSetCurrentContext invariant failed"
                << " reason=" << guest_set_current_context_reason(disposition)
                << " lr=" << hexadecimal(executing_context.lr)
                << " requested=" << hexadecimal(requested_context)
                << " D4=" << hexadecimal(current_context)
                << " C0=" << hexadecimal(physical_context)
                << " E4=" << hexadecimal(current_thread)
                << " r1=" << hexadecimal(executing_context.gpr[1])
                << " thread-state=" << current_thread_state
                << " token-depth="
                << g_pending_os_set_current_contexts.size()
                << " token-temp="
                << hexadecimal(
                       pending != nullptr ? pending->temporary_context : 0u)
                << " token-prev="
                << hexadecimal(
                       pending != nullptr ? pending->previous_context : 0u)
                << " pc=" << hexadecimal(executing_context.pc);
        throw RuntimeFailure(message.str());
    }

    const auto* role =
        galaxy::scheduler::find_guest_set_current_context_role(
            executing_context.lr);
    if (role == nullptr) {
        throw RuntimeFailure(
            "OSSetCurrentContext valid disposition lacks an exact role");
    }
    PreparedGuestSetCurrentContext prepared{
        true,
        GuestSetCurrentContextCommit::None,
        {},
        requested_context,
        executing_context.lr};
    if (role->kind ==
        galaxy::scheduler::GuestSetCurrentContextRoleKind::
            TemporaryInstall) {
        prepared.commit = GuestSetCurrentContextCommit::Push;
        prepared.token = galaxy::scheduler::GuestSetCurrentContextToken{
            requested_context,
            current_context,
            executing_context.lr,
            role->paired_return_lr};
    } else if (role->kind ==
               galaxy::scheduler::GuestSetCurrentContextRoleKind::
                   TemporaryRestore) {
        if (pending == nullptr) {
            throw RuntimeFailure(
                "OSSetCurrentContext valid restore lacks a pending token");
        }
        prepared.commit = GuestSetCurrentContextCommit::Pop;
        prepared.token = *pending;
    }
    return prepared;
}

void commit_guest_set_current_context(
    RuntimeState& state,
    const galaxy::PpcContext& executing_context,
    const PreparedGuestSetCurrentContext& prepared) {
    if (!prepared.active) {
        return;
    }
    if (state.address_space == nullptr) {
        throw RuntimeFailure(
            "OSSetCurrentContext commit lacks initialized address space");
    }

    constexpr std::uint32_t kCurrentPhysicalContextAddress = 0x800000C0u;
    constexpr std::uint32_t kCurrentContextAddress = 0x800000D4u;
    const std::uint32_t installed_context =
        state.address_space->read_u32(kCurrentContextAddress);
    const std::uint32_t installed_physical =
        state.address_space->read_u32(kCurrentPhysicalContextAddress);
    if (executing_context.gpr[3] != prepared.requested_context ||
        installed_context != prepared.requested_context ||
        installed_physical !=
            (prepared.requested_context & 0x3FFFFFFFu)) {
        throw RuntimeFailure(
            "translated OSSetCurrentContext violated its exact write contract"
            " lr=" + hexadecimal(prepared.return_lr) +
            " requested=" + hexadecimal(prepared.requested_context) +
            " r3=" + hexadecimal(executing_context.gpr[3]) +
            " D4=" + hexadecimal(installed_context) +
            " C0=" + hexadecimal(installed_physical));
    }

    switch (prepared.commit) {
        case GuestSetCurrentContextCommit::None:
            return;
        case GuestSetCurrentContextCommit::Push:
            if (!g_pending_os_set_current_contexts.push(prepared.token)) {
                throw RuntimeFailure(
                    "OSSetCurrentContext token stack overflow after validated "
                    "install lr=" + hexadecimal(prepared.return_lr));
            }
            return;
        case GuestSetCurrentContextCommit::Pop:
            if (!g_pending_os_set_current_contexts.consume_exact(
                    prepared.token)) {
                throw RuntimeFailure(
                    "OSSetCurrentContext lost exact restore ownership lr=" +
                    hexadecimal(prepared.return_lr));
            }
            return;
    }
}

bool guest_context_r1_cross_thread(
    galaxy::GuestMemoryV1* memory,
    const galaxy::NativeServicesV1* services,
    std::uint32_t guest_context,
    std::uint32_t r1,
    std::uint32_t& owner_thread) {
    // Only thread-base contexts have a defined stack; stack-allocated
    // exception OSContexts (e.g. __DSPHandler's 0x807AC9xx frame ctx) save
    // their own thread's r1 and must not be flagged.
    std::uint32_t stack_base = 0u;
    std::uint32_t stack_end = 0u;
    if (!guest_thread_stack_bounds(
            memory, services, guest_context, stack_base, stack_end)) {
        return false;
    }
    if (r1 >= stack_end && r1 <= stack_base) {
        return false;  // r1 inside the thread's own stack
    }
    owner_thread = guest_r1_owner_thread(memory, services, r1);
    return owner_thread != 0u && owner_thread != guest_context;
}

void save_exception_context(
    const galaxy::PpcContext& context,
    std::uint32_t resume_address,
    std::uint32_t guest_context,
    galaxy::GuestMemoryV1* memory,
    const galaxy::NativeServicesV1* services) {
    {
        std::uint32_t owner_thread = 0u;
        if (guest_context_r1_cross_thread(
                memory, services, guest_context, context.gpr[1],
                owner_thread)) {
            static std::uint64_t s_poison_save_logs = 0;
            if (++s_poison_save_logs <= 256u) {
                std::cerr << "[ctx-poison-save] #" << s_poison_save_logs
                          << " ctx=" << hexadecimal(guest_context)
                          << " r1=" << hexadecimal(context.gpr[1])
                          << " r1-owner=" << hexadecimal(owner_thread)
                          << " srr0=" << hexadecimal(resume_address)
                          << " lr=" << hexadecimal(context.lr)
                          << " pc=" << hexadecimal(context.pc)
                          << " curCtx=" << hexadecimal(galaxy::guest_load_u32(
                                 memory, 0x800000D4u, services, 0u))
                          << " curThr=" << hexadecimal(galaxy::guest_load_u32(
                                 memory, 0x800000E4u, services, 0u))
                          << '\n';
            }
        }
    }
    galaxy::interrupt::save_low_memory_exception_vector_context(
        context,
        resume_address,
        guest_context,
        memory,
        services);
}

void publish_decrementer_deadline_arm(
    RuntimeState& state,
    galaxy::timing::DecrementerDeadlineArm arm) {
    if (state.deadline_broker == nullptr) {
        throw RuntimeFailure(
            "decrementer armed without a native deadline broker");
    }
    try {
        state.deadline_broker->replace_once(
            galaxy::timing::EventKind::Decrementer,
            arm.deadline_ticks,
            arm.generation);
    } catch (const std::exception& error) {
        throw RuntimeFailure(
            std::string("decrementer deadline arm failed: ") +
            error.what());
    }
}

bool consume_decrementer_deadline_publication(RuntimeState& state) {
    using ReplaceableTakeStatus =
        galaxy::timing::PendingEventLatch::ReplaceableTakeStatus;
    const auto kind = galaxy::timing::EventKind::Decrementer;
    const std::uint64_t published_generation =
        state.deadline_events.pending_replaceable_generation(kind);
    if (published_generation == 0u) {
        return false;
    }
    const auto expected_arm = state.decrementer_deadline.arm();
    if (!expected_arm.has_value()) {
        throw RuntimeFailure(
            "decrementer deadline published before tracker initialization");
    }

    const auto take = state.deadline_events.take_replaceable(
        kind, expected_arm->generation);
    switch (take.status) {
        case ReplaceableTakeStatus::Empty:
            return false;
        case ReplaceableTakeStatus::Stale:
            // Replacement normally clears an older edge while holding the
            // broker mutex.  If one was already observed, discarding it cannot
            // advance the newer counter generation.
            return false;
        case ReplaceableTakeStatus::Future:
            throw RuntimeFailure(
                "decrementer deadline publication is newer than tracker state");
        case ReplaceableTakeStatus::Taken:
            break;
    }

    const std::uint64_t host_pause_recoveries_before_sample =
        state.host_pause_recoveries;
    const std::uint64_t now_ticks = runtime_time_base_ticks(state);
    // runtime_time_base_ticks may complete a verified host-suspension recovery
    // after the publication was taken above.  That transaction restores this
    // exact arm and clears all pre-rebase latch state while the broker worker is
    // serialized.  The taken edge was therefore produced on discarded host
    // time; applying it to rebased guest time would be an early DEC transition.
    // Return through synchronize_decrementer_deadline so its immutable-arm
    // fallback settles a genuinely due edge immediately, or the restored
    // broker arm republishes it at the correct guest-time boundary.
    if (state.host_pause_recoveries != host_pause_recoveries_before_sample) {
        const auto restored_arm = state.decrementer_deadline.arm();
        if (!restored_arm.has_value() || *restored_arm != *expected_arm) {
            throw RuntimeFailure(
                "host-suspension recovery changed the active decrementer arm");
        }
        if (state.decrementer_deadline_rebase_discards ==
            std::numeric_limits<std::uint64_t>::max()) {
            throw RuntimeFailure(
                "decrementer rebase-discard audit counter overflowed");
        }
        ++state.decrementer_deadline_rebase_discards;
        return false;
    }
    galaxy::timing::DecrementerDeadlineArm next_arm{};
    try {
        next_arm = state.decrementer_deadline.on_deadline(
            now_ticks, take.observed_generation);
    } catch (const std::exception& error) {
        throw RuntimeFailure(
            std::string("decrementer deadline publication failed audit: ") +
            error.what());
    }
    ++state.decrementer_deadline_publications;
    const std::uint64_t lateness = now_ticks - expected_arm->deadline_ticks;
    ++state.decrementer_deadline_settled_events;
    state.decrementer_deadline_total_lateness_ticks += lateness;
    if (lateness != 0u) {
        ++state.decrementer_deadline_late_events;
        state.decrementer_deadline_max_lateness_ticks =
            std::max(
                state.decrementer_deadline_max_lateness_ticks,
                lateness);
    }
    publish_decrementer_deadline_arm(state, next_arm);
    return true;
}

// DeadlineBroker is the wakeup authority, not the timer's semantic storage.
// A forced mtmsr/RFI/DEC-write boundary can reach the CPU thread after the
// absolute edge but before the worker publishes it; settle that exact edge
// from its immutable arm rather than delaying or dropping the request.
bool synchronize_decrementer_deadline(RuntimeState& state) {
    if (consume_decrementer_deadline_publication(state)) {
        return true;
    }
    const auto arm = state.decrementer_deadline.arm();
    if (!arm.has_value()) {
        return false;
    }
    const std::uint64_t now_ticks = runtime_time_base_ticks(state);
    if (now_ticks < arm->deadline_ticks) {
        return false;
    }

    galaxy::timing::DecrementerDeadlineArm next_arm{};
    try {
        next_arm = state.decrementer_deadline.on_deadline(
            now_ticks, arm->generation);
    } catch (const std::exception& error) {
        throw RuntimeFailure(
            std::string("decrementer deadline fallback failed audit: ") +
            error.what());
    }
    ++state.decrementer_deadline_fallbacks;
    const std::uint64_t lateness = now_ticks - arm->deadline_ticks;
    ++state.decrementer_deadline_settled_events;
    state.decrementer_deadline_total_lateness_ticks += lateness;
    if (lateness != 0u) {
        ++state.decrementer_deadline_late_events;
    }
    state.decrementer_deadline_max_lateness_ticks = std::max(
        state.decrementer_deadline_max_lateness_ticks,
        lateness);
    publish_decrementer_deadline_arm(state, next_arm);
    return true;
}

bool decrementer_needs_dispatch(
    const RuntimeState& state,
    const galaxy::PpcContext* context) {
    return context != nullptr &&
        state.decrementer_deadline.pending_request() &&
        guest_external_interrupts_enabled(context);
}

// Advance every non-VI device with EE temporarily masked, then restore the
// exact guest MSR and expose VI before DEC. This makes the translated external
// dispatcher, rather than host call order, choose among simultaneously latched
// PI sources. A due VI edge whose broker publication is still in flight blocks
// DEC until that immutable edge is published and consumed.
bool arbitrate_external_before_decrementer(
    RuntimeState& state,
    std::uint32_t resume_address,
    galaxy::PpcContext* context,
    galaxy::GuestMemoryV1* memory) {
    if (context == nullptr || memory == nullptr || state.services == nullptr ||
        state.address_space == nullptr) {
        throw RuntimeFailure(
            "external/decrementer arbitration lacks initialized native state");
    }
    if (!guest_external_interrupts_enabled(context)) {
        return false;
    }

    {
        const std::uint32_t saved_msr = context->msr;
        const galaxy::ScopeExit restore_msr([&]() noexcept {
            context->msr = saved_msr;
        });
        context->msr &= ~kMsrExternalInterruptEnable;
        service_native_input_with_ai_deadline_priority(
            state, context, memory, resume_address);
        dispatch_ipc_interrupt(state, context, memory, resume_address);
        if (state.address_space->pe_finish_pending() ||
            state.address_space->pe_token_pending() ||
            (sim_thread_pe_scan_enabled() &&
             state.address_space->gx_fifo_pe_scan_pending(
                 state.pe_scanned_fifo_bytes))) {
            dispatch_pe_interrupts(state, context, memory, resume_address);
        }
        dispatch_dsp_interface_interrupts(
            state, context, memory, resume_address);
    }

    bool force_due_vi_publication = false;
    bool vi_blocks_decrementer = false;
    if (state.vi_deadline_consumer != nullptr) {
        const auto observation = state.vi_deadline_consumer->inspect(
            state.deadline_events,
            galaxy::timing::EventKind::VideoInterface,
            runtime_time_base_ticks(state));
        force_due_vi_publication =
            observation.status ==
            galaxy::timing::PeriodicConsumeStatus::AwaitingPublication;
        // wait_for_exact_vi_deadline owns publication waiting. Re-entering its
        // force path would recurse; its latest exact sample instead decides
        // whether DEC was eligible before the VI edge.
        if (state.vi_deadline_wait_active &&
            observation.status !=
                galaxy::timing::PeriodicConsumeStatus::NotDue) {
            vi_blocks_decrementer = true;
        }
    }

    if (!state.vi_deadline_wait_active) {
        (void)dispatch_vi_retrace(
            state,
            context,
            memory,
            /*force=*/force_due_vi_publication,
            /*idle_ee_override=*/false,
            resume_address);
    }
    if (dispatch_external_interrupt(
            state, resume_address, context, memory)) {
        return true;
    }

    // A broker publication can become due while the non-VI/VI work above is
    // running. Sample once more immediately before DEC acceptance. NotDue is
    // the only state in which no VI edge has architectural priority.
    if (state.vi_deadline_consumer != nullptr) {
        const auto final_observation = state.vi_deadline_consumer->inspect(
            state.deadline_events,
            galaxy::timing::EventKind::VideoInterface,
            runtime_time_base_ticks(state));
        if (final_observation.status !=
            galaxy::timing::PeriodicConsumeStatus::NotDue) {
            vi_blocks_decrementer = true;
        }
    }
    return vi_blocks_decrementer;
}

void dispatch_decrementer(
    RuntimeState& state,
    std::uint32_t resume_address,
    galaxy::PpcContext* context,
    galaxy::GuestMemoryV1* memory) {
    constexpr std::uint32_t kCurrentContextAddress = 0x800000D4u;
    constexpr auto kEntry = galaxy::interrupt::kDecrementerExceptionEntry;

    if (context == nullptr || memory == nullptr || state.services == nullptr) {
        throw RuntimeFailure(
            "decrementer arbitration lacks initialized context/memory/services");
    }
    (void)synchronize_decrementer_deadline(state);
    if (!decrementer_needs_dispatch(state, context)) {
        return;
    }
    if (arbitrate_external_before_decrementer(
            state, resume_address, context, memory) ||
        !decrementer_needs_dispatch(state, context)) {
        return;
    }

    // At this point DEC is pending, EE is enabled, and all higher-priority
    // external sources have been arbitrated. The existing flat-transfer model
    // cannot yet preserve a live outer exception/selected-handler scope across
    // this nested asynchronous RFI, so reject before consuming the request or
    // saving any architectural state. Clean target proofs must keep this zero.
    if (state.dispatching_external_interrupt ||
        state.dispatching_decrementer ||
        state.dispatching_fpu_unavailable ||
        state.external_dispatch.active()) {
        ++state.nested_async_acceptance_count;
        const std::uint32_t current_context =
            state.address_space != nullptr
            ? state.address_space->read_u32(kCurrentContextAddress)
            : 0u;
        throw RuntimeFailure(
            "eligible decrementer reached an unsupported nested asynchronous "
            "acceptance boundary"
            " resume=" + hexadecimal(resume_address) +
            " msr=" + hexadecimal(context->msr) +
            " current-context=" + hexadecimal(current_context) +
            " outer-external=" +
                std::to_string(
                    state.dispatching_external_interrupt ? 1u : 0u) +
            " outer-decrementer=" +
                std::to_string(state.dispatching_decrementer ? 1u : 0u) +
            " outer-fpu=" +
                std::to_string(
                    state.dispatching_fpu_unavailable ? 1u : 0u) +
            " outer-external-record=" +
                std::to_string(
                    state.external_dispatch.active() ? 1u : 0u));
    }

    const std::uint32_t handler = galaxy::guest_load_u32(
        memory,
        galaxy::interrupt::kExceptionHandlerTable +
            kEntry.exception * sizeof(std::uint32_t),
        state.services,
        resume_address);
    const std::uint32_t interrupted_context = galaxy::guest_load_u32(
        memory,
        kCurrentContextAddress,
        state.services,
        resume_address);
    if (handler == 0 || interrupted_context == 0) {
        throw RuntimeFailure(
            "decrementer request became deliverable without an installed "
            "translated handler/current OSContext"
            " handler=" + hexadecimal(handler) +
            " context=" + hexadecimal(interrupted_context));
    }
    if (handler != kEntry.wrapper) {
        throw RuntimeFailure(
            "decrementer exception table does not name RMGE01's exact "
            "translated wrapper: expected=" + hexadecimal(kEntry.wrapper) +
            " installed=" + hexadecimal(handler));
    }

    // The request remains level-latched across DEC writes and EE-masked
    // execution.  Acknowledge it only after the translated exception has been
    // proven deliverable at this exact instruction boundary.
    if (!state.decrementer_deadline.take_pending_request()) {
        throw RuntimeFailure(
            "decrementer dispatch lost its pending architectural request");
    }

    validate_guest_exception_identity(
        state,
        memory,
        *context,
        interrupted_context,
        resume_address,
        "decrementer");
    save_exception_context(
        *context,
        resume_address,
        interrupted_context,
        memory,
        state.services);
    // NOTE: the former SRR0-skip hack for 0x804A8A0C / 0x80415610 is gone.
    // 0x804A8A0C is the loop branch inside OSReceiveMessage; skipping it with
    // usedCount==0 made the queue indices go negative and handed the caller a
    // garbage message.  Wait resolution is now done legally by the OS
    // Synchronization & Event Pump subsystem (see on_guest_sleep_thread).
    ++state.decrementer_count;
    if (trace_decrementer() && state.decrementer_count <= 8u) {
        const std::uint64_t now_ticks = runtime_time_base_ticks(state);
        const std::uint64_t elapsed =
            now_ticks - context->decrementer_start_ticks;
        std::cout << "[dec] pending " << state.decrementer_count
                  << " value=" << context->decrementer_start_value
                  << " elapsed=" << elapsed << '\n';
        if (state.address_space != nullptr) {
            constexpr std::uint32_t kAlarmQueueHead = 0x806A2CB0u;
            const std::uint32_t alarm =
                state.address_space->read_u32(kAlarmQueueHead);
            if (alarm != 0) {
                const std::uint32_t fire_high =
                    state.address_space->read_u32(alarm + 0x08u);
                const std::uint32_t fire_low =
                    state.address_space->read_u32(alarm + 0x0Cu);
                const std::uint32_t alarm_handler =
                    state.address_space->read_u32(alarm + 0x00u);
                const std::uint32_t next =
                    state.address_space->read_u32(alarm + 0x14u);
                const std::uint32_t period_high =
                    state.address_space->read_u32(alarm + 0x18u);
                const std::uint32_t period_low =
                    state.address_space->read_u32(alarm + 0x1Cu);
                const std::uint64_t system_time_offset =
                    static_cast<std::uint64_t>(
                        state.address_space->read_u32(0x800030D8u))
                        << 32 |
                    state.address_space->read_u32(0x800030DCu);
                const std::uint64_t system_time =
                    system_time_offset +
                    galaxy::read_time_base(
                        context, state.services, resume_address);
                const std::uint32_t start_high =
                    state.address_space->read_u32(alarm + 0x20u);
                const std::uint32_t start_low =
                    state.address_space->read_u32(alarm + 0x24u);
                std::cout << "[alarm] head=" << hexadecimal(alarm)
                          << " handler=" << hexadecimal(alarm_handler)
                          << " fire=" << hexadecimal(fire_high) << ':'
                          << hexadecimal(fire_low)
                          << " now="
                          << hexadecimal(
                                 static_cast<std::uint32_t>(system_time >> 32))
                          << ':'
                          << hexadecimal(
                                 static_cast<std::uint32_t>(system_time))
                          << " period=" << hexadecimal(period_high) << ':'
                          << hexadecimal(period_low)
                          << " start=" << hexadecimal(start_high) << ':'
                          << hexadecimal(start_low)
                          << " next=" << hexadecimal(next) << '\n';
            }
        }
    }
    if (trace_decrementer() && state.decrementer_count <= 4u) {
        std::cout << "[dec] entering translated exception wrapper "
                  << hexadecimal(handler) << '\n';
    }
    try {
        run_translated_exception_wrapper(
            state,
            context,
            memory,
            kEntry,
            interrupted_context,
            state.dispatching_decrementer);
    } catch (...) {
        // A successful translated RFI exits through GuestTransfer, so this is
        // also the normal decrementer completion edge. Service only a real
        // broker publication and retain its exact batch identity before the
        // non-local transfer resumes another guest context.
        if (state.deadline_events.pending(
                galaxy::timing::EventKind::InputReport) != 0u) {
            service_native_input_with_ai_deadline_priority(
                state, context, memory, resume_address);
        }
        throw;
    }
}

void on_decrementer_written(
    void* user,
    std::uint32_t guest_pc,
    std::uint32_t resume_pc,
    std::uint64_t write_ticks,
    std::uint32_t previous_value,
    galaxy::PpcContext* context,
    galaxy::GuestMemoryV1* memory) {
    auto& state = *static_cast<RuntimeState*>(user);
    if (context == nullptr || memory == nullptr ||
        !state.decrementer_deadline.initialized()) {
        throw RuntimeFailure(
            "statically translated DEC write lacks initialized native state at " +
            hexadecimal(guest_pc));
    }
    if (context->decrementer_start_ticks != write_ticks) {
        throw RuntimeFailure(
            "translated DEC write and native callback disagree on write tick");
    }

    std::uint32_t tracked_previous = 0u;
    try {
        tracked_previous =
            state.decrementer_deadline.current_value(write_ticks);
    } catch (const std::exception& error) {
        throw RuntimeFailure(
            std::string("DEC write previous-value audit failed: ") +
            error.what());
    }
    if (tracked_previous != previous_value) {
        throw RuntimeFailure(
            "translated DEC register diverged from native deadline tracker"
            " translated=" + hexadecimal(previous_value) +
            " native=" + hexadecimal(tracked_previous));
    }

    const auto previous_arm = state.decrementer_deadline.arm();
    if (previous_arm.has_value() &&
        write_ticks >= previous_arm->deadline_ticks) {
        ++state.decrementer_write_due_races;
    }
    galaxy::timing::DecrementerDeadlineArm next_arm{};
    try {
        // This must precede broker replacement: on_write latches an old edge
        // already due at write_ticks, whereas replace_once clears the old
        // generation's wake payload under the broker mutex.
        next_arm = state.decrementer_deadline.on_write(
            write_ticks, context->decrementer_start_value);
    } catch (const std::exception& error) {
        throw RuntimeFailure(
            std::string("DEC write deadline replacement failed: ") +
            error.what());
    }
    publish_decrementer_deadline_arm(state, next_arm);
    ++state.decrementer_write_count;

    if (trace_decrementer() && state.decrementer_write_count <= 8u) {
        std::cout << "[dec] armed " << state.decrementer_write_count
                  << " pc=" << hexadecimal(guest_pc)
                  << " value=" << context->decrementer_start_value
                  << " raw-ticks=" << write_ticks
                  << " deadline=" << next_arm.deadline_ticks
                  << " generation=" << next_arm.generation
                  << " pending="
                  << (state.decrementer_deadline.pending_request() ? 1 : 0)
                  << '\n';
    }

    // DEC writes are context-synchronizing callbacks reached from inside the
    // translated timer/scheduler path. They provide a safe native boundary to
    // service an HID edge that crossed after the checkpoint's pre-DEC pass,
    // before another decrementer arbitration can extend that service gap.
    if (state.deadline_events.pending(
            galaxy::timing::EventKind::InputReport) != 0u) {
        service_native_input_with_ai_deadline_priority(
            state, context, memory, resume_pc);
    }
    dispatch_decrementer(state, resume_pc, context, memory);
}

void log_message(void* user, galaxy::LogLevelV1 level, const char* message) {
    if (capture_generated_jutvideo_mq_trace(user, level, message) ||
        capture_generated_main_frame_trace(user, level, message)) {
        return;
    }
    if (level < galaxy::LogLevelV1::Warning && !trace_runtime_scaffolding()) {
        return;
    }
    std::cout << "[module] " << (message != nullptr ? message : "(null)") << '\n';
}

[[noreturn]] void fatal_error(void*, std::uint32_t guest_pc, const char* message) {
    throw RuntimeFailure(
        "guest fault at " + hexadecimal(guest_pc) + ": " +
        (message != nullptr ? message : "(null)"));
}

// Both flat transfer and retained native continuation arbitrate at the same
// post-RFI edge, after all wrapper/checkpoint ownership guards have unwound.
void arbitrate_after_completed_rfi(RuntimeState& state, std::uint32_t address,
                                 galaxy::PpcContext* context, galaxy::GuestMemoryV1* memory) {
    state.record_vi_post_rfi_handoff("entry", address, context);
    (void)synchronize_decrementer_deadline(state);
    state.record_vi_post_rfi_handoff("after-decrementer-sync", address, context);
    if (guest_external_interrupts_enabled(context)) {
        const bool owned=arbitrate_external_before_decrementer(state,address,context,memory);
        state.record_vi_post_rfi_handoff("after-external-arbitration",address,context);
        if (!owned) {
            dispatch_decrementer(state,address,context,memory);
            state.record_vi_post_rfi_handoff("after-decrementer-dispatch",address,context);
        }
    }
}

void branch_checkpoint(void* user,std::uint32_t guest_pc,
                       galaxy::PpcContext* context,galaxy::GuestMemoryV1* memory);

void branch_checkpoint_retaining_same_context(
    void* user,std::uint32_t guest_pc,galaxy::PpcContext* context,galaxy::GuestMemoryV1* memory) {
    auto& state=*static_cast<RuntimeState*>(user);
    static const bool enabled=read_env_flag("GALAXY_CHECKPOINT_SAME_CONTEXT_RFI",false);
    if (!enabled || context==nullptr || memory==nullptr || state.address_space==nullptr ||
        state.checkpoint_rfi_proof!=nullptr || state.dispatching_external_interrupt ||
        state.dispatching_decrementer || state.dispatching_fpu_unavailable ||
        state.external_dispatch.active() || g_pending_os_load_context.pending()!=nullptr ||
        g_branch_checkpoint_callback_depth!=0u || guest_pc==0u ||
        galaxy::interrupt::checkpoint_native_helper_range(guest_pc) ||
        galaxy::is_native_input_trace_copy_pre_checkpoint_pc(guest_pc)) {
        branch_checkpoint(user,guest_pc,context,memory);
        return;
    }
    static const bool pending_only =
        read_env_flag("GALAXY_CHECKPOINT_SAME_CONTEXT_RFI_PENDING_ONLY", false);
    if (pending_only && state.deadline_events.mask() == 0u) {
        ++state.checkpoint_rfi_pending_empty_bypasses;
        // This only declines local RFI retention. The full callback still
        // samples clocks and handles all devices. An event published after
        // this observation follows ordinary flat unwind; no work is skipped.
        branch_checkpoint(user, guest_pc, context, memory);
        return;
    }
    ++state.checkpoint_rfi_proof_preparations;
    const auto interrupted_thread=state.address_space->read_u32(0x800000E4u);
    const auto interrupted_context=state.address_space->read_u32(0x800000D4u);
    const auto callback_depth=g_branch_checkpoint_callback_depth;
    const auto callback_pc=g_active_branch_checkpoint_pc;
    const auto full_depth=state.checkpoint_gate.full_scope_depth();
    const auto inline_depth=state.checkpoint_gate.inline_scope_depth();
    galaxy::interrupt::CheckpointRfiProof proof{
        context,interrupted_context,context->pc,g_live_ctx_stack.size(),interrupted_thread};
    struct Scope {
        RuntimeState& state;
        explicit Scope(RuntimeState& s,galaxy::interrupt::CheckpointRfiProof& p):state(s){state.checkpoint_rfi_proof=&p;}
        ~Scope(){state.checkpoint_rfi_proof=nullptr;}
    } scope(state,proof);
    try {
        branch_checkpoint(user,guest_pc,context,memory);
    } catch (const GuestTransfer& transfer) {
        ++state.checkpoint_rfi_caught;
        const bool source_ok=galaxy::interrupt::validated_checkpoint_rfi_source(
            transfer.loaded_context(),transfer.load_call_pc(),interrupted_context);
        // A branch/call instruction need not be an exported entry. The RFI
        // continuation is the exact statically translated resume identity.
        const bool site_ok=state.lookup_function(transfer.address())!=nullptr;
        const bool thread_ok=state.address_space->read_u32(0x800000E4u)==interrupted_thread;
        const bool scope_ok=g_branch_checkpoint_callback_depth==callback_depth &&
            g_active_branch_checkpoint_pc==callback_pc &&
            state.checkpoint_gate.full_scope_depth()==full_depth &&
            state.checkpoint_gate.inline_scope_depth()==inline_depth;
        state.checkpoint_rfi_bad_source+=!source_ok;
        state.checkpoint_rfi_unmapped_site+=!site_ok;
        state.checkpoint_rfi_changed_thread+=!thread_ok;
        state.checkpoint_rfi_changed_scope+=!scope_ok;
        const bool ownership_clear=source_ok && site_ok && thread_ok && scope_ok &&
            !state.dispatching_external_interrupt &&
            !state.dispatching_decrementer && !state.dispatching_fpu_unavailable &&
            !state.external_dispatch.active() && g_pending_os_load_context.pending()==nullptr;
        const auto mismatch=proof.mismatch(*context,transfer.address(),transfer.exception(),
                state.address_space->read_u32(0x800000D4u),
                state.address_space->read_u32(0x800000C0u),g_live_ctx_stack.size(),true,
                state.address_space->read_u32(0x800000E4u));
        ++state.checkpoint_rfi_mismatches[static_cast<std::size_t>(mismatch)];
        if (!ownership_clear || mismatch!=galaxy::interrupt::CheckpointRfiProof::Mismatch::None) {
            ++state.checkpoint_rfi_rejected;
            throw;
        }
        ++state.checkpoint_rfi_accepted;
        if (transfer.unwind_start_ns()!=0u) {
            const auto arrived=galaxy::cadence::steady_now_ns_if_enabled(state.cadence_diagnostics);
            if (arrived>=transfer.unwind_start_ns()) state.cadence_diagnostics->record_phase(
                galaxy::cadence::TimingPhase::GuestTransferUnwind,arrived-transfer.unwind_start_ns());
        }
        // New transfers during arbitration retain their ordinary flat fallback.
        state.checkpoint_rfi_proof=nullptr;
        arbitrate_after_completed_rfi(state,transfer.address(),context,memory);
    }
}

